var e=[{no:`01`,baslik:`Yangın Güvenlik Uzmanlığı (YGU) Eğitimi Nasıl Olacak? Yangın Güvenlik Uzmanı (YGU) Eğitim Rehberi`,ozet:`Yangın güvenliği, yalnızca yangın söndürme cihazlarının bulundurulması veya yangın algılama sistemlerinin kurulmasıyla sağlanamaz. Bir binanın mimari özellikleri, kullanım amacı, kaçış yolları, yangından korunma tesisatları ve işletme koşulları bir bütün olarak değerlendirilmelidir.`,bloklar:[{tip:`p`,metin:`Türkiye'de yangın güvenliğinin değerlendirilmesine yönelik düzenlemeler, Yangın Güvenlik Uzmanlığı (YGU) alanını önemli bir mesleki gündem haline getirmiştir.`},{tip:`p`,metin:`22 Mayıs 2026 tarihinde yayımlanan kanuni düzenleme, yangın güvenliği periyodik kontrolleri ve yetkilendirilecek Yangın Güvenlik Uzmanları (YGU) bakımından yeni bir çerçeve oluşturmuştur.`},{tip:`p`,metin:`Bu gelişmeyle birlikte Yangın Güvenlik Uzmanlığı (YGU) eğitimi, YGU eğitimi veren üniversiteler, yangın güvenlik uzmanı eğitim şartları, YGU eğitim başvurusu, YGU eğitim ücretleri ve YGU eğitim tarihleri merak edilen konular arasında yer almaya başlamıştır.`},{tip:`p`,metin:`Peki, Yangın Güvenlik Uzmanlığı (YGU) eğitimi nasıl olacak? Yangın Güvenlik Uzmanı (YGU) olmak isteyen kişiler hangi konuları öğrenmeli? YGU eğitimi veren yerler nasıl belirlenecek?`},{tip:`p`,metin:`Bu makalede Yangın Güvenlik Uzmanlığı (YGU) eğitimini, mevcut mevzuat çerçevesini, eğitim içeriğini, uzmanlık seviyelerini ve mesleki hazırlık sürecini ele alıyoruz.`},{tip:`h2`,id:`1-yangin-guvenlik-uzmanligi-ygu-egitimi-nedir`,metin:`1. Yangın Güvenlik Uzmanlığı (YGU) Eğitimi Nedir?`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitimi, yapıların yangın güvenliğinin mevzuat ve teknik gereklilikler çerçevesinde değerlendirilmesine yönelik mesleki bilgi ve uygulama becerilerini geliştirmeyi amaçlayan eğitim sürecidir.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU) için yalnızca yönetmelik hükümlerini bilmek yeterli değildir. Uzmanın yapının özelliklerini değerlendirebilmesi, ilgili projeleri okuyabilmesi, saha koşullarını inceleyebilmesi ve tespitlerini teknik gerekçelerle açıklayabilmesi gerekir.`},{tip:`p`,metin:`Örneğin bir binada yangın merdiveni bulunması, kaçış güvenliğinin bütün koşullarıyla sağlandığını tek başına göstermez. Merdivenin hangi katlara hizmet ettiği, kaçış yoluyla bağlantısı, korunma özellikleri ve mevcut kullanım koşulları birlikte değerlendirilmelidir.`},{tip:`p`,metin:`Bu nedenle Yangın Güvenlik Uzmanlığı (YGU) eğitiminin temelinde, yangın güvenliği mevzuatı ile gerçek yapı uygulamalarının ilişkilendirilmesi bulunmalıdır.`},{tip:`h2`,id:`2-yangin-guvenlik-uzmanligi-ygu-egitiminin-mevzuat-dayanagi`,metin:`2. Yangın Güvenlik Uzmanlığı (YGU) Eğitiminin Mevzuat Dayanağı`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) sisteminin kanuni dayanağı ile eğitimlerin uygulanmasına ilişkin ayrıntılar birbirinden ayrılmalıdır.`},{tip:`p`,metin:`7579 sayılı Kanun ile 3194 sayılı İmar Kanunu'nda yapılan değişiklikler, yangın güvenliği periyodik kontrolleri ve Yangın Güvenlik Uzmanı (YGU) yetkilendirme sistemi bakımından kanuni çerçeveyi oluşturmuştur.`},{tip:`p`,metin:`Bu düzenlemeler kapsamında yangın güvenliği periyodik kontrollerinin yürütülmesine ve yangın güvenlik raporlarının düzenlenmesine ilişkin hükümler yer almaktadır.`},{tip:`p`,metin:`Bununla birlikte Yangın Güvenlik Uzmanlığı (YGU) eğitiminin ayrıntılı uygulama koşulları, sınav, uzmanlık seviyeleri ve yetkilendirme usulleri ilgili ikincil mevzuatla değerlendirilmelidir.`},{tip:`not`,etiket:`TASLAK`,metin:`Yangın Güvenlik Uzmanlığı ve Periyodik Kontrol Usul ve Esasları Hakkında Yönetmelik Taslağı, YGU eğitimi ve uzmanlık sistemi hakkında önerilen düzenlemeleri içermektedir.`},{tip:`p`,metin:`Taslakta yer alan eğitim ve yetkilendirme koşulları, kesinleşmiş mevzuat hükümleriyle karıştırılmamalıdır.`},{tip:`h2`,id:`3-yangin-guvenlik-uzmanligi-ygu-egitimi-hangi-konulari-kapsayacak`,metin:`3. Yangın Güvenlik Uzmanlığı (YGU) Eğitimi Hangi Konuları Kapsayacak?`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU) olarak görev yapacak kişilerin, yangın güvenliğini farklı teknik disiplinler açısından değerlendirebilmesi gerekir.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitimi bakımından önem taşıyan temel teknik alanlar aşağıda açıklanmaktadır.`},{tip:`h3`,metin:`3.1. Yangın bilimi ve yangın davranışı`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitiminde yangının oluşumu, yanma mekanizması, ısı transferi, duman hareketi ve yangının yapı içerisindeki gelişimi temel bilgi alanlarıdır.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU), bu bilgileri yangının yayılma yollarını ve korunma önlemlerinin işlevini anlayabilmek için kullanır.`},{tip:`h3`,metin:`3.2. Binaların Yangından Korunması Hakkında Yönetmelik`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitiminin en önemli teknik dayanaklarından biri Binaların Yangından Korunması Hakkında Yönetmelik'tir (BYKHY).`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU), yapının kullanım sınıfını, yüksekliğini, kullanıcı yükünü, mevcut veya yeni yapı niteliğini ve diğer ilgili özelliklerini dikkate alarak uygulanabilir hükümleri değerlendirebilmelidir.`},{tip:`p`,metin:`Özellikle mevcut yapılarda geçmiş ruhsat ve izin belgeleri, onaylı projeler ve sonraki tadilatlar birlikte ele alınmalıdır.`},{tip:`h3`,metin:`3.3. Mimari yangın güvenliği ve kaçış yolları`},{tip:`p`,metin:`Kaçış yolları, yangın merdivenleri, çıkışlar, yangın kapıları, yangın bölmeleri ve yapı elemanlarının yangına dayanımı, Yangın Güvenlik Uzmanlığı (YGU) eğitiminin temel teknik konuları arasındadır.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU), yalnızca bir elemanın bulunup bulunmadığını değil, ilgili düzenlemenin yapı içerisinde doğru biçimde uygulanıp uygulanmadığını değerlendirmelidir.`},{tip:`h3`,metin:`3.4. Yangın algılama ve uyarı sistemleri`},{tip:`p`,metin:`Yangın algılama ve alarm sistemlerinin bileşenleri, çalışma prensipleri ve diğer yangın güvenliği sistemleriyle ilişkileri, Yangın Güvenlik Uzmanlığı (YGU) eğitiminde önemli yer tutar.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU), kendi görev ve yetki kapsamındaki incelemelerde onaylı proje, saha uygulaması ve mevcut teknik raporlar arasındaki ilişkiyi değerlendirebilmelidir.`},{tip:`h3`,metin:`3.5. Yangın söndürme ve duman kontrol sistemleri`},{tip:`p`,metin:`Sprinkler sistemleri, yangın dolapları, hidrantlar, yangın pompaları, su depoları ve duman kontrol sistemleri, yapıların yangından korunmasında önemli işlevlere sahiptir.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitimi kapsamında bu sistemlerin temel çalışma prensiplerinin öğrenilmesi, saha incelemelerinde teknik değerlendirme yapılmasını kolaylaştırır.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU) yetkisi, diğer mesleklerin mevzuatla belirlenmiş tasarım, ölçüm, test ve özel teknik onay yetkilerini kendiliğinden kapsamaz.`},{tip:`h3`,metin:`3.6. Proje inceleme ve saha kontrolü`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitiminde onaylı projeler ile mevcut yapıların karşılaştırılması önemli bir uygulama alanıdır.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU), ilgili görevi kapsamında projede öngörülen yangın güvenlik önlemleri ile gerçek mahal, faaliyet ve işletme koşullarını karşılaştırabilmelidir.`},{tip:`p`,metin:`Bu değerlendirmede teknik belgeler, bakım ve kontrol raporları ile saha gözlemleri birlikte ele alınır.`},{tip:`not`,etiket:`Eğitim müfredatı notu`,metin:`Bu bölüm Yangın Güvenlik Uzmanlığı (YGU) açısından önemli teknik alanları açıklamaktadır. Kesin modül isimleri ve zorunlu ders saatleri, yürürlükteki eğitim düzenlemesi ve resmî müfredat üzerinden ayrıca doğrulanmalıdır.`},{tip:`h2`,id:`4-yangin-guvenlik-uzmanligi-ygu-egitim-seviyeleri-nelerdir`,metin:`4. Yangın Güvenlik Uzmanlığı (YGU) Eğitim Seviyeleri Nelerdir?`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) yönetmelik taslağında YGU-1, YGU-2, YGU-3 ve YGU-K uzmanlık seviyeleri öngörülmektedir.`},{tip:`p`,metin:`Bu seviyeler, Yangın Güvenlik Uzmanı (YGU) olarak görev alacak kişilerin uzmanlık ve yetki kapsamlarının farklılaştırılması amacıyla düzenleme çalışmalarına konu olmuştur.`},{tip:`p`,vurgu:`YGU-1:`,metin:`Taslakta düzenlenen uzmanlık seviyelerinden biridir.`},{tip:`p`,vurgu:`YGU-2:`,metin:`Taslakta ayrı yeterlilik ve görev kapsamıyla ele alınan uzmanlık seviyesidir.`},{tip:`p`,vurgu:`YGU-3:`,metin:`Taslakta ayrıca tanımlanan uzmanlık seviyesidir.`},{tip:`p`,vurgu:`YGU-K:`,metin:`Taslakta özel kapsamı bulunan Yangın Güvenlik Uzmanlığı (YGU) seviyesidir.`},{tip:`p`,metin:`Bu seviyelerin birbirinden hangi öğrenim, mesleki yeterlilik ve görev koşullarıyla ayrıldığı, kesinleşmiş mevzuatla birlikte değerlendirilmelidir.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitimine katılmak isteyen kişiler, öncelikle kendi mesleki niteliklerinin hangi uzmanlık seviyesi için uygun olduğunu araştırmalıdır.`},{tip:`h2`,id:`5-yangin-guvenlik-uzmanligi-ygu-egitimi-teorik-ve-uygulamali-mi-olacak`,metin:`5. Yangın Güvenlik Uzmanlığı (YGU) Eğitimi Teorik ve Uygulamalı mı Olacak?`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitiminde teorik bilgi ile uygulama becerilerinin birbirini tamamlaması önemlidir.`},{tip:`p`,metin:`Örneğin kaçış yolları anlatılırken yalnızca yönetmelik hükümlerinin gösterilmesi yerine, bir mimari proje üzerinden kaçış düzeninin incelenmesi daha öğretici olacaktır.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU) olmak isteyen kişiler, projede gösterilen yangın güvenlik düzenlemelerinin sahada nasıl karşılık bulduğunu anlayabilmelidir.`},{tip:`p`,metin:`Benzer şekilde yangın algılama veya söndürme sistemleri anlatılırken sistem bileşenlerinin birbirleriyle ilişkisi ve saha uygulamalarında karşılaşılabilecek farklılıklar değerlendirilmelidir.`},{tip:`p`,metin:`Bununla birlikte Yangın Güvenlik Uzmanlığı (YGU) eğitiminin zorunlu teorik ve uygulamalı süreleri ile eğitim biçimi, ilgili düzenlemelerin kesinleşmiş hükümlerine göre belirlenmelidir.`},{tip:`p`,metin:`TASLAK KARŞILAŞTIRMASI — Özgün YGU yönetmelik taslağı Madde 9, teorik eğitimin Bakanlık veya Bakanlıkça yetkilendirilmiş kuruluşlar tarafından; uygulama eğitiminin ise mahalli itfaiye teşkilatı tarafından verilmesini öngörmektedir. Teorik eğitim yüz yüze veya uzaktan düzenlenebilir; taslakta katılım belgesi için teorik eğitime en az %90 devam şartı bulunmaktadır. Uygulama bölümünde farklı kullanım sınıfındaki iki yapıya ilişkin rapor hazırlama ve uygulama gözetimi öngörülmüştür. Bunlar nihai yönetmelik hükümleri değil, TASLAK Madde 9 kurallarıdır.`},{tip:`h2`,id:`6-yangin-guvenlik-uzmanligi-ygu-egitimi-veren-universiteler`,metin:`6. Yangın Güvenlik Uzmanlığı (YGU) Eğitimi Veren Üniversiteler`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitimi veren üniversiteler konusu, YGU eğitimi almak isteyen kişilerin en çok araştırdığı başlıklardan biridir.`},{tip:`p`,metin:`Ancak bir üniversitenin yangın güvenliği alanında sertifika programı veya mesleki eğitim düzenlemesi, o kurumun resmî Yangın Güvenlik Uzmanlığı (YGU) eğitimi vermeye yetkili olduğu anlamına gelmez.`},{tip:`p`,metin:`Bu nedenle YGU eğitimi veren üniversiteler araştırılırken ilgili kurumun yetkilendirme durumu, eğitim programının niteliği ve resmî duyuruları kontrol edilmelidir.`},{tip:`not`,etiket:`Güncel durum`,metin:`Bu makalede yetkilendirmesi doğrulanmamış bir üniversite, resmî YGU eğitimi veren kuruluş olarak gösterilmemektedir.`},{tip:`h2`,id:`7-yangin-guvenlik-uzmanligi-ygu-egitimi-veren-yerler`,metin:`7. Yangın Güvenlik Uzmanlığı (YGU) Eğitimi Veren Yerler`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitimi veren yerler araştırılırken genel yangın güvenliği eğitimleri ile resmî uzmanlık eğitimleri birbirinden ayrılmalıdır.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU) olmaya yönelik hazırlık eğitimi sunan bir kurum ile mevzuat kapsamında yetkilendirilmiş bir eğitim kuruluşunun verdiği program aynı nitelikte olmayabilir.`},{tip:`p`,metin:`Bu nedenle Yangın Güvenlik Uzmanlığı (YGU) eğitimi almak isteyen kişiler yalnızca eğitim ilanının başlığına değil, programın yetkilendirme kapsamına ve verilen belgenin niteliğine dikkat etmelidir.`},{tip:`h2`,id:`8-yangin-guvenlik-uzmanligi-ygu-egitim-basvurusu-nasil-yapilacak`,metin:`8. Yangın Güvenlik Uzmanlığı (YGU) Eğitim Başvurusu Nasıl Yapılacak?`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitim başvurusu, uzmanlık seviyesine ve ilgili mevzuatta aranan yeterlilik koşullarına göre değerlendirilmelidir.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU) olmak isteyen kişinin yalnızca bir eğitim programına katılması, resmî uzmanlık yetkisini kendiliğinden kazandığı anlamına gelmez.`},{tip:`p`,metin:`Eğitim, sınav ve yetkilendirme süreçleri ilgili mevzuatın öngördüğü koşullara göre yürütülmelidir.`},{tip:`p`,metin:`YGU eğitim başvurusu sırasında hangi belgelerin isteneceği, başvuruların nereden yapılacağı ve başvuru takviminin nasıl işleyeceği, yetkili kurumların kesinleşmiş duyurularıyla belirlenmelidir.`},{tip:`h2`,id:`9-yangin-guvenlik-uzmanligi-ygu-egitim-sartlari-nelerdir`,metin:`9. Yangın Güvenlik Uzmanlığı (YGU) Eğitim Şartları Nelerdir?`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitim şartları, uzmanlık seviyelerine göre farklı yeterlilik koşullarını içerebilir.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU) olmak isteyen kişiler açısından öğrenim durumu, mesleki nitelikler, eğitim ve sınav koşulları birlikte önem taşır.`},{tip:`p`,metin:`Ancak mühendis, mimar, teknik personel veya iş güvenliği uzmanı olmak, ilgili mevzuattaki koşullar ayrıca sağlanmadan otomatik Yangın Güvenlik Uzmanı (YGU) yetkisi kazanıldığı anlamına gelmez.`},{tip:`p`,metin:`Bu nedenle YGU eğitim şartları incelenirken taslak hükümler ile yürürlükteki kesin şartlar birbirinden ayrılmalıdır.`},{tip:`h2`,id:`10-yangin-guvenlik-uzmanligi-ygu-egitim-ucretleri-ne-kadar`,metin:`10. Yangın Güvenlik Uzmanlığı (YGU) Eğitim Ücretleri Ne Kadar?`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitim ücretleri, YGU eğitimi almak isteyen kişilerin eğitim planlamasında önemli bir konudur.`},{tip:`p`,metin:`Eğitim ücretinin hangi hizmetleri kapsadığı, toplam ders süresi, uygulama faaliyetleri ve varsa ek giderler, eğitim programı değerlendirilirken dikkate alınmalıdır.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitim ücreti ile sınav veya yetkilendirme işlemlerine ilişkin olası bedeller aynı kalemler olmayabilir.`},{tip:`not`,etiket:`Güncel ücret durumu`,metin:`Bu makalede doğrulanmış bir Yangın Güvenlik Uzmanlığı (YGU) eğitim ücreti bulunmadığından kesin tutar verilmemiştir.`},{tip:`h2`,id:`11-yangin-guvenlik-uzmanligi-ygu-egitim-tarihleri-ne-zaman`,metin:`11. Yangın Güvenlik Uzmanlığı (YGU) Eğitim Tarihleri Ne Zaman?`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitim tarihleri ve başvuru takvimi, YGU eğitimi almak isteyen kişilerin takip ettiği önemli konular arasındadır.`},{tip:`p`,metin:`Bir yönetmelik taslağının yayımlanmış olması, Yangın Güvenlik Uzmanlığı (YGU) eğitim başvurularının başladığı veya eğitim takviminin kesinleştiği anlamına gelmez.`},{tip:`p`,metin:`Bu nedenle YGU eğitim tarihleri araştırılırken resmî duyurunun yayımlandığı tarih, ilgili eğitim kurumunun yetkilendirme durumu ve programın kapsamı kontrol edilmelidir.`},{tip:`not`,etiket:`Güncel takvim durumu`,metin:`Bu makalede doğrulanmış bir Yangın Güvenlik Uzmanlığı (YGU) eğitim başlangıç tarihi veya başvuru takvimi belirtilmemiştir.`},{tip:`h2`,id:`12-yangin-guvenlik-uzmaninin-ygu-sahadaki-uygulamasi`,metin:`12. Yangın Güvenlik Uzmanının (YGU) Sahadaki Uygulaması`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitiminin mesleki karşılığı, gerçek bir yapının yangın güvenliği bakımından incelenmesinde ortaya çıkar.`},{tip:`p`,metin:`Örneğin bir üretim tesisinde yangın güvenliği değerlendirmesi yapılırken öncelikle yapının onaylı projeleri, kullanım izinleri, mevcut faaliyetleri ve işletme koşulları incelenir.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU), ilgili görev kapsamında projede öngörülen yangın güvenlik önlemlerini sahadaki gerçek uygulamalarla karşılaştırır.`},{tip:`p`,metin:`Örneğin onaylı projede kaçış yolu olarak düzenlenen bir alanın işletme sırasında depolama amacıyla kullanılması, kaçış güvenliği bakımından incelenmesi gereken bir durumdur.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU), böyle bir tespitte mevcut durumu, ilgili teknik belgeleri ve uygulanabilir mevzuat hükümlerini birlikte değerlendirerek gerekçeli raporlama yapmalıdır.`},{tip:`p`,metin:`Özel test, ölçüm ve teknik tasarım faaliyetleri ise ilgili mesleklerin mevzuatla belirlenmiş yetki sınırları dikkate alınarak değerlendirilir.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitiminin en önemli kazanımlarından biri, bir binanın yalnızca projede gösterilen halinin değil, gerçek kullanım koşullarının da yangın güvenliği açısından değerlendirilmesidir.`},{tip:`h2`,id:`13-yangin-guvenlik-uzmani-ygu-olmak-isteyenler-egitime-nasil-hazirlanabilir`,metin:`13. Yangın Güvenlik Uzmanı (YGU) Olmak İsteyenler Eğitime Nasıl Hazırlanabilir?`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitimine hazırlanmak isteyen kişiler öncelikle Binaların Yangından Korunması Hakkında Yönetmelik'in temel sistematiğini öğrenmelidir.`},{tip:`p`,metin:`Yangın güvenliği mevzuatı, yangın davranışı, mimari proje okuma, kaçış düzenlemeleri ve yangından korunma sistemleri, YGU eğitimine hazırlık açısından önemli bilgi alanlarıdır.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU) olmak isteyen kişiler için özellikle proje ile saha arasındaki farklılıkların değerlendirilmesi üzerinde çalışmak yararlıdır.`},{tip:`p`,metin:`Bir eksikliğin yalnızca varlığını belirlemek değil, bu eksikliğin hangi teknik gerekçeyle önem taşıdığını açıklayabilmek de Yangın Güvenlik Uzmanlığı (YGU) bakımından önemli bir mesleki beceridir.`},{tip:`h2`,id:`14-yangin-guvenlik-uzmanligi-ygu-egitimi-hakkinda-sik-sorulan-sorular`,metin:`14. Yangın Güvenlik Uzmanlığı (YGU) Eğitimi Hakkında Sık Sorulan Sorular`},{tip:`h3`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitimi nedir?`},{tip:`p`,metin:`Yangın güvenliği mevzuatı, yapı özellikleri, yangından korunma sistemleri ve saha değerlendirme yöntemlerine ilişkin mesleki eğitim sürecidir. Resmî programın kapsamı ilgili mevzuatla belirlenir.`},{tip:`h3`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitimi veren üniversiteler hangileri?`},{tip:`p`,metin:`Yetkilendirilmiş üniversiteler, ilgili kurumların resmî duyurularıyla belirlenmelidir. Genel yangın güvenliği sertifika programlarıyla resmî YGU eğitimleri aynı kabul edilmemelidir.`},{tip:`h3`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitim başvurusu ne zaman yapılacak?`},{tip:`p`,metin:`Kesin başvuru tarihleri, yetkili kurumların açıklayacağı eğitim takvimine göre değerlendirilmelidir.`},{tip:`h3`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitim şartları nelerdir?`},{tip:`p`,metin:`Başvuru koşulları uzmanlık seviyesi, mesleki nitelikler ve ilgili mevzuat hükümlerine göre belirlenmelidir.`},{tip:`h3`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitim ücretleri belli mi?`},{tip:`p`,metin:`Bu makalede doğrulanmış bir ücret bulunmadığından kesin tutar verilmemiştir.`},{tip:`h3`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitim tarihleri belli mi?`},{tip:`p`,metin:`Eğitim ve başvuru takvimleri için ilgili kurumların kesinleşmiş resmî duyuruları esas alınmalıdır.`},{tip:`h3`,metin:`Yangın Güvenlik Uzmanı (YGU) olmak için yalnızca eğitim almak yeterli mi?`},{tip:`p`,metin:`Hayır. Resmî yetkilendirme için ilgili mevzuatta öngörülen eğitim, sınav ve diğer koşulların sağlanması gerekir.`},{tip:`h2`,id:`sonuc`,metin:`Sonuç`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU), yapıların yangın güvenliğinin değerlendirilmesinde teknik bilgi, mevzuat bilgisi ve saha inceleme becerilerini bir araya getiren bir uzmanlık alanıdır.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitimi, yangın güvenliği mevzuatının gerçek yapı ve işletme koşullarında nasıl uygulanacağının anlaşılması bakımından önem taşımaktadır.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU) olmak isteyen kişilerin, eğitim şartları, başvuru tarihleri, yetkili eğitim kurumları ve eğitim ücretleri konusunda doğrulanmış bilgileri takip etmesi gerekir.`},{tip:`p`,metin:`YGU Rehberi, Yangın Güvenlik Uzmanlığı (YGU) eğitimi, YGU eğitim başvurusu, yangın güvenlik uzmanlığı eğitim şartları, YGU eğitimi veren üniversiteler ve YGU eğitim tarihleri hakkında güncel ve doğrulanmış bilgileri bir araya getirmeyi amaçlamaktadır.`}],kaynakBaslik:`Kaynakça`,kaynaklar:[{metin:`3194 Sayılı İmar Kanunu`},{metin:`7579 Sayılı Tapu Kanunu ile Bazı Kanunlarda ve 375 Sayılı Kanun Hükmünde Kararnamede Değişiklik Yapılmasına Dair Kanun`},{metin:`Binaların Yangından Korunması Hakkında Yönetmelik`},{metin:`Yangın Güvenlik Uzmanlığı ve Periyodik Kontrol Usul ve Esasları Hakkında Yönetmelik Taslağı`}],sss:[{soru:`Yangın Güvenlik Uzmanlığı (YGU) eğitimi nedir?`,yanit:`Yangın güvenliği mevzuatı, yapı özellikleri, yangından korunma sistemleri ve saha değerlendirme yöntemlerine ilişkin mesleki eğitim sürecidir. Resmî programın kapsamı ilgili mevzuatla belirlenir.`},{soru:`Yangın Güvenlik Uzmanlığı (YGU) eğitimi veren üniversiteler hangileri?`,yanit:`Yetkilendirilmiş üniversiteler, ilgili kurumların resmî duyurularıyla belirlenmelidir. Genel yangın güvenliği sertifika programlarıyla resmî YGU eğitimleri aynı kabul edilmemelidir.`},{soru:`Yangın Güvenlik Uzmanlığı (YGU) eğitim başvurusu ne zaman yapılacak?`,yanit:`Kesin başvuru tarihleri, yetkili kurumların açıklayacağı eğitim takvimine göre değerlendirilmelidir.`},{soru:`Yangın Güvenlik Uzmanlığı (YGU) eğitim şartları nelerdir?`,yanit:`Başvuru koşulları uzmanlık seviyesi, mesleki nitelikler ve ilgili mevzuat hükümlerine göre belirlenmelidir.`},{soru:`Yangın Güvenlik Uzmanlığı (YGU) eğitim ücretleri belli mi?`,yanit:`Bu makalede doğrulanmış bir ücret bulunmadığından kesin tutar verilmemiştir.`},{soru:`Yangın Güvenlik Uzmanlığı (YGU) eğitim tarihleri belli mi?`,yanit:`Eğitim ve başvuru takvimleri için ilgili kurumların kesinleşmiş resmî duyuruları esas alınmalıdır.`},{soru:`Yangın Güvenlik Uzmanı (YGU) olmak için yalnızca eğitim almak yeterli mi?`,yanit:`Hayır. Resmî yetkilendirme için ilgili mevzuatta öngörülen eğitim, sınav ve diğer koşulların sağlanması gerekir.`}]},{no:`02`,baslik:`Mühendisler ve Mimarlar İçin Yangın Güvenlik Uzmanlığı (YGU) Eğitimi Ne Anlama Geliyor?`,ozet:`Yangın güvenliği, mühendislik ve mimarlık disiplinlerinin birlikte değerlendirilmesini gerektiren önemli bir teknik alandır. Bir binanın yangın karşısındaki güvenliği yalnızca mimari projesine, elektrik tesisatına veya mekanik yangından korunma sistemlerine bağlı değildir. Bütün bu unsurların birbiriyle uyumlu olması gerekir.`,bloklar:[{tip:`p`,metin:`Türkiye'de Yangın Güvenlik Uzmanlığı (YGU) sistemine ilişkin düzenlemeler, mühendisler ve mimarlar açısından yeni bir mesleki uzmanlaşma alanını gündeme getirmiştir.`},{tip:`p`,metin:`Peki, mühendisler ve mimarlar Yangın Güvenlik Uzmanı (YGU) olabilir mi? Yangın Güvenlik Uzmanlığı (YGU) eğitimi bu meslek gruplarına hangi yetkinlikleri kazandırabilir? YGU eğitimi ile mevcut mühendislik ve mimarlık hizmetleri arasında nasıl bir ilişki vardır?`},{tip:`h2`,id:`1-yangin-guvenlik-uzmanligi-ygu-neden-muhendislik-ve-mimarlikla-iliskilidir`,metin:`1. Yangın Güvenlik Uzmanlığı (YGU) Neden Mühendislik ve Mimarlıkla İlişkilidir?`},{tip:`p`,metin:`Bir binanın yangın güvenliği, daha tasarım aşamasında alınan kararlarla şekillenmeye başlar.`},{tip:`p`,metin:`Mimari yerleşim, kullanım sınıfı, kaçış yolları, yangın bölmeleri, yapı elemanları, yangın algılama sistemleri, söndürme tesisatları ve duman kontrolü birbiriyle ilişkili teknik düzenlemelerdir.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU), görev ve yetki kapsamındaki incelemelerde bu düzenlemelerin yangın güvenliği açısından ne anlama geldiğini değerlendirebilmelidir.`},{tip:`p`,metin:`Örneğin bir projede kaçış merdiveninin doğru konumlandırılması mimari tasarım bakımından önem taşırken, merdivenin korunması, basınçlandırılması ve yangın kapılarıyla ilişkisi farklı teknik disiplinleri ilgilendirebilir.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitiminin önemi, bu farklı unsurları tek bir yangın güvenliği değerlendirmesi içerisinde anlayabilme ihtiyacından kaynaklanmaktadır.`},{tip:`h2`,id:`2-mimarlar-icin-yangin-guvenlik-uzmanligi-ygu-egitimi`,metin:`2. Mimarlar İçin Yangın Güvenlik Uzmanlığı (YGU) Eğitimi`},{tip:`p`,metin:`Mimarlar, yapıların mekansal düzenini ve kullanım ilişkilerini değerlendirme konusunda önemli bir mesleki altyapıya sahiptir.`},{tip:`p`,metin:`Bu altyapı, Yangın Güvenlik Uzmanlığı (YGU) eğitiminde özellikle mimari yangın güvenliği ve kaçış düzenlemeleri bakımından yararlı olabilir.`},{tip:`p`,metin:`Bir mimarın YGU eğitiminde geliştirebileceği başlıca yetkinlikler; yapı kullanım sınıflarını değerlendirmek, kaçış düzenlemelerinin teknik gerekçelerini anlamak, yangın bölmelerinin sürekliliğini incelemek ve mevcut yapıyla onaylı projeyi karşılaştırmaktır.`},{tip:`p`,metin:`Ancak bir mimarın proje hazırlama veya mesleki onay yetkisi ile Yangın Güvenlik Uzmanı (YGU) olarak üstlenebileceği görevler aynı değildir.`},{tip:`p`,metin:`Her görev kendi mevzuatı ve yetkilendirme koşulları içerisinde değerlendirilmelidir.`},{tip:`h2`,id:`3-insaat-muhendisleri-icin-yangin-guvenlik-uzmanligi-ygu`,metin:`3. İnşaat Mühendisleri İçin Yangın Güvenlik Uzmanlığı (YGU)`},{tip:`p`,metin:`İnşaat mühendisliği, yapı elemanlarının davranışı ve taşıyıcı sistemlerin teknik özellikleri açısından yangın güvenliğiyle ilişkilidir.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitimi bakımından yapı malzemelerinin yangına tepkisi, yangına dayanım kavramları, yapı elemanlarının korunması ve mevcut yapılarda meydana gelen değişikliklerin değerlendirilmesi önemlidir.`},{tip:`p`,metin:`Örneğin bir yapıda sonradan oluşturulan tesisat geçişlerinin yangın bölmelerinin sürekliliğini etkileyip etkilemediği incelenebilir.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU), böyle bir durumu kendi inceleme kapsamı içinde tespit edip gerekçelendirebilir. Ancak bu görev, taşıyıcı sistemin yangın altındaki performansına ilişkin özel mühendislik hesaplarını otomatik olarak yapma yetkisi anlamına gelmez.`},{tip:`h2`,id:`4-makine-muhendisleri-icin-yangin-guvenlik-uzmanligi-ygu-egitimi`,metin:`4. Makine Mühendisleri İçin Yangın Güvenlik Uzmanlığı (YGU) Eğitimi`},{tip:`p`,metin:`Yangın söndürme, duman kontrolü, yangın pompaları ve ilgili mekanik tesisatlar makine mühendisliği ile yakından ilişkilidir.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitiminde bu sistemlerin ne amaçla kullanıldığı, hangi yapı özellikleriyle ilişkili olduğu ve diğer yangından korunma önlemleriyle nasıl çalıştığı anlaşılmalıdır.`},{tip:`p`,metin:`Örneğin sprinkler tesisatının projede bulunması ile sistemin gerçek yapıda öngörülen alanları koruyacak şekilde uygulanmış olması farklı değerlendirmelerdir.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU), ilgili görevi kapsamında onaylı projeleri, saha uygulamasını ve mevcut teknik belgeleri birlikte inceleyebilir.`},{tip:`p`,metin:`Sistemin tasarımı, özel teknik hesapları ve mevzuatla belirlenmiş test veya onay faaliyetleri ise ilgili yetki sınırları içerisinde yürütülür.`},{tip:`h2`,id:`5-elektrik-ve-elektronik-muhendisleri-icin-yangin-guvenlik-uzmanligi-ygu`,metin:`5. Elektrik ve Elektronik Mühendisleri İçin Yangın Güvenlik Uzmanlığı (YGU)`},{tip:`p`,metin:`Yangın algılama ve alarm sistemleri, acil durum aydınlatması, yönlendirme düzeni ve bazı güvenlik sistemleri elektrik ve elektronik mühendisliği ile ilişkilidir.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitimi, bu sistemlerin yangın güvenliği içerisindeki işlevlerinin anlaşılmasına katkı sağlayabilir.`},{tip:`p`,metin:`Örneğin yangın alarm sisteminden gelen bir sinyalin diğer güvenlik sistemleriyle ilişkisi, binanın kullanım özellikleri dikkate alınarak değerlendirilebilir.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU), teknik raporlar ve projeler üzerinden gerekli bilgileri inceleyebilmelidir. Bununla birlikte uzmanlık yetkisi, elektrik tesisatına ilişkin bütün test ve ölçümleri doğrudan gerçekleştirme yetkisi olarak yorumlanmamalıdır.`},{tip:`h2`,id:`6-kimya-muhendisleri-ve-diger-muhendislik-disiplinleri-icin-ygu-egitimi`,metin:`6. Kimya Mühendisleri ve Diğer Mühendislik Disiplinleri İçin YGU Eğitimi`},{tip:`p`,metin:`Endüstriyel tesislerde yangın güvenliği, kullanılan maddelerin özellikleri, üretim prosesleri, depolama düzeni ve işletme koşullarıyla doğrudan ilişkilidir.`},{tip:`p`,metin:`Kimya mühendisliği başta olmak üzere farklı mühendislik disiplinlerinin teknik bilgisi, Yangın Güvenlik Uzmanlığı (YGU) açısından değerli bir altyapı oluşturabilir.`},{tip:`p`,metin:`Özellikle yanıcı ve parlayıcı maddelerin bulunduğu işletmelerde bir yangın tehlikesinin doğru değerlendirilmesi için madde özelliklerinin ve proses koşullarının anlaşılması gerekir.`},{tip:`p`,metin:`Ancak Yangın Güvenlik Uzmanı (YGU) olmak, proses tasarımı veya özel güvenlik analizlerine ilişkin bütün mesleki yetkilerin kazanıldığı anlamına gelmez.`},{tip:`h2`,id:`7-muhendisler-ve-mimarlar-yangin-guvenlik-uzmani-ygu-olabilir-mi`,metin:`7. Mühendisler ve Mimarlar Yangın Güvenlik Uzmanı (YGU) Olabilir mi?`},{tip:`p`,metin:`Bu sorunun cevabı yalnızca kişinin mühendislik veya mimarlık diplomasına sahip olmasına bakılarak verilemez.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) için hangi meslek gruplarının hangi seviyeye başvurabileceği, ilgili mevzuatta düzenlenen öğrenim, eğitim, sınav ve yetkilendirme şartlarına bağlıdır.`},{tip:`not`,etiket:`TASLAK`,metin:`Yangın Güvenlik Uzmanlığı ve Periyodik Kontrol Usul ve Esasları Hakkında Yönetmelik Taslağı, uzmanlık seviyeleri ve yetkilendirme sistemine ilişkin önerilen hükümler içermektedir.`},{tip:`p`,metin:`Bu nedenle mesleki diploma ile resmî YGU yetkisinin birbirinden ayrılması gerekir.`},{tip:`p`,metin:`Bir mühendis veya mimarın yangın güvenliği konusunda eğitim alması mümkündür; ancak resmî Yangın Güvenlik Uzmanı (YGU) olarak görev yapabilmesi, mevzuatta aranan koşulların sağlanmasına bağlıdır.`},{tip:`p`,metin:`TASLAK KARŞILAŞTIRMASI — TASLAK Madde 5/2-b, YGU-2 için mimar ile inşaat, makine, elektrik, elektronik ve elektrik-elektronik mühendisi unvanlarını saymaktadır. Kimya mühendisleri ve kimya lisans mezunları ise YGU-K başvuru grubunda düzenlenmiştir. Bu liste bütün mühendislik dallarına otomatik başvuru hakkı vermez; meslek öğrenimi ve nihai başvuru şartları ayrıca doğrulanmalıdır.`},{tip:`h2`,id:`8-yangin-guvenlik-uzmaninin-ygu-sahadaki-uygulamasi`,metin:`8. Yangın Güvenlik Uzmanının (YGU) Sahadaki Uygulaması`},{tip:`p`,metin:`Bir binanın onaylı mimari projesinde yangın bölmesi olarak düzenlenen alanın, sonraki kullanım değişiklikleri nedeniyle farklı hale geldiğini düşünelim.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU), inceleme kapsamına göre önce yapının onaylı projelerini, izinlerini ve varsa tadilat belgelerini değerlendirir.`},{tip:`p`,metin:`Ardından sahadaki gerçek kullanım biçimini, duvarları, kapıları ve tesisat geçişlerini gözlemler. İlgili teknik belgeleri ve mevcut test raporlarını inceler.`},{tip:`p`,metin:`Burada önemli olan, her değişikliğin otomatik olarak mevzuata aykırı ilan edilmesi değildir. Değişikliğin hangi mevzuat hükmüne tabi olduğunun ve yangın güvenliği üzerindeki etkisinin gerekçelendirilmesidir.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU), gerekli teknik bulguları raporlayabilir; başka uzmanlıkların tasarım, hesap, test veya onay yetkilerini ise kendi görevinin doğal uzantısı olarak kabul etmez.`},{tip:`h2`,id:`9-yangin-guvenlik-uzmanligi-ygu-egitimi-muhendislere-ve-mimarlara-ne-kazandirabilir`,metin:`9. Yangın Güvenlik Uzmanlığı (YGU) Eğitimi Mühendislere ve Mimarlara Ne Kazandırabilir?`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitimi, farklı meslek disiplinlerinden gelen kişilerin yapı yangın güvenliğini daha bütüncül değerlendirmelerine yardımcı olabilir.`},{tip:`p`,metin:`Mühendisler ve mimarlar için bunun önemli kazanımlarından biri, yalnızca kendi uzmanlık alanlarındaki bir bileşene değil, binanın yangın güvenliği düzenine bütün olarak bakabilmektir.`},{tip:`p`,metin:`Bu yetkinlik, mevcut mesleki çalışmaların geliştirilmesi açısından da değerlidir.`},{tip:`p`,metin:`Ancak YGU eğitimi sonucunda elde edilebilecek resmî görevler ve çalışma alanları, ilgili uzmanlık seviyesine ve geçerli yetkilendirmeye göre belirlenir.`},{tip:`h2`,id:`10-muhendisler-ve-mimarlar-icin-ygu-egitimi-hakkinda-sik-sorulan-sorular`,metin:`10. Mühendisler ve Mimarlar İçin YGU Eğitimi Hakkında Sık Sorulan Sorular`},{tip:`h3`,metin:`Mimarlar Yangın Güvenlik Uzmanı (YGU) olabilir mi?`},{tip:`p`,metin:`Başvuru ve yetkilendirme hakkı, ilgili mevzuatta mimarlar için düzenlenen koşullara göre değerlendirilmelidir. Mimarlık diploması tek başına resmî YGU yetkisi vermez.`},{tip:`h3`,metin:`Makine mühendisleri için Yangın Güvenlik Uzmanlığı (YGU) eğitimi gerekli mi?`},{tip:`p`,metin:`YGU yetkisi hedefleniyorsa ilgili seviyenin eğitim ve yetkilendirme şartları esas alınmalıdır. Genel mesleki gelişim eğitimi ile resmî YGU eğitimi birbirinden ayrılmalıdır.`},{tip:`h3`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitimi veren üniversiteler hangileridir?`},{tip:`p`,metin:`Yetkilendirilmiş eğitim kurumları resmî duyurular üzerinden doğrulanmalıdır. Genel sertifika programları otomatik olarak resmî YGU eğitimi sayılmaz.`},{tip:`h3`,metin:`İş güvenliği uzmanları aynı zamanda Yangın Güvenlik Uzmanı (YGU) olabilir mi?`},{tip:`p`,metin:`İş güvenliği uzmanlığı belgesi ile YGU yetkisi ayrı sistemlerdir. Bir kişinin her iki alanda görev alabilmesi, her birinin ilgili koşullarını sağlamasına bağlıdır.`},{tip:`h2`,id:`sonuc`,metin:`Sonuç`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU), mühendislik ve mimarlık disiplinlerinin teknik bilgi birikiminden yararlanabilecek, ancak kendine özgü görev ve yetki sınırları bulunan bir uzmanlık alanıdır.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitimi, yapıların yangın güvenliğini proje, mevzuat, teknik sistemler ve gerçek kullanım koşullarıyla birlikte değerlendirebilme yetkinliğine katkı sağlayabilir.`},{tip:`p`,metin:`Mühendisler ve mimarlar için YGU uzmanlığına ilişkin en önemli konu, mevcut mesleki unvanlarının hangi uzmanlık seviyesine başvuru hakkı sağladığını ve resmî yetkilendirme için hangi koşulların arandığını güncel mevzuattan doğrulamaktır.`}],kaynakBaslik:`Kaynakça`,kaynaklar:[{metin:`3194 Sayılı İmar Kanunu`},{metin:`Binaların Yangından Korunması Hakkında Yönetmelik`},{metin:`Binaların Yangından Korunması Hakkında Yönetmelik Kılavuzu`},{metin:`Yangın Güvenlik Uzmanlığı ve Periyodik Kontrol Usul ve Esasları Hakkında Yönetmelik Taslağı`}],sss:[{soru:`Mimarlar Yangın Güvenlik Uzmanı (YGU) olabilir mi?`,yanit:`Başvuru ve yetkilendirme hakkı, ilgili mevzuatta mimarlar için düzenlenen koşullara göre değerlendirilmelidir. Mimarlık diploması tek başına resmî YGU yetkisi vermez.`},{soru:`Makine mühendisleri için Yangın Güvenlik Uzmanlığı (YGU) eğitimi gerekli mi?`,yanit:`YGU yetkisi hedefleniyorsa ilgili seviyenin eğitim ve yetkilendirme şartları esas alınmalıdır. Genel mesleki gelişim eğitimi ile resmî YGU eğitimi birbirinden ayrılmalıdır.`},{soru:`Yangın Güvenlik Uzmanlığı (YGU) eğitimi veren üniversiteler hangileridir?`,yanit:`Yetkilendirilmiş eğitim kurumları resmî duyurular üzerinden doğrulanmalıdır. Genel sertifika programları otomatik olarak resmî YGU eğitimi sayılmaz.`},{soru:`İş güvenliği uzmanları aynı zamanda Yangın Güvenlik Uzmanı (YGU) olabilir mi?`,yanit:`İş güvenliği uzmanlığı belgesi ile YGU yetkisi ayrı sistemlerdir. Bir kişinin her iki alanda görev alabilmesi, her birinin ilgili koşullarını sağlamasına bağlıdır.`}]},{no:`03`,baslik:`Yangın Güvenlik Uzmanlığı (YGU) Yeni Bir Kariyer Fırsatı mı? Yangın Güvenlik Uzmanı (YGU) Mesleğinin Geleceği`,ozet:`Yangın güvenliği, yapıların tasarımı ve işletilmesi boyunca önemini koruyan bir alandır. Özellikle mevcut yapılardaki yangından korunma önlemlerinin değerlendirilmesi, projeler ile saha koşullarının karşılaştırılması ve eksikliklerin tespit edilmesi, farklı teknik disiplinlerin birlikte çalışmasını gerektirir.`,bloklar:[{tip:`p`,metin:`Türkiye'de yangın güvenliği periyodik kontrollerine ilişkin kanuni düzenlemeler, Yangın Güvenlik Uzmanlığı (YGU) alanının geleceği konusunda önemli soruları gündeme getirmiştir.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU) olmak yeni bir kariyer fırsatı sağlayabilir mi? YGU eğitimi almak mesleki gelişim açısından ne ifade eder? Yangın güvenlik uzmanlığı hangi çalışma alanlarıyla ilişkilidir?`},{tip:`p`,metin:`Bu sorulara cevap verirken gelecekte oluşabilecek fırsatlarla bugün mevcut olan resmî görev ve yetkileri birbirinden ayırmak gerekir.`},{tip:`h2`,id:`1-yangin-guvenlik-uzmanligi-ygu-neden-onem-kazaniyor`,metin:`1. Yangın Güvenlik Uzmanlığı (YGU) Neden Önem Kazanıyor?`},{tip:`p`,metin:`Yangın güvenliği, yalnızca yeni binaların tasarım aşamasında ele alınabilecek bir konu değildir.`},{tip:`p`,metin:`Bir binanın kullanım amacı değişebilir, kullanıcı sayısı artabilir, üretim süreçleri farklılaşabilir veya başlangıçta projede bulunan yangından korunma sistemleri zamanla değişikliğe uğrayabilir.`},{tip:`p`,metin:`Bu nedenle yangın güvenliği, yapının kullanım ömrü boyunca değerlendirilmesi gereken bir konudur.`},{tip:`p`,metin:`22 Mayıs 2026 tarihinde yayımlanan kanuni düzenleme ile yangın güvenliği periyodik kontrol sistemine yönelik yeni bir çerçeve oluşturulmuştur.`},{tip:`p`,metin:`Bu çerçeve, Yangın Güvenlik Uzmanı (YGU) kavramının yalnızca eğitim ve teknik danışmanlık bakımından değil, mevzuatta tanımlanan görevler açısından da önem kazanmasını sağlamıştır.`},{tip:`p`,metin:`Ancak sistemin gelecekte nasıl uygulanacağı, uzmanlara yönelik talebin ne kadar olacağı ve hangi çalışma modellerinin oluşacağı, ikincil mevzuatın kesinleşmesine ve uygulamaya bağlıdır.`},{tip:`h2`,id:`2-yangin-guvenlik-uzmanligi-ygu-yeni-bir-meslek-mi`,metin:`2. Yangın Güvenlik Uzmanlığı (YGU) Yeni Bir Meslek mi?`},{tip:`p`,metin:`Yangın güvenliği alanındaki mühendislik, denetim, eğitim ve danışmanlık faaliyetleri yeni değildir. Uzun yıllardır mimarlar, mühendisler, teknik uzmanlar ve itfaiye teşkilatları bu alanda farklı görevler yürütmektedir.`},{tip:`p`,metin:`Yeni olan, yangın güvenliği periyodik kontrolleriyle ilişkili Yangın Güvenlik Uzmanı (YGU) yetkilendirme sisteminin mevzuatta ayrıca yapılandırılmasıdır.`},{tip:`p`,metin:`Bu nedenle Yangın Güvenlik Uzmanlığı (YGU), mevcut yangın güvenliği çalışmalarının tümünün yerine geçen bir meslek olarak değerlendirilmemelidir.`},{tip:`p`,metin:`Yangın güvenlik uzmanının görevleri, ilgili mevzuatla belirlenen kontrol ve raporlama sistemi içerisindeki yetki ve sorumluluklarıyla ele alınmalıdır.`},{tip:`h2`,id:`3-yangin-guvenlik-uzmani-ygu-hangi-alanlarda-calisabilir`,metin:`3. Yangın Güvenlik Uzmanı (YGU) Hangi Alanlarda Çalışabilir?`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) ile ilişkili çalışma alanları değerlendirilirken resmî uzmanlık yetkisi ile genel yangın güvenliği hizmetleri ayrılmalıdır.`},{tip:`h3`,metin:`Yangın güvenliği periyodik kontrolleri`},{tip:`p`,metin:`Kanuni düzenlemede, belirli koşullar altında yetkilendirilen yangın güvenlik uzmanlarının yangın güvenliği periyodik kontrollerinde görev almasına ilişkin çerçeve bulunmaktadır.`},{tip:`p`,metin:`Bu görevlerin hangi yapılarda, hangi usulle ve hangi kapsamda yürütülebileceği ilgili mevzuata bağlıdır.`},{tip:`h3`,metin:`Mevcut yapıların yangın güvenliği değerlendirmesi`},{tip:`p`,metin:`Kullanımdaki yapıların onaylı projeleri, izinleri, gerçek faaliyetleri ve mevcut yangından korunma sistemleri arasında farklılıklar bulunabilir.`},{tip:`p`,metin:`Bu farklılıkların teknik açıdan değerlendirilmesi, yangın güvenliği alanında uzmanlık gerektiren çalışmalardandır.`},{tip:`p`,metin:`Ancak bu tür bir teknik değerlendirme hizmeti ile resmî Yangın Güvenlik Uzmanı (YGU) kontrol veya raporlama yetkisi aynı kabul edilmemelidir.`},{tip:`h3`,metin:`Yangın güvenliği danışmanlığı`},{tip:`p`,metin:`İşletmelerin yangın güvenliğine ilişkin teknik bilgi ihtiyacı, proje değerlendirmesi, mevcut durum incelemesi ve iyileştirme çalışmalarında danışmanlık ihtiyacını gündeme getirebilir.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitimi, bu konularda mesleki bilgi birikiminin gelişmesine katkı sağlayabilir.`},{tip:`p`,metin:`Bununla birlikte danışmanlık hizmetinin kapsamı, yapılan işin niteliği ve ilgili diğer mesleklerin yetki sınırları dikkate alınmalıdır.`},{tip:`h3`,metin:`Eğitim ve mesleki gelişim`},{tip:`p`,metin:`Yangın güvenliği alanındaki teknik bilgi ihtiyacı, eğitim ve mesleki gelişim faaliyetleri bakımından da önemlidir.`},{tip:`p`,metin:`Ancak genel yangın güvenliği eğitimi vermek ile mevzuatta tanımlanan resmî YGU eğitimini düzenlemek farklı konulardır.`},{tip:`p`,metin:`Resmî eğitim faaliyetleri için gerekli yetkilendirme koşulları ayrıca değerlendirilmelidir.`},{tip:`h2`,id:`4-yangin-guvenlik-uzmanligi-ygu-is-imkanlari-artacak-mi`,metin:`4. Yangın Güvenlik Uzmanlığı (YGU) İş İmkanları Artacak mı?`},{tip:`p`,metin:`Yangın güvenlik uzmanlığına yönelik mevzuat çalışmaları, bu alanda yeni hizmet ihtiyaçlarının oluşabileceğini göstermektedir.`},{tip:`p`,metin:`Ancak belirli sayıda Yangın Güvenlik Uzmanı (YGU) istihdam edileceği, her işletmede zorunlu YGU çalıştırılacağı veya uzmanların belirli bir gelir elde edeceği yönünde kesin bir çıkarım yapılamaz.`},{tip:`p`,metin:`Yangın güvenliği periyodik kontrol sisteminin nasıl işleyeceği, hangi yapıların hangi dönemlerde kontrol edileceği ve yetkilendirilmiş uzmanların görev kapsamı, çalışma olanaklarını doğrudan etkileyebilir.`},{tip:`p`,metin:`Bu nedenle Yangın Güvenlik Uzmanlığı (YGU), değerlendirilmesi gereken bir mesleki gelişim alanıdır; ancak henüz kesinleşmemiş ekonomik beklentiler üzerinden tanıtılmamalıdır.`},{tip:`h2`,id:`5-yangin-guvenlik-uzmanligi-ygu-egitimi-kariyer-acisindan-neden-onemlidir`,metin:`5. Yangın Güvenlik Uzmanlığı (YGU) Eğitimi Kariyer Açısından Neden Önemlidir?`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitiminin mesleki değeri yalnızca bir yetki belgesi kazanma ihtimaliyle sınırlı değildir.`},{tip:`p`,metin:`Yangın güvenliği mevzuatının anlaşılması, mimari projelerin değerlendirilmesi, yangından korunma sistemlerinin tanınması ve saha inceleme yöntemlerinin öğrenilmesi, teknik bir uzmanlık birikimi oluşturur.`},{tip:`p`,metin:`Örneğin yalnızca yangın algılama sistemlerini tanıyan bir kişi ile bu sistemlerin yapı kullanım sınıfı, kaçış düzeni ve diğer korunma önlemleriyle ilişkisini değerlendirebilen kişi arasında önemli bir yetkinlik farkı bulunur.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU) eğitiminde bu bütüncül bakış açısının gelişmesi, mesleki kariyer bakımından önemli bir kazanım olabilir.`},{tip:`h2`,id:`6-yangin-guvenlik-uzmani-ygu-olmak-icin-hangi-yetkinlikler-gereklidir`,metin:`6. Yangın Güvenlik Uzmanı (YGU) Olmak İçin Hangi Yetkinlikler Gereklidir?`},{tip:`p`,metin:`Yangın güvenlik uzmanlığına hazırlanırken yalnızca diploma veya eğitim belgesine odaklanılmamalıdır.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU) için önemli teknik yetkinlikler arasında mevzuatı yorumlama, yapı ve tesisat projelerini inceleme, saha gözlemlerini kayıt altına alma, teknik raporları değerlendirme ve gerekçeli raporlama bulunur.`},{tip:`p`,metin:`Özellikle mevcut yapılarda hangi mevzuat hükümlerinin uygulanacağının belirlenmesi, tek başına yapının yaşına bakılarak çözülebilecek bir konu değildir.`},{tip:`p`,metin:`Yapının ruhsat, izin, kullanım ve tadilat geçmişi birlikte değerlendirilmelidir.`},{tip:`p`,metin:`Bu yaklaşım, yangın güvenlik uzmanının teknik değerlendirmelerini güvenilir verilere dayandırmasına yardımcı olur.`},{tip:`h2`,id:`7-yangin-guvenlik-uzmaninin-ygu-sahadaki-uygulamasi`,metin:`7. Yangın Güvenlik Uzmanının (YGU) Sahadaki Uygulaması`},{tip:`p`,metin:`Bir lojistik tesisinde zaman içerisinde depolama yüksekliğinin değiştiğini ve bazı alanların farklı amaçlarla kullanılmaya başlandığını düşünelim.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU), kendisine mevzuat kapsamında verilen görev çerçevesinde önce yapının onaylı projelerini, kullanım izinlerini ve mevcut işletme faaliyetlerini inceler.`},{tip:`p`,metin:`Ardından depolama düzenini, kaçış yollarını, yangından korunma sistemlerinin sahadaki yerleşimini ve ilgili teknik belgeleri değerlendirir.`},{tip:`p`,metin:`Örneğin sprinkler sisteminin bulunduğu bir depoda depolama biçiminin değişmiş olması, sistemin koruma koşulları bakımından incelenmesi gereken bir durum olabilir.`},{tip:`p`,metin:`Ancak yalnızca depolama biçiminin değiştiğini görmek, sistemin otomatik olarak yetersiz olduğu sonucunu doğurmaz.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU), gözlemsel tespitlerini ve ilgili belgeleri değerlendirerek gerekçeli raporlama yapmalı; özel hidrolik hesap, test veya tasarım gerektiren konuları kendi yetki sınırlarıyla karıştırmamalıdır.`},{tip:`p`,metin:`Bu örnek, Yangın Güvenlik Uzmanlığı (YGU) alanında teorik bilgi kadar doğru saha değerlendirmesinin de önem taşıdığını gösterir.`},{tip:`h2`,id:`8-ygu-egitimi-veren-universiteler-egitim-sartlari-ve-basvurular`,metin:`8. YGU Eğitimi Veren Üniversiteler, Eğitim Şartları ve Başvurular`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) kariyerini değerlendiren kişilerin en önemli araştırma konuları arasında YGU eğitimi veren üniversiteler, yangın güvenlik uzmanlığı eğitim şartları ve YGU eğitim başvuruları bulunmaktadır.`},{tip:`not`,etiket:`TASLAK`,metin:`Yönetmelik taslağında YGU-1, YGU-2, YGU-3 ve YGU-K uzmanlık seviyeleri öngörülmektedir.`},{tip:`p`,metin:`Hangi meslek gruplarının hangi seviyeye başvurabileceği, eğitim ve sınav koşulları ile yetkilendirme süreçleri kesinleşmiş mevzuat üzerinden doğrulanmalıdır.`},{tip:`p`,metin:`Bir üniversitenin yangın güvenliği sertifika programı düzenlemesi, resmî Yangın Güvenlik Uzmanlığı (YGU) eğitimi verme yetkisine sahip olduğu anlamına gelmez.`},{tip:`p`,metin:`Ayrıca YGU eğitim ücretleri ve eğitim tarihleri konusunda yalnızca doğrulanmış duyurular esas alınmalıdır.`},{tip:`p`,metin:`TASLAK KARŞILAŞTIRMASI — Yangın Güvenlik Uzmanlığı (YGU) kariyerinde eğitimden önce resmi kabul koşullarının bilinmesi gerekir. TASLAK Madde 9, teorik ve uygulama eğitimini iki ayrı aşama olarak düzenler. Bir uzmanlık belgesi edinilmesi ise herhangi bir iş veya gelir garantisi vermez. Gelecekteki periyodik kontrol ihtiyacı, itfaiye teşkilatlarının rolü, yetkilendirme ve fiili uygulama koşullarına bağlıdır.`},{tip:`h2`,id:`9-yangin-guvenlik-uzmanligi-ygu-kariyeri-hakkinda-sik-sorulan-sorular`,metin:`9. Yangın Güvenlik Uzmanlığı (YGU) Kariyeri Hakkında Sık Sorulan Sorular`},{tip:`h3`,metin:`Yangın Güvenlik Uzmanlığı (YGU) geleceği olan bir alan mı?`},{tip:`p`,metin:`Yangın güvenliğine ilişkin kanuni düzenlemeler ve yapıların sürekli değerlendirilmesi ihtiyacı, bu alanın gelişim potansiyelini göstermektedir. Ancak istihdam ve gelir beklentileri kesin değildir.`},{tip:`h3`,metin:`Yangın Güvenlik Uzmanı (YGU) olmak için mühendis olmak şart mı?`},{tip:`p`,metin:`Başvuru hakkı, ilgili uzmanlık seviyesinin mevzuatta belirlenen öğrenim ve yeterlilik koşullarına bağlıdır. Kesin şartlar doğrulanmadan bütün seviyeler için tek bir meslek koşulu söylenmemelidir.`},{tip:`h3`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitimi iş garantisi sağlar mı?`},{tip:`p`,metin:`Hayır. Eğitim veya yetkilendirme, tek başına iş garantisi anlamına gelmez.`},{tip:`h3`,metin:`Yangın Güvenlik Uzmanı (YGU) ile iş güvenliği uzmanı aynı meslek mi?`},{tip:`p`,metin:`Hayır. Yangın Güvenlik Uzmanlığı (YGU) ile iş güvenliği uzmanlığı farklı mevzuat ve yetkilendirme sistemleriyle değerlendirilmelidir. Aynı kişinin iki alanda yetkinlik kazanması, her iki sistemin koşullarını sağlamasına bağlıdır.`},{tip:`h2`,id:`sonuc`,metin:`Sonuç`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU), teknik bilgi, mevzuat ve saha inceleme becerilerini bir araya getiren bir uzmanlık alanı olarak önem kazanmaktadır.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU) olmak isteyen kişiler için mesleki gelişim fırsatları bulunabilir. Ancak bunların kapsamını belirleyecek temel unsurlar, kesinleşmiş eğitim ve yetkilendirme şartları ile uygulamadaki gerçek ihtiyaçlardır.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitimi, bu alanda uzmanlaşmak isteyen kişilerin teknik bilgi ve değerlendirme becerilerini geliştirmesi bakımından önem taşır.`},{tip:`p`,metin:`YGU eğitimi veren üniversiteler, eğitim şartları, başvuru tarihleri ve yetkilendirme süreçleri konusunda doğrulanmış bilgiler esas alınmalıdır.`}],kaynakBaslik:`Kaynakça`,kaynaklar:[{metin:`3194 Sayılı İmar Kanunu`},{metin:`Binaların Yangından Korunması Hakkında Yönetmelik`},{metin:`Binaların Yangından Korunması Hakkında Yönetmelik Kılavuzu`},{metin:`Yangın Güvenlik Uzmanlığı ve Periyodik Kontrol Usul ve Esasları Hakkında Yönetmelik Taslağı`}],sss:[{soru:`Yangın Güvenlik Uzmanlığı (YGU) geleceği olan bir alan mı?`,yanit:`Yangın güvenliğine ilişkin kanuni düzenlemeler ve yapıların sürekli değerlendirilmesi ihtiyacı, bu alanın gelişim potansiyelini göstermektedir. Ancak istihdam ve gelir beklentileri kesin değildir.`},{soru:`Yangın Güvenlik Uzmanı (YGU) olmak için mühendis olmak şart mı?`,yanit:`Başvuru hakkı, ilgili uzmanlık seviyesinin mevzuatta belirlenen öğrenim ve yeterlilik koşullarına bağlıdır. Kesin şartlar doğrulanmadan bütün seviyeler için tek bir meslek koşulu söylenmemelidir.`},{soru:`Yangın Güvenlik Uzmanlığı (YGU) eğitimi iş garantisi sağlar mı?`,yanit:`Hayır. Eğitim veya yetkilendirme, tek başına iş garantisi anlamına gelmez.`},{soru:`Yangın Güvenlik Uzmanı (YGU) ile iş güvenliği uzmanı aynı meslek mi?`,yanit:`Hayır. Yangın Güvenlik Uzmanlığı (YGU) ile iş güvenliği uzmanlığı farklı mevzuat ve yetkilendirme sistemleriyle değerlendirilmelidir. Aynı kişinin iki alanda yetkinlik kazanması, her iki sistemin koşullarını sağlamasına bağlıdır.`}]},{no:`04`,baslik:`Yangın Güvenlik Uzmanlığı (YGU) Eğitimine Nasıl Hazırlanılır? Yangın Güvenlik Uzmanı (YGU) Adayları İçin Hazırlık Rehberi`,ozet:`Yangın Güvenlik Uzmanlığı (YGU) eğitimi almak isteyen kişiler için en önemli hazırlık, yangın güvenliği mevzuatını ve teknik sistemleri birbiriyle ilişkili biçimde öğrenmektir.`,bloklar:[{tip:`p`,metin:`Yangın güvenliği farklı disiplinlerin bilgilerini gerektirdiği için yalnızca bir yönetmeliği okumak veya yangın söndürme sistemlerinin adlarını öğrenmek yeterli değildir.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU) olmak isteyen bir kişinin yapının kullanım özelliklerini, kaçış düzenini, yangından korunma sistemlerini ve sahadaki gerçek koşulları birlikte değerlendirebilmesi gerekir.`},{tip:`p`,metin:`Peki, Yangın Güvenlik Uzmanlığı (YGU) eğitimine hazırlanırken hangi konulara çalışılmalı? YGU eğitimine başlamadan önce hangi teknik beceriler geliştirilmelidir? Yangın güvenlik uzmanlığı eğitim müfredatı nasıl incelenmelidir?`},{tip:`p`,metin:`Bu rehberde eğitim öncesinde yapılabilecek teknik hazırlıkları sistemli biçimde ele alıyoruz.`},{tip:`h2`,id:`1-yangin-guvenlik-uzmanligi-ygu-egitimine-hazirlik-neden-onemlidir`,metin:`1. Yangın Güvenlik Uzmanlığı (YGU) Eğitimine Hazırlık Neden Önemlidir?`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitimi, yangın güvenliğiyle ilişkili birden fazla teknik alanı kapsayabilecek bir uzmanlık eğitimidir.`},{tip:`p`,metin:`Mühendislik, mimarlık veya başka bir teknik alandan gelen kişiler bazı konularda ön bilgi sahibi olabilir. Ancak bu, yangın güvenliğinin bütün yönleriyle bilindiği anlamına gelmez.`},{tip:`p`,metin:`Örneğin bir mimar kaçış yollarının projelendirilmesine aşina olabilirken yangın algılama sistemlerinin çalışma mantığı hakkında daha fazla bilgiye ihtiyaç duyabilir.`},{tip:`p`,metin:`Benzer şekilde mekanik tesisat konusunda deneyimli bir mühendis, yapı kullanım sınıfları ve mevcut binalara uygulanacak yangın güvenliği hükümlerini ayrıca öğrenmek isteyebilir.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU) adayının hazırlık sürecinde amacı, mevcut bilgi birikimini yangın güvenliği açısından tamamlamak olmalıdır.`},{tip:`h2`,id:`2-yangin-guvenlik-uzmanligi-ygu-mevzuati-nasil-ogrenilmeli`,metin:`2. Yangın Güvenlik Uzmanlığı (YGU) Mevzuatı Nasıl Öğrenilmeli?`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitimine hazırlıkta ilk temel kaynak Binaların Yangından Korunması Hakkında Yönetmelik'tir (BYKHY).`},{tip:`p`,metin:`Ancak BYKHY'yi baştan sona ezberlemeye çalışmak, mevzuatı doğru uygulamak için yeterli bir yöntem değildir.`},{tip:`p`,metin:`Öncelikle yönetmeliğin hangi konuları düzenlediği ve bu konular arasındaki ilişki öğrenilmelidir.`},{tip:`p`,metin:`Yapı kullanım sınıfları, kaçış güvenliği, yapı elemanlarının yangına dayanımı, yangın algılama sistemleri, söndürme sistemleri ve işletme sorumlulukları birbirinden bağımsız değildir.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU), belirli bir yapı için hangi hükümlerin uygulanabileceğini belirlerken yapının özelliklerini ve ilgili mevzuatın kapsamını birlikte değerlendirmelidir.`},{tip:`p`,metin:`Özellikle mevcut yapılarda ruhsat ve kullanım izinleri ile sonradan yapılan değişikliklerin incelenmesi gerekir.`},{tip:`p`,metin:`Bir yapının eski olması, her durumda eski yönetmelik hükümlerinin geçerli olduğu anlamına gelmez.`},{tip:`h2`,id:`3-yangin-bilimi-ygu-egitiminde-ne-kadar-onemlidir`,metin:`3. Yangın Bilimi YGU Eğitiminde Ne Kadar Önemlidir?`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitimine hazırlanan kişilerin yanma ve yangın davranışı hakkında temel bilgi edinmesi gerekir.`},{tip:`p`,metin:`Yanmanın oluşumu, ısı transferi, dumanın hareketi ve yangının kapalı hacimlerde gelişmesi, korunma önlemlerinin neden gerekli olduğunu anlamaya yardımcı olur.`},{tip:`p`,metin:`Örneğin bir yangında dumanın bir kaçış yoluna ulaşabilmesi, kaçış güvenliğini önemli ölçüde etkileyebilir.`},{tip:`p`,metin:`Yangın kapılarının, yangın bölmelerinin ve duman kontrol sistemlerinin işlevi bu teknik bağlamda daha iyi anlaşılır.`},{tip:`p`,metin:`Ancak Yangın Güvenlik Uzmanı (YGU) hazırlığı, gerekli olmayan ileri düzey yangın fiziği hesaplarına veya karmaşık modelleme çalışmalarına dönüştürülmemelidir.`},{tip:`p`,metin:`Öncelik, teknik mekanizmaların yapı güvenliği açısından doğru anlaşılmasıdır.`},{tip:`h2`,id:`4-yangin-guvenlik-uzmanligi-ygu-icin-mimari-proje-okuma`,metin:`4. Yangın Güvenlik Uzmanlığı (YGU) İçin Mimari Proje Okuma`},{tip:`p`,metin:`Yangın güvenlik uzmanı olmak isteyen kişilerin geliştirebileceği en önemli becerilerden biri mimari proje okumadır.`},{tip:`p`,metin:`Bir kat planında merdivenlerin, koridorların, kapıların, kullanım alanlarının ve yangın bölmelerinin nerede bulunduğu anlaşılabilmelidir.`},{tip:`p`,metin:`Proje üzerinde görülen düzenlemelerin sahada hangi yapı elemanlarına karşılık geldiği değerlendirilmelidir.`},{tip:`p`,metin:`Örneğin bir koridorun kaçış yolu olarak kullanılması öngörülmüşse bu koridorun gerçek kullanım koşulları da önemlidir.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitimi öncesinde örnek kat planlarını incelemek, yangın güvenliği hükümlerinin uygulanmasını daha anlaşılır hale getirebilir.`},{tip:`h2`,id:`5-kacis-yollari-ve-yangin-kapilari-nasil-calisilmali`,metin:`5. Kaçış Yolları ve Yangın Kapıları Nasıl Çalışılmalı?`},{tip:`p`,metin:`Kaçış yolları, Yangın Güvenlik Uzmanlığı (YGU) eğitiminde teknik değerlendirme gerektiren temel konulardandır.`},{tip:`p`,metin:`Hazırlık sırasında çıkış kavramı, kaçış yolunun sürekliliği, kaçış merdivenlerinin konumu, yangın kapılarının işlevi ve çıkışlara erişim gibi başlıklar öğrenilmelidir.`},{tip:`p`,metin:`Bunlar yalnızca ayrı ayrı yapı elemanları olarak değerlendirilmemelidir.`},{tip:`p`,metin:`Örneğin uygun özelliklere sahip bir yangın kapısının bulunması, kapıya ulaşan kaçış yolunun kullanım sırasında engellenmiş olması halinde tek başına yeterli olmayabilir.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU), böyle durumlarda kaçış düzeninin bütününü değerlendirebilecek bilgiye sahip olmalıdır.`},{tip:`h2`,id:`6-yangin-algilama-ve-sondurme-sistemleri-nasil-ogrenilmeli`,metin:`6. Yangın Algılama ve Söndürme Sistemleri Nasıl Öğrenilmeli?`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitimine hazırlıkta yangın algılama ve söndürme sistemlerinin temel işlevleri öğrenilmelidir.`},{tip:`p`,metin:`Yangın algılama sistemleri, alarmın oluşturulması ve gerekli uyarıların verilmesi açısından önem taşır.`},{tip:`p`,metin:`Sprinkler sistemleri, yangın dolapları, hidrantlar, yangın pompaları ve ilgili su kaynakları ise farklı yangından korunma ihtiyaçlarıyla ilişkilidir.`},{tip:`p`,metin:`Bir sistemin yalnızca adını bilmek yeterli değildir.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU), bu sistemlerin hangi amaçlarla kullanıldığını, projelerde nasıl gösterildiğini ve teknik belgelerde hangi bilgilerin yer aldığını anlayabilmelidir.`},{tip:`p`,metin:`Sistemlerin özel teknik hesaplarının, tasarımının veya gerekli testlerinin ilgili yetki ve yeterliliklere tabi olduğu unutulmamalıdır.`},{tip:`h2`,id:`7-yangin-guvenlik-uzmanligi-ygu-icin-mevcut-yapilari-inceleme`,metin:`7. Yangın Güvenlik Uzmanlığı (YGU) İçin Mevcut Yapıları İnceleme`},{tip:`p`,metin:`Yangın güvenliğinin değerlendirilmesinde yeni projeler kadar mevcut yapılar da önemlidir.`},{tip:`p`,metin:`Mevcut bir binanın onaylı projesi ile sahadaki durumu arasında farklılıklar bulunabilir.`},{tip:`p`,metin:`Kullanım amacı değişmiş, yeni bölmeler oluşturulmuş veya bazı teknik tesisatlarda değişiklik yapılmış olabilir.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitimine hazırlık sırasında bu tür değişikliklerin nasıl değerlendirileceği üzerinde çalışılmalıdır.`},{tip:`p`,metin:`Bunun için öncelikle yapının proje ve izin geçmişinin incelenmesi, ardından gerçek kullanım koşullarının belirlenmesi gerekir.`},{tip:`p`,metin:`Gözlemlenen her değişiklik otomatik olarak uygunsuzluk anlamına gelmez. İlgili mevzuatın, projelerin ve teknik gerekliliklerin birlikte değerlendirilmesi gerekir.`},{tip:`h2`,id:`8-yangin-guvenlik-uzmaninin-ygu-sahadaki-uygulamasi`,metin:`8. Yangın Güvenlik Uzmanının (YGU) Sahadaki Uygulaması`},{tip:`p`,metin:`Bir iş merkezinde yangın güvenliği incelemesi yapılacağını düşünelim.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU), görevinin kapsamına göre önce binanın kullanım amacını, onaylı mimari projesini, kullanım izinlerini ve varsa tadilat belgelerini inceler.`},{tip:`p`,metin:`Daha sonra katlardaki gerçek faaliyetleri ve mevcut kullanım biçimlerini belirler.`},{tip:`p`,metin:`Örneğin projede toplantı salonu olarak gösterilen bir alanın daha sonra farklı bir işleve dönüştürülmüş olması, kullanıcı yükü ve kaçış düzeni bakımından yeniden değerlendirme gerektirebilir.`},{tip:`p`,metin:`Bu durumda Yangın Güvenlik Uzmanı (YGU), gerçek faaliyet ile projedeki kullanım arasındaki farklılığı tespit eder.`},{tip:`p`,metin:`Ardından hangi mevzuat hükümlerinin uygulanacağını araştırır; mevcut belgeleri, saha gözlemlerini ve gerekli teknik raporları birlikte değerlendirir.`},{tip:`p`,metin:`YGU'nun görevi yalnızca farklılığı yazmak değildir. Farklılığın yangın güvenliği bakımından neden önemli olduğunu ve hangi teknik dayanağa sahip olduğunu açıklamaktır.`},{tip:`p`,metin:`Ancak gözlemsel inceleme, özel ölçüm veya test gerektiren teknik çalışmalarla karıştırılmamalıdır.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitimi, bu tür saha kararlarının doğru verilmesine yardımcı olacak bilgi ve değerlendirme becerilerini geliştirmelidir.`},{tip:`h2`,id:`9-yangin-guvenlik-uzmanligi-ygu-egitimine-hazirlik-icin-ornek-calisma-plani`,metin:`9. Yangın Güvenlik Uzmanlığı (YGU) Eğitimine Hazırlık İçin Örnek Çalışma Planı`},{tip:`p`,metin:`Resmî eğitim programının yerini almamak üzere aşağıdaki hazırlık sırası kullanılabilir.`},{tip:`h3`,metin:`Birinci aşama: Mevzuatın temel yapısı`},{tip:`p`,metin:`BYKHY'nin kapsamı, yapı sınıfları ve temel yangın güvenliği kavramları öğrenilir.`},{tip:`h3`,metin:`İkinci aşama: Mimari yangın güvenliği`},{tip:`p`,metin:`Kaçış yolları, yangın merdivenleri, kapılar, bölmeler ve yapı elemanlarının yangına dayanım özellikleri incelenir.`},{tip:`h3`,metin:`Üçüncü aşama: Yangından korunma sistemleri`},{tip:`p`,metin:`Yangın algılama, uyarı, söndürme ve duman kontrol sistemlerinin temel işlevleri öğrenilir.`},{tip:`h3`,metin:`Dördüncü aşama: Proje inceleme`},{tip:`p`,metin:`Örnek mimari ve tesisat projeleri üzerinde yangın güvenliği düzenlemeleri belirlenir.`},{tip:`h3`,metin:`Beşinci aşama: Saha değerlendirmesi`},{tip:`p`,metin:`Proje ile mevcut kullanım koşullarının nasıl karşılaştırılacağına yönelik örnek çalışmalar yapılır.`},{tip:`h3`,metin:`Altıncı aşama: Raporlama`},{tip:`p`,metin:`Bir teknik tespitin gözlem, belge ve mevzuat dayanaklarıyla nasıl açıklanabileceği üzerinde çalışılır.`},{tip:`p`,metin:`Bu çalışma sırası, zorunlu YGU eğitim müfredatı veya resmî ders takvimi değildir. Eğitim öncesi bireysel hazırlık önerisidir.`},{tip:`h2`,id:`10-yangin-guvenlik-uzmanligi-ygu-egitim-mufredati-nasil-takip-edilmeli`,metin:`10. Yangın Güvenlik Uzmanlığı (YGU) Eğitim Müfredatı Nasıl Takip Edilmeli?`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitimine ilişkin taslak düzenlemeler, uzmanlık seviyeleri ve eğitim konuları bakımından önemli bilgiler içerebilir.`},{tip:`not`,etiket:`TASLAK`,metin:`Yönetmelik taslağında yer alan eğitim ve uzmanlık düzenlemeleri, nihai haliyle kabul edilmedikçe kesinleşmiş zorunlu koşullar olarak değerlendirilmemelidir.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU) olmak isteyen kişiler, resmî eğitim müfredatı açıklandığında modül içeriklerini, sürelerini, teorik ve uygulamalı bölümlerini ayrı ayrı incelemelidir.`},{tip:`p`,metin:`Özellikle eğitim programının hangi uzmanlık seviyesine yönelik olduğunun belirlenmesi önemlidir.`},{tip:`p`,metin:`TASLAK KARŞILAŞTIRMASI — TASLAK EK-2 teorik eğitim toplamları YGU-1 için 65, YGU-2 için 85, YGU-3 için 40 ek ve YGU-K için 35 saattir. Taslak Madde 9 ayrıca farklı kullanım sınıfındaki iki yapı üzerinden uygulama eğitimi ve teorik eğitime en az %90 devam şartı düzenler. Bireysel hazırlık planı bu resmî taslak yapıdan ayrı tutulmalı; çalışma planı, geçerli eğitim kurumu ve sınav duyurusu yerine sunulmamalıdır.`},{tip:`h2`,id:`11-ygu-egitimi-veren-universiteler-basvuru-sartlari-ve-egitim-tarihleri`,metin:`11. YGU Eğitimi Veren Üniversiteler, Başvuru Şartları ve Eğitim Tarihleri`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitimine hazırlanan kişilerin teknik konuların yanında eğitim sürecine ilişkin duyuruları da takip etmesi gerekir.`},{tip:`p`,metin:`YGU eğitimi veren üniversiteler ve yangın güvenlik uzmanlığı eğitimi veren yerler araştırılırken ilgili kurumun resmî yetkilendirmesi kontrol edilmelidir.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitim şartları, başvuru belgeleri ve uzmanlık seviyelerine ilişkin koşullar kesinleşmiş mevzuattan doğrulanmalıdır.`},{tip:`p`,metin:`Ayrıca YGU eğitim ücretleri ile eğitim tarihleri, yetkili kurumların güncel duyurularından öğrenilmelidir.`},{tip:`p`,metin:`Bir kurumun genel yangın güvenliği sertifika programı düzenlemesi, aynı kurumun resmî Yangın Güvenlik Uzmanlığı (YGU) eğitimi verdiği anlamına gelmez.`},{tip:`h2`,id:`12-yangin-guvenlik-uzmanligi-ygu-egitimine-hazirlik-hakkinda-sik-sorulan-sorular`,metin:`12. Yangın Güvenlik Uzmanlığı (YGU) Eğitimine Hazırlık Hakkında Sık Sorulan Sorular`},{tip:`h3`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitimine başlamadan önce BYKHY okunmalı mı?`},{tip:`p`,metin:`Evet. Yönetmeliğin temel sistematiğini öğrenmek, eğitim konularını anlamayı kolaylaştırır. Ancak ezber yerine hükümlerin hangi yapı koşullarında uygulandığı üzerinde çalışılmalıdır.`},{tip:`h3`,metin:`Yangın Güvenlik Uzmanı (YGU) olmak için proje okuma bilmek gerekli mi?`},{tip:`p`,metin:`Proje okuma becerisi, yangın güvenliğine ilişkin teknik değerlendirmeler açısından önemlidir. Resmî yeterlilik şartları ise ilgili mevzuatla belirlenir.`},{tip:`h3`,metin:`YGU eğitimi için yangın fiziği bilmek gerekir mi?`},{tip:`p`,metin:`Yanma, ısı transferi, duman hareketi ve yangının gelişimi hakkında temel bilgi edinilmesi yararlıdır. Gereksiz ileri hesaplamalar yerine uygulamaya yönelik teknik anlayış geliştirilmelidir.`},{tip:`h3`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitimine hazırlanırken hangi kaynaklardan yararlanılabilir?`},{tip:`p`,metin:`BYKHY, Bakanlığın ilgili kılavuzu, yangın güvenliği teknik dokümanları ve doğrulanmış eğitim kaynakları kullanılabilir. Taslak hükümler yürürlükteki hükümlerden ayrı değerlendirilmelidir.`},{tip:`h3`,metin:`YGU eğitim başvurusu yapılmadan hazırlığa başlanabilir mi?`},{tip:`p`,metin:`Evet. Mevzuat, proje okuma ve yangından korunma sistemleri üzerine çalışmak için resmî başvuru takviminin başlaması gerekmez.`},{tip:`h2`,id:`sonuc`,metin:`Sonuç`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitimine hazırlanmanın en etkili yolu, yangın güvenliği konularını birbirinden kopuk bilgiler olarak değil, bir yapının bütün güvenlik düzeninin parçaları olarak öğrenmektir.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU) için temel yetkinlik, mevzuat bilgisini proje, teknik belge ve saha koşullarıyla ilişkilendirebilmektir.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitimi almak isteyen kişiler, temel yangın güvenliği bilgilerini geliştirirken resmî eğitim şartlarını, yetkilendirilmiş üniversiteleri, YGU eğitim başvurularını ve eğitim tarihlerini de takip etmelidir.`},{tip:`p`,metin:`Bu hazırlık, resmî eğitimin yerine geçmez; ancak eğitime daha güçlü bir teknik altyapıyla başlanmasına yardımcı olabilir.`}],kaynakBaslik:`Kaynakça`,kaynaklar:[{metin:`3194 Sayılı İmar Kanunu`},{metin:`Binaların Yangından Korunması Hakkında Yönetmelik`},{metin:`Binaların Yangından Korunması Hakkında Yönetmelik Kılavuzu`},{metin:`Yangın Güvenlik Uzmanlığı ve Periyodik Kontrol Usul ve Esasları Hakkında Yönetmelik Taslağı`}],sss:[{soru:`Yangın Güvenlik Uzmanlığı (YGU) eğitimine başlamadan önce BYKHY okunmalı mı?`,yanit:`Evet. Yönetmeliğin temel sistematiğini öğrenmek, eğitim konularını anlamayı kolaylaştırır. Ancak ezber yerine hükümlerin hangi yapı koşullarında uygulandığı üzerinde çalışılmalıdır.`},{soru:`Yangın Güvenlik Uzmanı (YGU) olmak için proje okuma bilmek gerekli mi?`,yanit:`Proje okuma becerisi, yangın güvenliğine ilişkin teknik değerlendirmeler açısından önemlidir. Resmî yeterlilik şartları ise ilgili mevzuatla belirlenir.`},{soru:`YGU eğitimi için yangın fiziği bilmek gerekir mi?`,yanit:`Yanma, ısı transferi, duman hareketi ve yangının gelişimi hakkında temel bilgi edinilmesi yararlıdır. Gereksiz ileri hesaplamalar yerine uygulamaya yönelik teknik anlayış geliştirilmelidir.`},{soru:`Yangın Güvenlik Uzmanlığı (YGU) eğitimine hazırlanırken hangi kaynaklardan yararlanılabilir?`,yanit:`BYKHY, Bakanlığın ilgili kılavuzu, yangın güvenliği teknik dokümanları ve doğrulanmış eğitim kaynakları kullanılabilir. Taslak hükümler yürürlükteki hükümlerden ayrı değerlendirilmelidir.`},{soru:`YGU eğitim başvurusu yapılmadan hazırlığa başlanabilir mi?`,yanit:`Evet. Mevzuat, proje okuma ve yangından korunma sistemleri üzerine çalışmak için resmî başvuru takviminin başlaması gerekmez.`}]},{no:`05`,baslik:`Yangın Güvenlik Uzmanı (YGU) Nasıl Olunur? Yangın Güvenlik Uzmanlığı (YGU) Eğitimi, Sınav ve Yetkilendirme Süreci`,ozet:`Yangın güvenlik uzmanı (YGU) nasıl olunur sorusunun cevabı, yalnızca bir kursa kayıt olmaktan ibaret değildir. Yangın Güvenlik Uzmanlığı (YGU) için uygun öğrenim alanının bulunması, doğru seviyeye başvurulması, resmî teorik ve uygulamalı eğitim, sınav ve yetkilendirme aşamalarının tamamlanması gerekir. Bu aşamaları birbirine karıştırmak, bir eğitim sertifikasının resmî uzmanlık yetkisiyle eş tutulmasına yol açabilir.`,bloklar:[{tip:`not`,etiket:`MEVZUAT DURUMU`,metin:`22 Mayıs 2026 tarihli kanun değişikliğiyle yangın güvenliği periyodik kontrollerine ilişkin kanuni çerçeve kurulmuştur. Aşağıdaki seviye, eğitim, sınav, belge ve uygulama ayrıntıları ise YGU yönetmelik TASLAĞIndan aktarılmıştır; kesinleşmiş uygulama kuralı değildir.`},{tip:`h2`,id:`1-hangi-ygu-seviyesi-benim-icin-uygun`,metin:`1. Hangi YGU seviyesi benim için uygun?`},{tip:`p`,metin:`TASLAK Madde 5, dört uzmanlık seviyesini düzenler. YGU-1, belirli teknikerlik ve itfaiyecilik ön lisans öğrenimlerine; YGU-2, belirtilen mühendislik dalları ile mimarlığa; YGU-K, kimya mühendisliği veya kimya lisans öğrenimine yöneliktir. YGU-3 için genel geçiş yolu, YGU-2 yetki belgesi ve son bir yılda en az iki farklı kullanım sınıfından dört yapıda usulüne uygun yangın güvenlik raporu düzenleme şartını içerir.`},{tip:`p`,metin:`Başvuru hakkı bir kişinin mevcut iş unvanından değil, taslakta açıkça tanımlanan öğrenim ve diğer koşullardan değerlendirilmelidir. Örneğin A sınıfı iş güvenliği uzmanlığı belgesi, bütün mühendislik dalları için YGU-2 başvuru hakkı anlamına gelmez.`},{tip:`h2`,id:`2-yangin-guvenlik-uzmanligi-ygu-egitimi-nasil-duzenlenebilir`,metin:`2. Yangın Güvenlik Uzmanlığı (YGU) eğitimi nasıl düzenlenebilir?`},{tip:`p`,metin:`TASLAK Madde 9 iki aşamalı sistem öngörür. Teorik eğitim Bakanlık veya Bakanlığın yetkilendirdiği eğitici kuruluşlar; uygulama eğitimi mahalli itfaiye teşkilatı tarafından verilir. Teorik dersler yüz yüze veya uzaktan yapılabilir. Taslakta katılım belgesi için teorik eğitime en az %90 devam şartı bulunur.`},{tip:`p`,metin:`Uygulama eğitimi, farklı kullanım sınıfındaki iki yapıyla ilgili yangın güvenlik raporu düzenleme ve uygulama gözetimi faaliyetlerini içerir. Bu nedenle yalnızca teorik derslerde bulunmak, taslağın öngördüğü bütün eğitim aşamalarının tamamlandığı anlamına gelmez.`},{tip:`h2`,id:`3-ygu-1-ygu-2-ygu-3-ve-ygu-k-teorik-egitim-sureleri`,metin:`3. YGU-1, YGU-2, YGU-3 ve YGU-K teorik eğitim süreleri`},{tip:`p`,metin:`TASLAK EK-2 modül toplamları, YGU-1 için 65 saat, YGU-2 için 85 saat, YGU-3 için 40 saatlik ek eğitim ve YGU-K için 35 saat öngörmektedir. Bu toplamlar EK-2 tablosundaki modül süreleri yeniden toplanarak doğrulanmıştır. Uygulamalı eğitimin gerçek takvimi, teorik modül toplamlarından çıkarılamaz.`},{tip:`p`,metin:`YGU-1 ile YGU-2'nin konu başlıkları yer yer benzese de modüllerin derinliği farklıdır. YGU-3'te yüksek tehlikeli yapılar ve uluslararası teknik dokümanlar; YGU-K'de tehlikeli maddelerin tespiti ve sınıflandırılması öne çıkmaktadır.`},{tip:`h2`,id:`4-ygu-egitim-basvurusunda-hangi-belgeler-gerekir`,metin:`4. YGU eğitim başvurusunda hangi belgeler gerekir?`},{tip:`p`,metin:`TASLAK Madde 10, kimlik ve fotoğraf, adli sicil, diploma/mezuniyet veya denklik, gerektiğinde meslek odası kaydı, YGU-3 için deneyim kanıtı, KEP adresi belgesi ve belirtilen bilgilendirme iznine ilişkin belgeyi saymaktadır. Başvuru ilanı yetkili kurumun resmî sayfasında duyurulmalıdır.`},{tip:`p`,metin:`YGU eğitim başvurusu, bir binanın periyodik kontrolü için kullanılan EK-5 formuyla karıştırılmamalıdır. EK-5 yapı ve kontrol başvurusuna ilişkin olup adayın resmî eğitim belgesi listesi Madde 10'da yer alır.`},{tip:`h2`,id:`5-yangin-guvenlik-uzmanligi-ygu-sinavi-nasil-olacak`,metin:`5. Yangın Güvenlik Uzmanlığı (YGU) sınavı nasıl olacak?`},{tip:`p`,metin:`TASLAK Madde 11, sınavın Bakanlıkça teorik eğitim konularını kapsayacak biçimde düzenlenmesini öngörür. YGU-1/2/3 için en az 50, YGU-K için en az 25 çoktan seçmeli soru ve 100 üzerinden en az 70 başarı koşulu taslakta belirtilmiştir. Bu bilgiler nihai sınav ilanının yerine geçmez.`},{tip:`p`,metin:`Aynı maddenin 4. fıkrası, Komisyonun zorunlu belgelerde eksiklik tespit etmesi halinde 15 günlük tamamlama süresi öngörür; eksiklik tamamlanmazsa kişinin sınava alınmaması düzenlenir. Bu hüküm her üniversitenin kayıt koşulu olarak ayrı yorumlanmamalıdır.`},{tip:`h2`,id:`6-sinavdan-sonra-ygu-yetki-belgesi-nasil-alinabilir`,metin:`6. Sınavdan sonra YGU yetki belgesi nasıl alınabilir?`},{tip:`p`,metin:`TASLAK Madde 13, sınavda başarılı olanlara elektronik ortamdan doğrulanabilir yetki belgesi düzenlenmesini ve beş yıllık geçerlilik süresini öngörür. Yenilemenin eğitimlere yeniden katılmadan sınavla yapılabilmesine ilişkin koşullar da taslakta vardır. Bunlar belgenin fiilen verilmeye başlandığına ilişkin bir duyuru değildir.`},{tip:`p`,metin:`Bir kişinin belgesinin bulunması bile tek başına bütün binalarda sınırsız kontrol yetkisi sağlamaz. Hangi yapı ve işlem için görev alabileceği, mahalli itfaiye teşkilatının kanuni rolü, taslak Madde 6 ve EK-1 ile ilişkilidir.`},{tip:`h2`,id:`7-sahada-yangin-guvenlik-uzmaninin-ygu-calisma-yontemi`,metin:`7. Sahada Yangın Güvenlik Uzmanının (YGU) çalışma yöntemi`},{tip:`p`,metin:`Bir ticaret yapısında kontrol yapılacağını düşünelim. Yangın Güvenlik Uzmanı (YGU), görevinin kapsamına göre önce yapının onaylı projelerini, kullanım izinlerini ve varsa tadilat kayıtlarını inceler; gerçek kullanım sınıfını belirler. Kaçış yolları, yangın kapıları, alarm ve söndürme sistemlerine ilişkin gözlem ve teknik belgeleri karşılaştırır.`},{tip:`p`,metin:`Proje ile sahada farklılık görülmesi otomatik uygunsuzluk sonucuna eşit değildir. Hangi mevzuat hükmünün uygulanacağı ve değişikliğin teknik etkisi ayrı gerekçelendirilmelidir. Özel tasarım, ölçüm ve test işlemleri, YGU'nun genel görevinin kendiliğinden uzantısı olarak kabul edilmemelidir.`},{tip:`h2`,id:`sik-sorulan-sorular`,metin:`Sık sorulan sorular`},{tip:`h3`,metin:`YGU olmak için yalnızca sertifika yeterli mi?`},{tip:`p`,metin:`Hayır; taslak, meslek şartı, eğitim, sınav ve resmî yetkilendirmeyi ayrı aşamalar olarak düzenler.`},{tip:`h3`,metin:`Bütün üniversiteler YGU eğitimi verebilir mi?`},{tip:`p`,metin:`Genel kurs açabilmek resmî YGU eğitim yetkisi demek değildir; kurumun ilgili yetkilendirmesi doğrulanmalıdır.`},{tip:`h3`,metin:`YGU eğitimleri ne zaman başlayacak?`},{tip:`p`,metin:`Doğrulanmış yetkili kurum ilanı olmadan kesin tarih verilemez.`},{tip:`h3`,metin:`YGU-K, YGU-3'ten sonra alınan kademe mi?`},{tip:`p`,metin:`Hayır. Kimya alanıyla ilişkili özel uzmanlık grubudur.`},{tip:`h2`,id:`sonuc`,metin:`Sonuç`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU) olma yolu, doğru seviyenin belirlenmesiyle başlar; resmî eğitim, uygulama, sınav ve yetkilendirme ile devam eder. Taslak, bu sürecin ayrıntılarını göstermektedir; ancak fiili başvuru ve yetki kararlarında nihai mevzuat ile resmî duyurular esas alınmalıdır.`}],kaynakBaslik:`Kaynakça`,kaynaklar:[{metin:`3194 Sayılı İmar Kanunu`},{metin:`7579 Sayılı Tapu Kanunu ile Bazı Kanunlarda ve 375 Sayılı Kanun Hükmünde Kararnamede Değişiklik Yapılmasına Dair Kanun`},{metin:`Binaların Yangından Korunması Hakkında Yönetmelik`},{metin:`Yangın Güvenlik Uzmanlığı ve Periyodik Kontrol Usul ve Esasları Hakkında Yönetmelik Taslağı`}],sss:[{soru:`YGU olmak için yalnızca sertifika yeterli mi?`,yanit:`Hayır; taslak, meslek şartı, eğitim, sınav ve resmî yetkilendirmeyi ayrı aşamalar olarak düzenler.`},{soru:`Bütün üniversiteler YGU eğitimi verebilir mi?`,yanit:`Genel kurs açabilmek resmî YGU eğitim yetkisi demek değildir; kurumun ilgili yetkilendirmesi doğrulanmalıdır.`},{soru:`YGU eğitimleri ne zaman başlayacak?`,yanit:`Doğrulanmış yetkili kurum ilanı olmadan kesin tarih verilemez.`},{soru:`YGU-K, YGU-3'ten sonra alınan kademe mi?`,yanit:`Hayır. Kimya alanıyla ilişkili özel uzmanlık grubudur.`}]},{no:`06`,baslik:`Kimler Yangın Güvenlik Uzmanlığı (YGU) Eğitimine Başvurabilir? Meslekler, Diplomalar ve Eğitim Şartları`,ozet:`Yangın Güvenlik Uzmanlığı (YGU) eğitimine kimlerin başvurabileceği sorusu, yalnızca meslek unvanına bakılarak cevaplandırılamaz. Temel öğrenim, başvurulacak uzmanlık seviyesi, varsa uygulama deneyimi ve genel kabul şartları birlikte değerlendirilmelidir. Bir kişinin iş güvenliği uzmanı, itfaiye personeli veya yangın sistemleri konusunda deneyimli olması, kendiliğinden bütün YGU seviyelerine kabul hakkı sağlamaz.`,bloklar:[{tip:`not`,etiket:`MEVZUAT DURUMU – TASLAK`,metin:`Aşağıdaki meslek eşleştirmeleri ve eğitim başvurusu koşulları, Kitaplık'taki Yangın Güvenlik Uzmanlığı ve Periyodik Kontrol Usul ve Esasları Hakkında Yönetmelik Taslağına dayanmaktadır. Nihai yönetmelik ve resmî başvuru duyurusu doğrulanmadan kesin başvuru hakkı olarak yorumlanmamalıdır.`},{tip:`h2`,id:`1-yangin-guvenlik-uzmanligi-ygu-basvurusunda-once-hangi-bilgiye-bakilir`,metin:`1. Yangın Güvenlik Uzmanlığı (YGU) başvurusunda önce hangi bilgiye bakılır?`},{tip:`p`,metin:`İlk kontrol, diplomada veya resmî mezuniyet kaydında yer alan öğrenim alanıdır. Taslak Madde 5, YGU-1, YGU-2 ve YGU-K için belirli meslek ve öğrenim gruplarını sayarken YGU-3 için ayrıca önceden edinilmiş YGU-2 yetkisi ve uygulama geçmişi aramaktadır. Dolayısıyla “mühendisim” veya “teknikerim” demek yerine hangi mühendislik ya da teknikerlik programından mezun olunduğu belirlenmelidir.`},{tip:`p`,metin:`Mesleki deneyim, gerektiğinde teknik yeterliliği destekleyebilir; ancak açıkça belirtilen diploma şartının yerine geçtiği varsayılamaz. Başvuru aşamasında diploma, unvan ve belge türleri aynı anlama gelmez.`},{tip:`h2`,id:`2-ygu-1-egitimine-hangi-meslekler-basvurabilir`,metin:`2. YGU-1 eğitimine hangi meslekler başvurabilir?`},{tip:`not`,etiket:`TASLAK Madde 5/2-a`,metin:`Makine teknikeri, inşaat teknikeri, elektrik teknikeri, elektrik ve elektronik teknikeri olanlar ile itfaiyecilik alanında iki yıllık ön lisans öğrenimini tamamlayanlar YGU-1 grubu için sayılmıştır.`},{tip:`p`,metin:`Burada iki farklı durum ayrılmalıdır: İtfaiyede görev yapan herkesin itfaiyecilik ön lisans mezunu olduğu varsayılamaz; teknik ön lisans diploması bulunan herkes de taslakta sayılan dallardan mezun olmayabilir. YGU-1 için öğrenim alanı, yetkili kurumun inceleyeceği belge üzerinden doğrulanmalıdır.`},{tip:`h2`,id:`3-ygu-2-egitimine-hangi-muhendisler-ve-mimarlar-basvurabilir`,metin:`3. YGU-2 eğitimine hangi mühendisler ve mimarlar başvurabilir?`},{tip:`not`,etiket:`TASLAK Madde 5/2-b`,metin:`Mimar; inşaat mühendisi; makine mühendisi; elektrik mühendisi; elektronik mühendisi; elektrik ve elektronik mühendisi unvanları sayılmıştır.`},{tip:`p`,metin:`Bu liste tüm mühendislik fakültesi mezunlarını kapsayan genel bir ifade değildir. Örneğin sadece iş sağlığı ve güvenliği alanında yüksek lisans yapmış olmak veya A sınıfı iş güvenliği uzmanlığı belgesine sahip olmak, taslakta sayılmayan bir temel mühendislik diplomasını YGU-2 koşulunu sağlamış hale getirmez.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU) adayının akademik unvanı, diploma programı ve varsa meslek kuruluşu kaydı birbirinden bağımsız olarak değerlendirilmelidir.`},{tip:`h2`,id:`4-kimya-muhendisleri-ve-kimya-lisans-mezunlari-hangi-seviyeye-yonelir`,metin:`4. Kimya mühendisleri ve kimya lisans mezunları hangi seviyeye yönelir?`},{tip:`not`,etiket:`TASLAK Madde 5/2-d`,metin:`Kimya mühendisleri ve kimya alanında lisans eğitimini tamamlayanlar YGU-K için öngörülmüştür. YGU-K, YGU-3'ün üzerindeki genel bir kademe değildir; yüksek tehlikeli yapıların periyodik kontrolünde tehlikeli maddelerin tespiti ve sınıflandırılmasıyla ilişkilendirilen özel görev alanıdır.`},{tip:`p`,metin:`Bu nedenle kimya mühendisliği mezununun yalnızca diploması nedeniyle YGU-2 veya YGU-3 yetkisine de sahip olacağı sonucuna varılamaz. Başka bir öğrenim veya özel istisna varsa bunlar ayrıca değerlendirilmelidir.`},{tip:`h2`,id:`5-ygu-3-icin-diploma-yeterli-midir`,metin:`5. YGU-3 için diploma yeterli midir?`},{tip:`not`,etiket:`TASLAK Madde 5/2-c`,metin:`Genel geçiş yolunda kişinin YGU-2 yetki belgesine sahip olması ve son bir yıl içinde en az iki farklı bina kullanım sınıfından en az dört yapıya ilişkin yangın güvenlik raporunu usulüne uygun düzenlemiş olması öngörülmektedir.`},{tip:`p`,metin:`Süre şartı ile rapor sayısı birlikte ele alınmalıdır. Dört raporun yalnızca tek yapı kullanım sınıfından olması, metindeki “en az iki farklı kullanım sınıfı” koşuluyla aynı değildir. Madde 14'te belirli Bakanlık personeline ilişkin özel muafiyet bulunması, genel adaylar için bu koşulların ortadan kalktığı anlamına gelmez.`},{tip:`h2`,id:`6-ygu-egitimine-basvururken-hangi-genel-sartlar-aranabilir`,metin:`6. YGU eğitimine başvururken hangi genel şartlar aranabilir?`},{tip:`not`,etiket:`TASLAK Madde 7`,metin:`Belirli mahkumiyetler ve mesleki/disiplin yaptırımları bakımından kabul koşulları; eğitimin ve sınavın başarıyla tamamlanması; 75 yaşını dolduranların göreve engel durum bulunmadığını belgelemeleri ve diğer şartlar yer almaktadır. Bu koşulların tam kapsamı ilan metninden ve nihai mevzuattan okunmalıdır.`},{tip:`p`,metin:`Bu tür genel şartlar, mesleğe başvuru koşullarıdır. Yangın Güvenlik Uzmanlığı (YGU) eğitimine yönelik kurum içi değerlendirme puanı veya yeni bir performans ölçeği oluşturulması anlamına gelmez.`},{tip:`h2`,id:`7-egitim-basvurusu-icin-hangi-belgeler-ongoruluyor`,metin:`7. Eğitim başvurusu için hangi belgeler öngörülüyor?`},{tip:`not`,etiket:`TASLAK Madde 10`,metin:`Kimlik bilgisi (yabancılar için ilgili kimlik ve çalışma izni), vesikalık fotoğraf, başvuru tarihinden önceki üç ay içinde alınmış adli sicil belgesi, diploma/mezuniyet veya denklik belgesi, gerektiğinde son altı ay içinde alınmış oda faaliyet/kayıt belgesi, YGU-3 için deneyimi tevsik eden belge, KEP adresi belgesi ve belirtilen bilgilendirme/yayın iznine ilişkin belge listelenmektedir.`},{tip:`p`,metin:`Listeyi “sadece diploma ve fotoğraf” diye özetlemek eksik olur. Bununla birlikte resmî başvuru ekranı açılmadan belge formatları, son yükleme tarihi veya ek kurum talepleri konusunda kesin işlem talimatı verilemez. Taslak EK-5 ise eğitim adayının belge listesi değil, yapıların periyodik kontrol başvuru ve taahhütname formlarıyla ilgilidir.`},{tip:`h2`,id:`8-is-guvenligi-uzmanlari-ve-itfaiye-personeli-icin-farkli-bir-yol-var-mi`,metin:`8. İş güvenliği uzmanları ve itfaiye personeli için farklı bir yol var mı?`},{tip:`p`,metin:`İş güvenliği uzmanlığı belgesi YGU yetki belgesinin yerine geçmez. A, B veya C sınıfına sahip olmak, Madde 5'teki öğrenim gruplarını değiştirmez. Benzer biçimde itfaiyede görev yapmakla taslakta aranan öğrenim şartına sahip olmak aynı değildir.`},{tip:`p`,metin:`TASLAK Madde 14, Bakanlığın merkez teşkilatında yangın mevzuatı konusunda en az üç yıl çalışmış, belirli temel mesleklere sahip personel için eğitim ve sınav muafiyeti öngörmektedir. Bu dar düzenleme, bütün iş güvenliği uzmanlarına veya bütün itfaiye personeline muafiyet tanındığı anlamına gelmez.`},{tip:`h2`,id:`9-saha-ornegi-basvurudan-gorev-sinirina`,metin:`9. Saha örneği: Başvurudan görev sınırına`},{tip:`p`,metin:`Bir makine mühendisi ve bir kimya mühendisi aynı endüstriyel tesiste yangın güvenliğiyle ilgili çalışıyor olsun. İlk kişinin taslak kapsamındaki başlangıç başvuru grubu YGU-2; ikinci kişinin ise YGU-K olabilir. Her ikisi teknik açıdan yangın güvenliğine katkı sağlayabilir, ancak resmî kontrol ve tehlikeli madde sınıflandırması görevleri aynı değildir.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU) adayının eğitim seviyesini doğru belirlemesi, ileride hangi raporlama ve inceleme işlemlerinde yetkilendirilebileceğini anlaması açısından ilk teknik adımdır.`},{tip:`h2`,id:`sik-sorulan-sorular`,metin:`Sık sorulan sorular`},{tip:`h3`,metin:`Her mühendis YGU-2 olabilir mi?`},{tip:`p`,metin:`Taslakta meslekler tek tek sayılmıştır; bütün mühendislik dallarına otomatik hak verilmemektedir.`},{tip:`h3`,metin:`Kimyager YGU-1'e mi başvurur?`},{tip:`p`,metin:`Taslak, kimya lisans mezunlarını YGU-K altında düzenlemektedir.`},{tip:`h3`,metin:`A sınıfı iş güvenliği uzmanı doğrudan YGU-3 olur mu?`},{tip:`p`,metin:`Hayır; iş güvenliği uzmanlığı sınıfı tek başına YGU-3 koşullarının yerine geçmez.`},{tip:`h3`,metin:`YGU-3 rapor koşulu eğitim öncesinde mi sağlanır?`},{tip:`p`,metin:`Taslak Madde 5, YGU-3 kabul yeterliliğinin parçası olarak tanımlar. Kesin başvuru takvimi ve istenen kanıt türü resmî duyuruyla açıklanmalıdır.`},{tip:`h2`,id:`sonuc`,metin:`Sonuç`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitiminde en önemli başlangıç işi, temel öğrenimle uzmanlık seviyesini doğru eşleştirmektir. Diploma, önceki yetki belgesi, saha deneyimi ve genel şartlar birlikte ele alınmalı; taslak hükümler kesinleşmiş mesleğe kabul kuralı gibi kullanılmamalıdır.`}],kaynakBaslik:`Kaynakça`,kaynaklar:[{metin:`3194 Sayılı İmar Kanunu`},{metin:`Binaların Yangından Korunması Hakkında Yönetmelik`},{metin:`Yangın Güvenlik Uzmanlığı ve Periyodik Kontrol Usul ve Esasları Hakkında Yönetmelik Taslağı`}],sss:[{soru:`Her mühendis YGU-2 olabilir mi?`,yanit:`Taslakta meslekler tek tek sayılmıştır; bütün mühendislik dallarına otomatik hak verilmemektedir.`},{soru:`Kimyager YGU-1'e mi başvurur?`,yanit:`Taslak, kimya lisans mezunlarını YGU-K altında düzenlemektedir.`},{soru:`A sınıfı iş güvenliği uzmanı doğrudan YGU-3 olur mu?`,yanit:`Hayır; iş güvenliği uzmanlığı sınıfı tek başına YGU-3 koşullarının yerine geçmez.`},{soru:`YGU-3 rapor koşulu eğitim öncesinde mi sağlanır?`,yanit:`Taslak Madde 5, YGU-3 kabul yeterliliğinin parçası olarak tanımlar. Kesin başvuru takvimi ve istenen kanıt türü resmî duyuruyla açıklanmalıdır.`}]},{no:`07`,baslik:`İş Güvenliği Uzmanları Yangın Güvenlik Uzmanı (YGU) Olabilir mi? Yangın Güvenlik Uzmanlığı (YGU) Eğitimi ve Başvuru Şartları`,ozet:`İş güvenliği uzmanları, işyerlerinde yangın risklerinin değerlendirilmesi ve acil durum hazırlıklarıyla sıkça ilgilenmektedir. Bu nedenle Yangın Güvenlik Uzmanı (YGU) olup olamayacakları önemli bir başvuru sorusudur. Cevap, mevcut iş güvenliği uzmanlığı belgesinin sınıfına değil, ilgili YGU seviyesinde aranan temel öğrenim ve diğer şartlara bağlıdır.`,bloklar:[{tip:`not`,etiket:`MEVZUAT DURUMU – TASLAK`,metin:`Aşağıdaki YGU seviye ve muafiyet değerlendirmeleri YGU yönetmelik taslağının 5, 7 ve 14. maddelerine dayanır. İş güvenliği uzmanlığına ilişkin mevcut hak ve görevler ise kendi mevzuatı kapsamında kalır.`},{tip:`h2`,id:`1-a-sinifi-is-guvenligi-uzmani-otomatik-ygu-olur-mu`,metin:`1. A sınıfı iş güvenliği uzmanı otomatik YGU olur mu?`},{tip:`p`,metin:`Hayır. A sınıfı belge, iş sağlığı ve güvenliği alanında bir yetki sınıfıdır; Yangın Güvenlik Uzmanlığı (YGU) belgesinin yerine geçmez. Örneğin temel öğrenimi makine mühendisliği olan bir A sınıfı iş güvenliği uzmanı taslaktaki YGU-2 meslek listesinde yer alabilir. Buna karşılık başka bir mühendislik dalından mezun olmak, A sınıfı belgenin bulunması nedeniyle aynı otomatik YGU-2 başvuru hakkını doğurmaz.`},{tip:`p`,metin:`B ve C sınıfı iş güvenliği uzmanları bakımından da temel ilke değişmez: Taslak, başvuru gruplarını iş güvenliği uzmanlığı sınıfıyla değil, belirli teknikerlik, mühendislik, mimarlık ve kimya öğrenimleriyle tanımlar.`},{tip:`h2`,id:`2-hangi-temel-diplomalar-hangi-ygu-grubuna-karsilik-gelir`,metin:`2. Hangi temel diplomalar hangi YGU grubuna karşılık gelir?`},{tip:`p`,metin:`TASLAK Madde 5 YGU-1'de belirli tekniker ve itfaiyecilik ön lisans öğrenimlerini; YGU-2'de mimarlık ve sayılan mühendislik alanlarını; YGU-K'de kimya mühendisliği/kimya lisans öğrenimini belirtir. YGU-3 için ise genel yolda YGU-2 yetkisi ile raporlama deneyimi istenir.`},{tip:`p`,metin:`Bir kişinin iş güvenliği uzmanı olarak deneyim kazanması değerlidir; ancak temel mesleki öğrenimin veya YGU-3 geçişinde istenen özel rapor koşulunun yerini kendiliğinden almaz.`},{tip:`h2`,id:`3-uzun-yillar-isg-yapmis-olanlar-ygu-egitiminden-muaf-mi`,metin:`3. Uzun yıllar İSG yapmış olanlar YGU eğitiminden muaf mı?`},{tip:`p`,metin:`TASLAK Madde 14, Bakanlığın merkez teşkilatında yangın mevzuatı konusunda en az üç yıl çalışmış ve Madde 5'teki ilgili temel meslek gruplarına sahip belirli personel için özel eğitim ve sınav muafiyeti öngörür. Bu muafiyet, bütün A sınıfı iş güvenliği uzmanlarını veya bütün itfaiye çalışanlarını kapsayan genel bir muafiyet olarak okunmamalıdır.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) sınavı ve eğitimi için adayın daha önce aldığı eğitimlerin ne ölçüde sayılacağı, nihai düzenlemede açıkça tanımlanmadıkça varsayılamaz.`},{tip:`h2`,id:`4-isg-risk-degerlendirmesi-ygu-kontrolunun-yerine-gecer-mi`,metin:`4. İSG risk değerlendirmesi YGU kontrolünün yerine geçer mi?`},{tip:`p`,metin:`İşyerinde yangın riski, iş sağlığı ve güvenliği risk değerlendirmesi içerisinde ele alınabilir. Buna karşılık yangın güvenliği periyodik kontrolü, kullanıma yönelik belgeye sahip yapının onaylı projeleri, yapı ve tesisat özellikleri ile mevcut saha koşullarına yönelik ayrı bir kontrol sistemidir.`},{tip:`p`,metin:`Örneğin acil çıkışın malzeme ile engellenmesi hem İSG risk değerlendirmesinde hem yapı yangın güvenliği incelemesinde gündeme gelebilir. Ancak raporların dayandığı mevzuat, işleme ilişkin görevli kişiler ve amaçları farklıdır. Bir belgenin varlığı, diğer zorunluluğun kendiliğinden yerine geldiğini göstermez.`},{tip:`h2`,id:`5-ygu-egitimi-isg-uzmanina-ne-kazandirabilir`,metin:`5. YGU eğitimi İSG uzmanına ne kazandırabilir?`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitimi; mimari proje okuma, BYKHY sistematiği, kaçış ve yangın bölmesi düzeni, yangın algılama/söndürme sistemleri ve teknik raporlama konularında daha bütüncül bir değerlendirme zemini sunabilir.`},{tip:`p`,metin:`İş güvenliği uzmanının saha gözlemi ve acil durum deneyimi bu öğrenmeyi destekleyebilir. Bununla birlikte YGU eğitimindeki proje ve kontrol becerileri, bütün özel elektrik/mekanik proje hesaplarının ya da test yetkilerinin aynı kişiye geçtiği anlamına gelmez.`},{tip:`h2`,id:`6-sahada-iki-gorev-nasil-ayrilir`,metin:`6. Sahada iki görev nasıl ayrılır?`},{tip:`p`,metin:`Bir fabrikada yeni üretim hattı kurulduğunda iş güvenliği uzmanı çalışanların maruziyetini, makine yerleşimini, acil durum koşullarını ve risk değerlendirmesini gözden geçirebilir. Yangın Güvenlik Uzmanı (YGU) ise mevzuatla görevlendirildiği ölçüde onaylı yapı projelerini, kullanım sınıfını, kaçış düzenini ve yangından korunma sistemlerini kontrol eder.`},{tip:`p`,metin:`Bu iki teknik yaklaşım birbirini besleyebilir; ancak aynı kontrol raporu değildir. YGU, hangi projeyi esas aldığını, sahada ne gördüğünü, belgeyle neyi doğruladığını ve hangi hükme göre karar verdiğini açıkça göstermelidir.`},{tip:`h2`,id:`sik-sorulan-sorular`,metin:`Sık sorulan sorular`},{tip:`h3`,metin:`A sınıfı İSG belgesi YGU-3 hakkı verir mi?`},{tip:`p`,metin:`Hayır. Taslakta YGU-3 için YGU-2 yetkisi ve belirli rapor geçmişi öngörülür; dar özel muafiyetler ayrıca düzenlenmiştir.`},{tip:`h3`,metin:`İSG belgesi olmadan YGU olunur mu?`},{tip:`p`,metin:`Taslakta her YGU adayı için iş güvenliği uzmanlığı belgesi genel şart olarak yazılmamıştır.`},{tip:`h3`,metin:`Kimya mühendisi olan iş güvenliği uzmanı hangi seviyeye yönelir?`},{tip:`p`,metin:`Taslak Madde 5'te kimya mühendisliği YGU-K grubunda sayılır.`},{tip:`h3`,metin:`İSG uzmanlığı ve YGU aynı işyerinde sürdürülebilir mi?`},{tip:`p`,metin:`İki ayrı yetkinin bulunması mümkündür; ancak her bir görevin bağımsızlık, çıkar çatışması ve yetki koşulları ayrıca değerlendirilmelidir.`},{tip:`h2`,id:`sonuc`,metin:`Sonuç`},{tip:`p`,metin:`İş güvenliği uzmanlarının Yangın Güvenlik Uzmanı (YGU) olabilmesi otomatik bir unvan dönüşümü değildir. Belirleyici konular uygun temel öğrenim, ilgili YGU seviyesi, taslakta tarif edilen eğitim/sınav süreci ve nihai resmî yetkilendirmedir.`}],kaynakBaslik:`Kaynakça`,kaynaklar:[{metin:`6331 Sayılı İş Sağlığı ve Güvenliği Kanunu`},{metin:`İş Güvenliği Uzmanlarının Görev, Yetki, Sorumluluk ve Eğitimleri Hakkında Yönetmelik`},{metin:`3194 Sayılı İmar Kanunu`},{metin:`Binaların Yangından Korunması Hakkında Yönetmelik`},{metin:`Yangın Güvenlik Uzmanlığı ve Periyodik Kontrol Usul ve Esasları Hakkında Yönetmelik Taslağı`}],sss:[{soru:`A sınıfı İSG belgesi YGU-3 hakkı verir mi?`,yanit:`Hayır. Taslakta YGU-3 için YGU-2 yetkisi ve belirli rapor geçmişi öngörülür; dar özel muafiyetler ayrıca düzenlenmiştir.`},{soru:`İSG belgesi olmadan YGU olunur mu?`,yanit:`Taslakta her YGU adayı için iş güvenliği uzmanlığı belgesi genel şart olarak yazılmamıştır.`},{soru:`Kimya mühendisi olan iş güvenliği uzmanı hangi seviyeye yönelir?`,yanit:`Taslak Madde 5'te kimya mühendisliği YGU-K grubunda sayılır.`},{soru:`İSG uzmanlığı ve YGU aynı işyerinde sürdürülebilir mi?`,yanit:`İki ayrı yetkinin bulunması mümkündür; ancak her bir görevin bağımsızlık, çıkar çatışması ve yetki koşulları ayrıca değerlendirilmelidir.`}]},{no:`08`,baslik:`YGU-1, YGU-2, YGU-3 ve YGU-K: Yangın Güvenlik Uzmanlığı (YGU) Eğitim Seviyeleri ve Aralarındaki Farklar`,ozet:`Yangın Güvenlik Uzmanlığı (YGU) eğitim seviyeleri, yalnızca ders saatlerini değil; mesleki kabul koşullarını, uzmanlık derinliğini ve görevlendirme alanını birbirinden ayırır. Yangın Güvenlik Uzmanı (YGU) olmayı planlayan kişinin kendi seviyesini belirlemesi için üç farklı kaynağı birlikte okuması gerekir: Taslak Madde 5 meslek ve geçiş şartlarını, Madde 6 görev türlerini, EK-1 yapı ve kontrol kapsamını, EK-2 ise eğitim modüllerini gösterir.`,bloklar:[{tip:`not`,etiket:`MEVZUAT DURUMU – TASLAK`,metin:`Aşağıdaki bütün seviye, saat, yapı sınırı ve periyot bilgileri yönetmelik taslağındaki düzenlemelerdir. Bunlar yürürlüğe girmiş kesin yetki olarak kullanılmamalıdır.`},{tip:`h2`,id:`1-ygu-1-hangi-ogrenim-grubu-icin-ongoruluyor`,metin:`1. YGU-1 hangi öğrenim grubu için öngörülüyor?`},{tip:`p`,metin:`YGU-1, taslak Madde 5'te sayılan makine, inşaat, elektrik ve elektrik-elektronik teknikerleri ile itfaiyecilik alanındaki iki yıllık ön lisans mezunları için öngörülmektedir. Taslak Madde 6/2-b, uygun kullanım sınıfı ve sınırlar dahilinde YGU-1'in periyodik kontrol görevlerinde yer alabileceğini belirtir; proje uygunluğu, yapı kullanma izni ve belirli tatbikat planlama görevleri ise YGU-2 veya YGU-3'e ayrılmıştır.`},{tip:`p`,metin:`Örneğin küçük bir büro yapısının EK-1'de YGU-1'e açık olması, her büro binasının veya bütün yapıların YGU-1 tarafından kontrol edilebileceği anlamına gelmez.`},{tip:`h2`,id:`2-ygu-2-neyi-farkli-yapar`,metin:`2. YGU-2 neyi farklı yapar?`},{tip:`p`,metin:`YGU-2 başlangıç grubu, taslakta sayılan mimarlar ile inşaat, makine, elektrik, elektronik ve elektrik-elektronik mühendislerinden oluşur. Bu seviyede daha geniş kullanım sınıfı/sınır kombinasyonları öngörülür. Ayrıca Madde 6'da proje uygunluğu görüşüne esas raporlama, yapı kullanma izni aşamasındaki inceleme ve belirli tatbikatların birlikte planlanması YGU-2/YGU-3 görevleri arasında belirtilmiştir.`},{tip:`p`,metin:`Buradaki “uygunluk görüşüne esas rapor” ifadesi önemlidir: YGU-2 belgesi, bütün projelerin müellifliği veya bütün teknik projelerin resmî onayı anlamına gelmez.`},{tip:`h2`,id:`3-ygu-3-icin-neden-onceki-uygulama-deneyimi-isteniyor`,metin:`3. YGU-3 için neden önceki uygulama deneyimi isteniyor?`},{tip:`p`,metin:`YGU-3, taslakta doğrudan genel başlangıç seviyesi değildir. Madde 5/2-c uyarınca önce YGU-2 yetki belgesine sahip olunması; son bir yıl içinde en az iki farklı kullanım sınıfından dört yapı için yangın güvenlik raporu düzenlenmesi öngörülmüştür. Bazı Bakanlık personeline ilişkin özel muafiyet Madde 14'te ayrıca ele alınmıştır.`},{tip:`p`,metin:`EK-1 yüksek tehlikeli endüstriyel ve bazı depolama yapılarında YGU-3'ü öne çıkarmaktadır. YGU-3'ün teknik kapsama ilişkin eğitim içeriği ise EK-2'de yüksek tehlikeli yapılar ve uluslararası doküman/standart okuma modüllerinde yoğunlaşır.`},{tip:`h2`,id:`4-ygu-k-diger-seviyelerin-ustu-mudur`,metin:`4. YGU-K diğer seviyelerin üstü müdür?`},{tip:`p`,metin:`Hayır. YGU-K, kimya mühendisleri ve kimya lisans mezunlarına ilişkin özel gruptur. Taslak Madde 6/2-b, yüksek tehlikeli yapıların periyodik kontrolünde tehlikeli maddelerin tespiti ve sınıflandırılmasındaki görevini tanımlar. YGU-K'yi “bütün kontrollerde YGU-3'ten üstün” bir unvan veya tasarım onay yetkisi olarak tanımlamak doğru değildir.`},{tip:`h2`,id:`5-ek-2-de-tasarlanan-teorik-egitim-sureleri`,metin:`5. EK-2'de tasarlanan teorik eğitim süreleri`},{tip:`tablo`,basliklar:[`Seviye`,`Taslak teorik eğitim toplamı`,`Özellik`],satirlar:[[`YGU-1`,`65 saat`,`Temel yapı ve sistem bilgisi, periyodik kontrol, tahliye`],[`YGU-2`,`85 saat`,`Daha ayrıntılı yapı, elektrik ve mekanik sistemler, proje ve uygulama incelemesi`],[`YGU-3`,`40 saat ek`,`Yüksek tehlikeli yapılar ve uluslararası teknik dokümanlar`],[`YGU-K`,`35 saat`,`Temel yangın/mevzuat, yüksek tehlikeli maddeler, kontrol ve raporlama`]]},{tip:`p`,metin:`Bu toplamlar EK-2'de ilgili seviye için işaretlenen modüllerin saatleri toplanarak doğrulanmıştır. Taslak Madde 9'a göre teorik eğitim dışında, farklı kullanım sınıfındaki iki yapıyla ilişkili uygulama eğitimi de öngörülür. Dolayısıyla tabloda yer alan saatler resmî eğitimin bütün süreç yükünü tek başına göstermemektedir.`},{tip:`h2`,id:`6-ek-1-e-gore-yapi-ve-gorev-sinirlari-nasil-okunmali`,metin:`6. EK-1'e göre yapı ve görev sınırları nasıl okunmalı?`},{tip:`p`,metin:`EK-1'de aynı kullanım sınıfında farklı bina özelliklerine göre kontrol periyodu ve uzmanlık seviyesi değişebilir. Örnekler:`},{tip:`tablo`,basliklar:[`Yapı durumu (TASLAK)`,`Kontrol aralığı`,`EK-1'deki YGU seviyesi`],satirlar:[[`Büro, yapı inşaat alanı 1.000 m² ve altı`,`5 yıl`,`YGU-1 veya YGU-2 veya YGU-3`],[`Büro, yapı inşaat alanı 1.000 m² üstü`,`4 yıl`,`YGU-2 veya YGU-3`],[`Konaklama, yatılan oda sayısı 25 ve altında`,`5 yıl`,`YGU-1 veya YGU-2 veya YGU-3`],[`Konaklama, yatılan oda sayısı 25'in üstünde`,`4 yıl`,`YGU-2 veya YGU-3`],[`Yüksek tehlikeli endüstriyel tesis`,`3 yıl`,`YGU-3 ve YGU-K`]]},{tip:`p`,metin:`EK-1 tablosunun satırı belirlenmeden yalnızca “bina küçük”, “tesis sanayi içinde” veya “burası otel” denilerek kesin yetki kararı verilmemelidir. Karma kullanımlı yapılara ilişkin tablo notları da dikkate alınmalıdır.`},{tip:`h2`,id:`7-saha-ornegi-ayni-isletmede-farkli-bina-kullanimlari`,metin:`7. Saha örneği: aynı işletmede farklı bina kullanımları`},{tip:`p`,metin:`Bir sanayi parselinde üretim binası, idari büro ve tehlikeli madde deposu bulunabilir. Yangın Güvenlik Uzmanı (YGU) görevine ilişkin uygunluk değerlendirmesinde önce bu bölümlerin gerçekten nasıl kullanıldığı, ruhsat/proje kayıtları ve hangi yapısal sınıra girdiği belirlenir. Üretim alanına verilen YGU yetki kararı, komşu idari bloğa otomatik uygulanamaz; depolamanın tehlike düzeyi de ayrı incelenir.`},{tip:`p`,metin:`Sahada doğru yöntem, hangi yapı, hangi kullanım sınıfı, hangi teknik sınır, hangi işlem, hangi uzmanlık seviyesi sorularını sırayla cevaplamaktır. Onaylı proje, gerçek saha ve teknik belgeler bu değerlendirmenin dayanaklarıdır.`},{tip:`h2`,id:`8-sik-sorulan-sorular`,metin:`8. Sık sorulan sorular`},{tip:`h3`,metin:`YGU-1 belgesi olan herkes 1.000 m²'ye kadar bütün yapılara bakabilir mi?`},{tip:`p`,metin:`Hayır; kullanım sınıfı ve EK-1'in ilgili satırı ayrıca belirlenmelidir.`},{tip:`h3`,metin:`YGU-2 doğrudan YGU-3 sayılır mı?`},{tip:`p`,metin:`Hayır. Taslakta genel geçiş için YGU-2 belgesiyle birlikte raporlama deneyimi öngörülür.`},{tip:`h3`,metin:`YGU-K bağımsız olarak her yüksek tehlikeli tesisi kontrol eder mi?`},{tip:`p`,metin:`Taslakta tehlikeli maddelerin tespiti ve sınıflandırılmasına yönelik özel görev tanımlanmıştır; genel kontrol göreviyle eşit değildir.`},{tip:`h3`,metin:`Eğitim saatleri yürürlüğe girdi mi?`},{tip:`p`,metin:`Hayır; tabloda yalnız incelenen taslaktaki EK-2 değerleri gösterilmektedir.`},{tip:`h2`,id:`sonuc`,metin:`Sonuç`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) seviyelerini yalnızca diploma veya ders saatiyle açıklamak eksik kalır. Yetki değerlendirmesinde Madde 5, Madde 6, EK-1 ve EK-2 birlikte okunmalı; taslak kaynak içindeki YGU-4 yazım sorunu da gizlenmemelidir.`}],kaynakBaslik:`Kaynakça`,kaynaklar:[{metin:`3194 Sayılı İmar Kanunu`},{metin:`Binaların Yangından Korunması Hakkında Yönetmelik`},{metin:`Yangın Güvenlik Uzmanlığı ve Periyodik Kontrol Usul ve Esasları Hakkında Yönetmelik Taslağı`}],sss:[{soru:`YGU-1 belgesi olan herkes 1.000 m²'ye kadar bütün yapılara bakabilir mi?`,yanit:`Hayır; kullanım sınıfı ve EK-1'in ilgili satırı ayrıca belirlenmelidir.`},{soru:`YGU-2 doğrudan YGU-3 sayılır mı?`,yanit:`Hayır. Taslakta genel geçiş için YGU-2 belgesiyle birlikte raporlama deneyimi öngörülür.`},{soru:`YGU-K bağımsız olarak her yüksek tehlikeli tesisi kontrol eder mi?`,yanit:`Taslakta tehlikeli maddelerin tespiti ve sınıflandırılmasına yönelik özel görev tanımlanmıştır; genel kontrol göreviyle eşit değildir.`},{soru:`Eğitim saatleri yürürlüğe girdi mi?`,yanit:`Hayır; tabloda yalnız incelenen taslaktaki EK-2 değerleri gösterilmektedir.`}]},{no:`09`,baslik:`Yangın Güvenlik Uzmanlığı (YGU) Eğitimi Veren Üniversiteler Nasıl Belirlenir? Yetkili Üniversiteler ve Eğitim Programları`,ozet:`Yangın Güvenlik Uzmanlığı (YGU) eğitimi veren üniversiteleri araştırırken en önemli konu, üniversitenin tanınmışlığı değil, ilgili uzmanlık programını düzenlemek için resmî olarak yetkilendirilmiş olmasıdır. Bir üniversitenin yangın güvenliği, acil durum veya BYKHY konusunda sertifika programı açabilmesi, o programın doğrudan resmî Yangın Güvenlik Uzmanlığı (YGU) eğitimi olduğu anlamına gelmez.`,bloklar:[{tip:`not`,etiket:`MEVZUAT DURUMU – TASLAK`,metin:`Aşağıdaki kurum türleri, yetkilendirme şartları ve eğitim yöntemi, YGU yönetmelik taslağının 9 ve 15. maddelerine dayanmaktadır. Yetkilendirilmiş üniversitelerin kesin listesi ve fiilen açılmış programlar yalnızca resmî duyurulardan doğrulanmalıdır.`},{tip:`h2`,id:`1-ygu-egitimi-veren-universite-nasil-yetkilendirilebilir`,metin:`1. YGU eğitimi veren üniversite nasıl yetkilendirilebilir?`},{tip:`p`,metin:`TASLAK Madde 15/1, üniversitelerin Bakanlıkça eğitici kuruluş olarak yetkilendirilebilmesini öngörür. Bununla birlikte taslak yalnız üniversiteleri saymaz: kamu kurumu niteliğindeki meslek kuruluşları ile bunların ticari iştirakleri de belirli protokol ve koşullarla yetkilendirilebilecek kurum türleri arasındadır.`},{tip:`p`,metin:`Bu hüküm, ülkenin bütün üniversitelerinin otomatik olarak resmî eğitim verebildiği anlamına gelmez. Eğitim programını, eğiticilerin yeterliliklerini, eğitim ortamını ve uygulama eğitimi için itfaiye ile işbirliği bilgilerini içeren başvuru süreci öngörülmüştür.`},{tip:`h2`,id:`2-universite-sertifikasi-ile-ygu-yetki-belgesi-neden-ayni-degildir`,metin:`2. Üniversite sertifikası ile YGU yetki belgesi neden aynı değildir?`},{tip:`p`,metin:`Üniversitelerin sürekli eğitim merkezleri genel yangın güvenliği, yangın risk analizi veya söndürme sistemleri konularında yararlı sertifika programları düzenleyebilir. Ancak bu faaliyetlerin yetki kapsamı, resmî YGU uzmanlık eğitiminin kapsamından farklı olabilir.`},{tip:`p`,metin:`Taslak Madde 9'a göre eğitim teorik ve uygulamalı iki aşamadan oluşur; Madde 11 sınavı; Madde 13 yetki belgesini ayrı düzenler. Böylece bir kurumdan katılım belgesi almak, Bakanlıkça elektronik doğrulanabilir resmî Yangın Güvenlik Uzmanı (YGU) yetkisi kazanmakla eş tutulamaz.`},{tip:`h2`,id:`3-bir-universitenin-ygu-egitim-ilaninda-hangi-bilgiler-bulunmali`,metin:`3. Bir üniversitenin YGU eğitim ilanında hangi bilgiler bulunmalı?`},{tip:`p`,metin:`Yetkiyi değerlendirmek için ilan edilen uzmanlık seviyesi, eğitim müfredatı, teorik/uygulamalı ders yöntemi, başvuru takvimi, kurumun yetkilendirme durumu ve eğitim sonrasındaki sınav süreci birlikte okunmalıdır.`},{tip:`p`,metin:`TASLAK EK-2 seviyelere göre farklı teorik saatler öngörür: YGU-1 65, YGU-2 85, YGU-3 40 ek ve YGU-K 35 saat. Bu süreler bir üniversitenin belirli takvimde kurs açtığını göstermez. Taslak Madde 9'da teorik eğitime en az %90 devam ve mahalli itfaiye teşkilatınca verilen uygulama eğitimi de ayrıca yer alır.`},{tip:`h2`,id:`4-hangi-universiteler-resmi-ygu-egitimi-veriyor`,metin:`4. Hangi üniversiteler resmî YGU eğitimi veriyor?`},{tip:`p`,metin:`Bu çalışmada 5 Kasım 2026 itibarıyla doğrulanmış, yetkilendirilmiş üniversitelerin eksiksiz resmî listesi elde edilmedi. Bu nedenle herhangi bir üniversitenin ismini kesin yetkili kurum olarak yayımlamıyoruz. Kamuya açık bir kurumun eğitim duyurusu ile Bakanlığın eğitim yetkilendirme kaydı aynı kanıt değildir.`},{tip:`p`,metin:`YGU Rehberi'ndeki bilgi sayfası güncellendiğinde üniversite adı, hangi YGU seviyesinde eğitim verdiği, yetki dayanağı ve duyuru tarihi birlikte gösterilmelidir. Belirli bir eğitim tarihi veya kontenjan doğrulanmamışsa boş alanı tahmini bilgiyle doldurmak uygun değildir.`},{tip:`h2`,id:`5-egitim-kalitesi-ve-saha-uygulamasi-nasil-degerlendirilebilir`,metin:`5. Eğitim kalitesi ve saha uygulaması nasıl değerlendirilebilir?`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU) eğitiminde yalnızca yönetmelik metninin okunması değil, proje–saha–rapor bağlantısının anlaşılması da önemlidir. Örnek kat planlarında kaçış yollarının incelenmesi, teknik belgelerin karşılaştırılması ve yangın güvenlik raporlarında gerekçeli bulgu oluşturma gibi çalışmalardan yararlanılabilir.`},{tip:`p`,metin:`TASLAK Madde 9/5, farklı kullanım sınıfından iki yapı üzerinde uygulama eğitimi öngörür. Bu, sadece sınıf içi anlatımdan farklı bir aşamadır. Ancak resmî uygulamanın nerede, hangi tarihte ve hangi itfaiye teşkilatıyla yürütüleceği, program duyurusu görülmeden varsayılamaz.`},{tip:`h2`,id:`6-saha-ornegi-universitede-ogrenilen-bilginin-kullanilmasi`,metin:`6. Saha örneği: Üniversitede öğrenilen bilginin kullanılması`},{tip:`p`,metin:`Bir Yangın Güvenlik Uzmanı (YGU) adayı, okul binasının onaylı mimari projesiyle gerçek kaçış düzeni arasında farklılık görsün. Projedeki kaçış kapısının yerini ve görevini belirlemeden sadece sahadaki kapının fotoğrafına bakarak uygunluk kararı verilmesi yeterli değildir. Yapı kullanımı, izin geçmişi, kaçış düzeni ve ilgili mevzuat birlikte okunmalıdır.`},{tip:`p`,metin:`Bu örnek, üniversitenin veya diğer eğitici kuruluşun teorik bilgisinin uygulama gözetimiyle ilişkilendirilmesi gerektiğini gösterir. Ancak projeye ilişkin özel tasarım/ölçüm/test faaliyetleri YGU eğitiminin otomatik yetki konusu değildir.`},{tip:`h2`,id:`sik-sorulan-sorular`,metin:`Sık sorulan sorular`},{tip:`h3`,metin:`Her üniversite YGU eğitimi verebilir mi?`},{tip:`p`,metin:`Hayır. Taslakta Bakanlıkça yetkilendirme süreci öngörülür.`},{tip:`h3`,metin:`Sürekli eğitim merkezi sertifikası YGU belgesi midir?`},{tip:`p`,metin:`Doğrudan değildir. Eğitim katılımı, sınav ve resmî yetkilendirme farklı işlemlerdir.`},{tip:`h3`,metin:`Yetkili üniversite listesi nereden doğrulanır?`},{tip:`p`,metin:`Bakanlığın veya ilgili yetkilendirilmiş kurumların resmî ilanlarından.`},{tip:`h2`,id:`sonuc`,metin:`Sonuç`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitimi veren üniversiteler için en güvenilir ölçüt resmî yetkilendirmedir. Bir üniversite adı, programın YGU seviyesini ve yetki durumunu doğrulamadan tanıtım listesine eklenmemelidir.`}],kaynakBaslik:`Kaynakça`,kaynaklar:[{metin:`3194 Sayılı İmar Kanunu`},{metin:`Binaların Yangından Korunması Hakkında Yönetmelik`},{metin:`Yangın Güvenlik Uzmanlığı ve Periyodik Kontrol Usul ve Esasları Hakkında Yönetmelik Taslağı`}],sss:[{soru:`Her üniversite YGU eğitimi verebilir mi?`,yanit:`Hayır. Taslakta Bakanlıkça yetkilendirme süreci öngörülür.`},{soru:`Sürekli eğitim merkezi sertifikası YGU belgesi midir?`,yanit:`Doğrudan değildir. Eğitim katılımı, sınav ve resmî yetkilendirme farklı işlemlerdir.`},{soru:`Yetkili üniversite listesi nereden doğrulanır?`,yanit:`Bakanlığın veya ilgili yetkilendirilmiş kurumların resmî ilanlarından.`}]},{no:`10`,baslik:`Yangın Güvenlik Uzmanlığı (YGU) Eğitimi Veren Yerler: Yetkili Eğitim Kurumu Nasıl Anlaşılır?`,ozet:`“Yangın Güvenlik Uzmanlığı (YGU) eğitimi veren yerler” araması yapan kişi çoğu zaman yakınındaki bir kursu veya hangi şehirde eğitim bulunduğunu öğrenmek ister. Ancak resmî yangın güvenlik uzmanı yetkilendirmesinde eğitimin nerede düzenlendiği kadar, hangi kuruluşun hangi YGU seviyesi için yetkilendirildiği önemlidir. Bu makale, üniversite listelerinden farklı olarak eğitim kurumu, şehir, teorik/uygulamalı eğitim ve kurs duyurusu ayrımına odaklanmaktadır.`,bloklar:[{tip:`not`,etiket:`MEVZUAT DURUMU – TASLAK`,metin:`Eğitim kurumlarının yetkilendirilmesi ve ders yöntemleri yönetmelik taslağının 9 ve 15. maddelerinden aktarılmaktadır. Kesin eğitim yeri ve takvimi için resmî ilan gereklidir.`},{tip:`h2`,id:`1-yetkili-ygu-egitim-kurumu-hangi-tur-kurulus-olabilir`,metin:`1. Yetkili YGU eğitim kurumu hangi tür kuruluş olabilir?`},{tip:`p`,metin:`TASLAK Madde 15, üniversitelerin yanında kamu kurumu niteliğindeki meslek kuruluşları ve bunların ticari iştirakleri için de yetkilendirme yolu öngörmektedir. Bu hüküm, herhangi bir özel kursun kendiliğinden resmî Yangın Güvenlik Uzmanlığı (YGU) eğitimi vereceği anlamına gelmez.`},{tip:`p`,metin:`Kuruluşun programı, eğiticileri, fiziki/teknik altyapısı ve uygulama eğitimi için işbirliği protokolü, yetkilendirme değerlendirmesinin parçaları arasında sayılmıştır. Yetkili eğitici kuruluşların listesinin Bakanlık tarafından ilan edilmesi de taslakta öngörülmektedir.`},{tip:`h2`,id:`2-ygu-egitimi-online-mi-yuz-yuze-mi-duzenlenebilir`,metin:`2. YGU eğitimi online mı yüz yüze mi düzenlenebilir?`},{tip:`p`,metin:`TASLAK Madde 9/2, teorik eğitimin yüz yüze veya uzaktan yapılabilmesini öngörür. Bu ifade, uygulama eğitiminin de otomatik olarak yalnızca uzaktan tamamlanabileceği anlamına gelmez. Aynı maddenin ilk fıkrasında uygulama eğitimini mahalli itfaiye teşkilatı yürütür; beşinci fıkrada ise farklı kullanım sınıfındaki iki yapıya ilişkin rapor ve uygulama gözetimi vardır.`},{tip:`p`,metin:`Bu nedenle “tamamen internetten YGU belgesi” gibi bir vaat, resmî eğitim ve sınav aşamalarından bağımsız olarak kabul edilmemelidir.`},{tip:`h2`,id:`3-hangi-sehirlerde-ygu-egitimi-acilabilir`,metin:`3. Hangi şehirlerde YGU eğitimi açılabilir?`},{tip:`p`,metin:`İstanbul, Ankara, Bursa, İzmir veya başka bir şehirde genel yangın güvenliği kursunun bulunması, o şehirde resmî YGU eğitiminin fiilen açıldığı anlamına gelmez. Şehir, kampüs, derslik ve uygulama yapılacak yapıların konumu ancak yetkili kuruluşun program ilanıyla doğrulanmalıdır.`},{tip:`p`,metin:`Eğitim yerini değerlendirirken teorik derslerin uzaktan verilip verilmeyeceği, uygulama eğitimi için hangi mahalli itfaiye teşkilatıyla protokol kurulduğu ve sınavın başka bir yerde uygulanıp uygulanmayacağı ayrı sorulardır.`},{tip:`h2`,id:`4-bir-kurs-ilani-nasil-degerlendirilmelidir`,metin:`4. Bir kurs ilanı nasıl değerlendirilmelidir?`},{tip:`p`,metin:`İlanın dayandığı yetkilendirme, YGU-1/2/3/K seviyelerinden hangisine yönelik olduğu, taslak EK-2 ile program ilişkisi, başvuru koşulları, toplam bedel kalemleri ve resmî sınav aşaması açık olmalıdır. Tanıtımda “sertifikalı”, “üniversite onaylı” veya “yangın uzmanlığı” ifadesi bulunması tek başına resmî YGU yetkisini ispatlamaz.`},{tip:`p`,metin:`TASLAK Madde 9/3, teorik eğitime en az %90 devam şartı içerir. Bu oran ve eğitim yöntemi yalnızca taslak düzenlemedir; kurumun fiilen açtığı bir programın kesin katılım koşulu şeklinde ilanla doğrulanmadan kullanılmamalıdır.`},{tip:`h2`,id:`5-egitim-yerinin-teknik-donanimi-onemli-mi`,metin:`5. Eğitim yerinin teknik donanımı önemli mi?`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitiminde proje okuma, kaçış düzeni, sistem dokümanları ve raporlama becerileri birbirini tamamlar. Nitelikli bir eğitim ortamında örnek projeler, kontrol kayıtları ve teknik sistemlerin işlevleri anlaşılabilir biçimde ele alınmalıdır.`},{tip:`p`,metin:`Saha uygulamasında kişi, projede öngörülen yangın kapısı, algılama sistemi ve kaçış yolunu gerçek kullanım koşullarıyla karşılaştırmayı öğrenir. Bunun için bütün özel mühendislik testlerinin eğitim alanlar tarafından yapılması veya hazırlanan dokümanların dış uzmanlara imzalatılması gerektiği gibi yeni zorunluluklar çıkarılmamalıdır.`},{tip:`h2`,id:`6-saha-ornegi-iki-farkli-kullanim-sinifi`,metin:`6. Saha örneği: iki farklı kullanım sınıfı`},{tip:`p`,metin:`Uygulamalı eğitimde bir büro yapısı ile bir konaklama yapısının incelendiğini düşünelim. Yangın Güvenlik Uzmanı (YGU) adayı, iki yapının farklı kullanıcı profillerini, kaçış düzenlerini, projelerini ve ilgili yangın güvenliği gerekliliklerini karşılaştırır. Farklı kullanım sınıflarında aynı kontrol sorusunun neden farklı teknik sonuçlar doğurabileceğini görür.`},{tip:`p`,metin:`Bu örnek, taslak Madde 9/5'teki farklı kullanım sınıflı iki yapı yaklaşımının mesleki amacını açıklar; belirli bir üniversitenin veya itfaiyenin bu programa kesin olarak katıldığı iddiasını içermez.`},{tip:`h2`,id:`sik-sorulan-sorular`,metin:`Sık sorulan sorular`},{tip:`h3`,metin:`Şehir dışına gitmek zorunlu mu?`},{tip:`p`,metin:`Kesin programlar ilan edilmeden genel bir zorunluluk söylenemez.`},{tip:`h3`,metin:`Uzaktan eğitimle resmî YGU olunur mu?`},{tip:`p`,metin:`Taslak teorik eğitime uzaktan yöntem tanır; uygulama, sınav ve yetkilendirme ayrıca düzenlenir.`},{tip:`h3`,metin:`Özel kurs sertifikası yeterli mi?`},{tip:`p`,metin:`Resmî yetkilendirme olmadan yeterli kabul edilemez.`},{tip:`h2`,id:`sonuc`,metin:`Sonuç`},{tip:`p`,metin:`YGU eğitimi veren yerler araştırılırken önce kuruluşun resmî statüsü, ardından eğitim seviyesi, teorik ders yöntemi, uygulama yeri ve sınav usulü değerlendirilmelidir. Şehir listesi veya tanıtım afişi, yetkilendirme kararı yerine geçmez.`}],kaynakBaslik:`Kaynakça`,kaynaklar:[{metin:`3194 Sayılı İmar Kanunu`},{metin:`Yangın Güvenlik Uzmanlığı ve Periyodik Kontrol Usul ve Esasları Hakkında Yönetmelik Taslağı`}],sss:[{soru:`Şehir dışına gitmek zorunlu mu?`,yanit:`Kesin programlar ilan edilmeden genel bir zorunluluk söylenemez.`},{soru:`Uzaktan eğitimle resmî YGU olunur mu?`,yanit:`Taslak teorik eğitime uzaktan yöntem tanır; uygulama, sınav ve yetkilendirme ayrıca düzenlenir.`},{soru:`Özel kurs sertifikası yeterli mi?`,yanit:`Resmî yetkilendirme olmadan yeterli kabul edilemez.`}]},{no:`11`,baslik:`Yangın Güvenlik Uzmanlığı (YGU) Eğitim Başvurusu Nasıl Yapılır? Gerekli Belgeler ve Başvuru Şartları`,ozet:`Yangın Güvenlik Uzmanlığı (YGU) eğitim başvurusunun doğru yapılabilmesi için kişinin önce başvuracağı uzmanlık seviyesini ve o seviyeye ilişkin öğrenim koşullarını belirlemesi gerekir. Başvuru dosyasının hazırlanması, teorik eğitimin alınması, uygulama eğitimi, sınav ve yetki belgesinin düzenlenmesi birbirinden farklı işlemlerdir. Bu aşamalardan birinin tamamlanması, diğerlerinin kendiliğinden gerçekleştiği anlamına gelmez.`,bloklar:[{tip:`not`,etiket:`MEVZUAT DURUMU – TASLAK`,metin:`Aşağıdaki başvuru usulleri, incelenen YGU yönetmelik taslağının 5, 9, 10, 11 ve 13. maddelerine dayanmaktadır. Kurum, takvim ve belge biçimleri bakımından kesin işlem bilgisi için yürürlüğe girmiş metin ve resmî ilan gereklidir.`},{tip:`h2`,id:`1-basvuruya-baslanmadan-once-uzmanlik-seviyesi-belirlenir`,metin:`1. Başvuruya başlanmadan önce uzmanlık seviyesi belirlenir`},{tip:`p`,metin:`TASLAK Madde 5, YGU-1 için belirtilen teknik ön lisans ve itfaiyecilik mezunlarını; YGU-2 için belirtilen mühendislik dalları ile mimarları; YGU-K için kimya mühendisleri ve kimya lisans mezunlarını saymaktadır. YGU-3 için ise YGU-2 yetkisi yanında belirli raporlama deneyimi öngörülmüştür. Bu nedenle “önce eğitim kurumuna kayıt olayım, sonra seviyeyi seçerim” yaklaşımı resmî kabul koşullarını gözden kaçırabilir.`},{tip:`p`,metin:`Adayın diplomasındaki alan, uzmanlık seviyesinin başlıca dayanağıdır. İş güvenliği uzmanlığı sınıfı veya işyerindeki görev unvanı bu diploma alanının yerine geçmez.`},{tip:`h2`,id:`2-ygu-egitim-basvurusu-hangi-kurumdan-takip-edilir`,metin:`2. YGU eğitim başvurusu hangi kurumdan takip edilir?`},{tip:`p`,metin:`TASLAK Madde 10/1, teorik eğitim başvuru ilanının Bakanlığın veya Bakanlığın yetkilendirdiği kuruluşun resmî internet sayfasında yayımlanmasını öngörmektedir. Madde 15 ise üniversitelerin ve kamu kurumu niteliğindeki meslek kuruluşları ile bunların ticari iştiraklerinin belirli koşullarla eğitici kuruluş olarak yetkilendirilebileceğini düzenler.`},{tip:`p`,metin:`Bu nedenle bir kursun reklamında “yangın sertifikası” yazması, resmî YGU eğitim başvurusu açıldığı anlamına gelmez. Eğitimin seviyesi, yetkilendirme kapsamı, başvuru adresi ve kesin takvim aynı resmî duyuruda doğrulanmalıdır.`},{tip:`h2`,id:`3-ygu-egitim-basvurusunda-istenen-belgeler`,metin:`3. YGU eğitim başvurusunda istenen belgeler`},{tip:`p`,metin:`TASLAK Madde 10/2 aşağıdaki belgeleri öngörmektedir:`},{tip:`liste`,numarali:!0,maddeler:[`Türkiye Cumhuriyeti vatandaşları için T.C. kimlik numarası; yabancılar için pasaport veya yabancı kimlik numarası ile çalışma iznini gösterir belge.`,`Bir adet vesikalık fotoğraf.`,`Başvuru tarihinden önceki son üç ay içerisinde alınmış adli sicil belgesi.`,`Diploma, mezuniyet, geçici mezuniyet veya diploma denklik belgesi.`,`Mesleğini icra etmek için meslek kuruluşu üyeliği aranan kişilerde son altı ay içinde alınmış oda faaliyet veya oda kayıt belgesi.`,`YGU-3 başvurularında mesleki tecrübeyi tevsik eden belge.`,`KEP adresini gösterir belge.`,`Taslakta tarif edilen kişisel bilgilerin Bakanlık internet sayfasında yayımlanmasına izin verildiğini gösterir belge.`]},{tip:`p`,metin:`Belgelerin güncellik sınırları bütün kalemlerde aynı değildir: örneğin taslakta adli sicil belgesi üç ay, ilgili oda belgeleri altı ay olarak belirtilmiştir. Kesin başvuru sistemi açıldığında elektronik doğrulama yöntemi ve belge biçimi ayrıca kontrol edilmelidir.`},{tip:`h2`,id:`4-ek-5-neden-egitim-basvurusu-eki-degildir`,metin:`4. EK-5 neden eğitim başvurusu eki değildir?`},{tip:`p`,metin:`Taslağın EK-5'i, yapıların periyodik kontrol başvuru ve taahhütname formlarını içerir. Bu ek, YGU adayının teorik eğitime başvururken sunacağı belgelerin doğrudan listesi değildir. YGU adayının belge listesi için Madde 10, yapı sahibinin periyodik kontrol başvurusu için EK-5 okunmalıdır.`},{tip:`p`,metin:`Bu ayrımı yapmamak, yanlış formun eğitim başvurusunda aranmasına veya yapı kontrol sürecinin aday eğitim süreciyle karıştırılmasına yol açabilir.`},{tip:`h2`,id:`5-teorik-ve-uygulama-egitimi-nasil-ayrilir`,metin:`5. Teorik ve uygulama eğitimi nasıl ayrılır?`},{tip:`p`,metin:`TASLAK Madde 9 teorik eğitimin Bakanlık veya yetkili eğitici kuruluşça, uygulama eğitiminin ise mahalli itfaiye teşkilatınca verilmesini öngörür. Teorik eğitim yüz yüze veya uzaktan yapılabilir. Katılım belgesi için teorik derslerin en az %90'ına devam şartı taslakta yer alır.`},{tip:`p`,metin:`Uygulama eğitimi, farklı kullanım sınıfındaki iki yapı için yangın güvenlik raporu düzenleme ve uygulama gözetimi faaliyetlerini içerir. Bu nedenle uygulama süreci, yalnızca teorik derslerin bitişinden ibaret değildir.`},{tip:`h2`,id:`6-eksik-belgeye-iliskin-15-gunluk-sure-hangi-asamada-duzenleniyor`,metin:`6. Eksik belgeye ilişkin 15 günlük süre hangi aşamada düzenleniyor?`},{tip:`p`,metin:`TASLAK Madde 11/4 belirleyici hükümdür: Madde 10'da sayılan belgelerin Komisyon tarafından inceleneceği, başvuru dilekçesine eklenmesi zorunlu belgenin eksik olması halinde 15 gün süre verileceği, eksiklik giderilmezse belgelerin Bakanlıkça iade edilerek kişinin sınava alınmayacağı yazılıdır.`},{tip:`p`,metin:`Metin, eğitim başvurusu belgelerine gönderme yapmakla birlikte eksikliğin sonucunu sınava katılamama üzerinden kurmaktadır. Bu nedenle 15 günün her kayıt işleminde otomatik uygulanan bir “eğitime kabul süresi” olduğu kesin biçimde söylenmemelidir. Başvuru ilanındaki işlem adımı, komisyon incelemesi ve sınav kabulü birlikte okunmalıdır.`},{tip:`h2`,id:`7-egitim-basvurusu-sinav-ve-yetki-belgesi-arasindaki-sira`,metin:`7. Eğitim başvurusu, sınav ve yetki belgesi arasındaki sıra`},{tip:`p`,metin:`Taslak sistemde adayın uygun mesleki öğrenim koşulunu sağlaması, resmî teorik ve uygulama eğitimini tamamlaması, sınava kabul edilmesi ve başarı sağlaması sonrasında resmî yetkilendirmesi öngörülmektedir. Madde 13, yetki belgesinin Bakanlıkça elektronik ortamda doğrulanabilir biçimde düzenlenmesini tarif eder.`},{tip:`p`,metin:`Dolayısıyla üniversiteden alınan eğitim katılım belgesi, tek başına Yangın Güvenlik Uzmanı (YGU) yetki belgesi değildir. Eğitim tamamlandığında sınava veya yetkilendirmeye ilişkin duyurunun ayrıca izlenmesi gerekir.`},{tip:`h2`,id:`8-saha-ornegi-dogru-belgeyi-dogru-islemde-kullanmak`,metin:`8. Saha örneği: Doğru belgeyi doğru işlemde kullanmak`},{tip:`p`,metin:`Bir Yangın Güvenlik Uzmanı (YGU) adayı, kimya mühendisliği diplomasıyla YGU-K başvurusu yapmak istiyor olsun. Bu aşamada temel öğrenimini, adaylığa ilişkin belgelerini ve resmî eğitim duyurusunu doğrulaması gerekir. Henüz sahada bir deponun periyodik kontrolüne ilişkin EK-5/A başvuru formu doldurması beklenmez.`},{tip:`p`,metin:`Aynı kişi ileride yetki sahibi olduğunda yüksek tehlikeli tesiste görev alırsa, hangi belgelerin yapı sahibine, hangilerinin itfaiye teşkilatına veya yetkili uzmana ait olduğunu ayrıca bilmelidir. Böylece başvuru dosyasıyla teknik kontrol dosyası karıştırılmaz.`},{tip:`h2`,id:`sik-sorulan-sorular`,metin:`Sık sorulan sorular`},{tip:`h3`,metin:`YGU eğitim başvurusu için yalnızca diploma yeterli midir?`},{tip:`p`,metin:`Taslak Madde 10'da diploma dışında kimlik, fotoğraf, adli sicil, KEP ve duruma göre diğer belgeler de sayılmıştır.`},{tip:`h3`,metin:`KEP belgesi taslakta geçiyor mu?`},{tip:`p`,metin:`Evet, Madde 10/2-f'de yer alır. Nihai şartlar resmî ilanla doğrulanmalıdır.`},{tip:`h3`,metin:`Eksik belge 15 gün içinde tamamlanmazsa ne olur?`},{tip:`p`,metin:`Taslak Madde 11/4, Komisyon incelemesi kapsamında belgelerin iadesini ve sınava katılamamayı öngörür.`},{tip:`h3`,metin:`YGU eğitim ücreti yatırmak yetki kazandırır mı?`},{tip:`p`,metin:`Hayır. Ücret, eğitim, sınav başarısı ve yetkilendirme ayrı aşamalardır.`},{tip:`h2`,id:`sonuc`,metin:`Sonuç`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitim başvurusunun güvenilir yolu, önce meslek ve seviye koşullarını doğrulamak, sonra resmî yetkili kurum ilanından belge listesini takip etmektir. Madde 10'daki aday belgeleriyle EK-5'teki yapı kontrol formları kesinlikle birbirine karıştırılmamalıdır.`}],kaynakBaslik:`Kaynakça`,kaynaklar:[{metin:`3194 Sayılı İmar Kanunu`},{metin:`Yangın Güvenlik Uzmanlığı ve Periyodik Kontrol Usul ve Esasları Hakkında Yönetmelik Taslağı`}],sss:[{soru:`YGU eğitim başvurusu için yalnızca diploma yeterli midir?`,yanit:`Taslak Madde 10'da diploma dışında kimlik, fotoğraf, adli sicil, KEP ve duruma göre diğer belgeler de sayılmıştır.`},{soru:`KEP belgesi taslakta geçiyor mu?`,yanit:`Evet, Madde 10/2-f'de yer alır. Nihai şartlar resmî ilanla doğrulanmalıdır.`},{soru:`Eksik belge 15 gün içinde tamamlanmazsa ne olur?`,yanit:`Taslak Madde 11/4, Komisyon incelemesi kapsamında belgelerin iadesini ve sınava katılamamayı öngörür.`},{soru:`YGU eğitim ücreti yatırmak yetki kazandırır mı?`,yanit:`Hayır. Ücret, eğitim, sınav başarısı ve yetkilendirme ayrı aşamalardır.`}]},{no:`12`,baslik:`Yangın Güvenlik Uzmanlığı (YGU) Eğitim Ücretleri, Eğitim Tarihleri ve Kontenjanları Nasıl Öğrenilir?`,ozet:`Yangın Güvenlik Uzmanlığı (YGU) eğitim ücreti, eğitim tarihi ve kontenjan bilgileri, yangın güvenlik uzmanı olmak isteyen kişinin kayıt kararında önemli yer tutar. Ancak eğitim bedeli, sınav bedeli ve resmî kontrol hizmet bedeli birbirinden farklıdır. Taslak bir rakamın veya internette paylaşılan ön kayıt duyurusunun kesinleşmiş program ilanı sanılması, yanlış beklenti oluşturabilir.`,bloklar:[{tip:`not`,etiket:`MEVZUAT DURUMU – TASLAK`,metin:`Ücret belirleme ve duyuru usulleri, YGU yönetmelik taslağının 9, 10, 12 ve ilgili diğer hükümlerine dayanmaktadır. Makale 5 Kasım 2026 tarihi itibarıyla doğrulanmış bir eğitim bedeli veya kurum bazlı kesin takvim göstermemektedir.`},{tip:`h2`,id:`1-ygu-egitim-bedelini-kim-belirleyebilir`,metin:`1. YGU eğitim bedelini kim belirleyebilir?`},{tip:`p`,metin:`TASLAK Madde 12/1 Bakanlığın düzenlediği eğitimlerin bedelinin Bakanlıkça, yetkilendirilmiş eğitici kuruluşlarca düzenlenen eğitimin bedelinin ise ilgili eğitici kuruluşlarca belirlenmesini öngörür. Bu yaklaşım, bütün üniversitelerin ve bütün YGU seviyelerinin kesin olarak aynı ücreti alacağı anlamına gelmez.`},{tip:`p`,metin:`TASLAK Madde 12/2, Bakanlıkça düzenlenen eğitim ve sınav için Bakanlığın belirleyip duyuracağı bedelin Bakanlık Döner Sermaye hesabına yatırılmasını öngörmektedir. Madde 12/3, yatırılan eğitim ve sınav bedelinin iade edilmemesine yönelik düzenleme içerir. Bunların tamamı taslak hükümleridir.`},{tip:`h2`,id:`2-egitim-ve-sinav-ucretleri-neden-ayri-incelenmelidir`,metin:`2. Eğitim ve sınav ücretleri neden ayrı incelenmelidir?`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitimi, teorik ve uygulama aşamaları ile sınav ve yetkilendirmeden oluşabilecek bir sistemdir. Eğitim ilanında verilen rakamın hangi hizmete ait olduğu açıkça yazılmalıdır.`},{tip:`p`,metin:`Sadece eğitim ücreti duyurulmuş olması, sınav bedelinin veya diğer işlem bedellerinin o tutara dahil olduğunu kanıtlamaz. Aynı şekilde taslağın periyodik kontrol hizmetleri için öngördüğü ücret mekanizması, YGU adayının eğitim ücreti olarak gösterilmemelidir.`},{tip:`h2`,id:`3-dort-ygu-seviyesi-icin-ucretler-farkli-mi-olacak`,metin:`3. Dört YGU seviyesi için ücretler farklı mı olacak?`},{tip:`p`,metin:`TASLAK EK-2'de YGU-1 için 65, YGU-2 için 85, YGU-3 için 40 ek ve YGU-K için 35 teorik saat öngörülmektedir. Ancak ders süresinden fiyat hesaplanamaz. “YGU-2 eğitimi YGU-1'den yüzde şu kadar pahalı olacaktır” gibi ifadeler, doğrulanmış resmî fiyat olmadan kullanılamaz.`},{tip:`p`,metin:`Ücret konusunda program seviyesi, eğitim veren yetkili kurum, duyurulan hizmet kapsamı ve ödeme şartları bir arada değerlendirilmelidir.`},{tip:`h2`,id:`4-egitim-tarihi-ile-basvuru-tarihi-ayni-mi`,metin:`4. Eğitim tarihi ile başvuru tarihi aynı mı?`},{tip:`p`,metin:`Hayır. Başvuru başlangıcı ve bitişi, teorik eğitimin başlangıcı, uygulama eğitiminin yapılacağı dönem, sınav tarihi ve belge düzenlenme işlemleri ayrı zamanlardır. TASLAK Madde 10/1, başvuru ilanının Bakanlık veya yetkili eğitici kuruluşun resmî sayfasında yayımlanmasını öngörür; Madde 11/2, sınava ilişkin bilgilerin ayrıca Bakanlıkça duyurulacağını söyler.`},{tip:`p`,metin:`Ön kayıt formu açılması, eğitim başlangıcının kesinleştiğini veya sınav yerinin belirlendiğini göstermez. Yangın Güvenlik Uzmanı (YGU) adayının takvimini bu aşamaları ayırarak oluşturması gerekir.`},{tip:`h2`,id:`5-kontenjan-neye-gore-belirlenir`,metin:`5. Kontenjan neye göre belirlenir?`},{tip:`p`,metin:`Bir kursun ilan ettiği kontenjan, o program için kabul edilebilecek katılımcı sayısını ifade eder. Ancak taslak metinden bütün YGU seviyeleri için sabit ulusal kontenjan sayısı çıkarılamaz. Eğitici kuruluşun yetkilendirme kapsamı ve resmî duyurusu görülmeden kesin kontenjan belirtilmemelidir.`},{tip:`p`,metin:`Başvurunun erken yapılması da diğer koşullar sağlanmadan otomatik kabul veya resmî yetki garantisi vermez.`},{tip:`h2`,id:`6-5-kasim-2026-itibariyla-kesin-ucret-ve-tarih-var-mi`,metin:`6. 5 Kasım 2026 itibarıyla kesin ücret ve tarih var mı?`},{tip:`p`,metin:`Bu makalenin kontrolünde yetkili kurumlara ait toplu ve eksiksiz bir kesin fiyat/takvim listesi elde edilmedi. Bu nedenle “YGU eğitimi ... TL”, “tüm eğitimler ... tarihinde başlıyor” veya “şu kadar kişilik kontenjan var” gibi ifadeler kullanılmamıştır.`},{tip:`p`,metin:`Bilgi güncellenecekse kaynak duyurunun tarihi, kurum adı, program seviyesi, ücretin kapsadığı işlemler ve başvuru süresi birlikte doğrulanmalıdır. Daha önce hazırlanmış blog yazılarındaki tarih ve rakamlar, resmî ilanla karşılaştırılmadan aynen taşınmamalıdır.`},{tip:`h2`,id:`7-saha-ve-meslek-baglantisi`,metin:`7. Saha ve meslek bağlantısı`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitiminin amacı yalnızca sertifika almak değildir. Yapının onaylı projelerini, işletme değişikliklerini ve yangından korunma sistemlerine ilişkin belgeleri ilişkilendirebilecek teknik yeterlilik kazanmak önemlidir. Örneğin bir büro alanının depoya dönüştürülmesinde değişen kullanımın kaçış koşullarına etkisini değerlendirmek, ilgili mevzuat ve proje bilgisi gerektirir.`},{tip:`p`,metin:`Kurs seçerken fiyat kadar programın resmî niteliği, müfredat kapsamı ve uygulama yaklaşımı da önem taşır.`},{tip:`h2`,id:`sik-sorulan-sorular`,metin:`Sık sorulan sorular`},{tip:`h3`,metin:`YGU eğitimi ücretsiz mi?`},{tip:`p`,metin:`Kesin kurum ilanı görülmeden ücretsiz veya ücretli olduğu her program için genellenemez.`},{tip:`h3`,metin:`Sınav bedeli eğitim ücretine dahil mi?`},{tip:`p`,metin:`Ödeme kalemleri resmî duyurudan kontrol edilmelidir; taslak Madde 12 bunları ayrı ele alır.`},{tip:`h3`,metin:`Kontenjanı dolan üniversite diğer şehirlerdeki kursları etkiler mi?`},{tip:`p`,metin:`Her programın ilanı ve kontenjanı ayrı doğrulanmalıdır.`},{tip:`h2`,id:`sonuc`,metin:`Sonuç`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitim ücretleri, tarihler ve kontenjanlar tahminle değil, yetkilendirilmiş kuruluşların resmî duyurularıyla yayımlanmalıdır. Eğitim bedeliyle sınav ve yapı kontrol hizmet bedeli kesinlikle karıştırılmamalıdır.`}],kaynakBaslik:`Kaynakça`,kaynaklar:[{metin:`3194 Sayılı İmar Kanunu`},{metin:`Yangın Güvenlik Uzmanlığı ve Periyodik Kontrol Usul ve Esasları Hakkında Yönetmelik Taslağı`}],sss:[{soru:`YGU eğitimi ücretsiz mi?`,yanit:`Kesin kurum ilanı görülmeden ücretsiz veya ücretli olduğu her program için genellenemez.`},{soru:`Sınav bedeli eğitim ücretine dahil mi?`,yanit:`Ödeme kalemleri resmî duyurudan kontrol edilmelidir; taslak Madde 12 bunları ayrı ele alır.`},{soru:`Kontenjanı dolan üniversite diğer şehirlerdeki kursları etkiler mi?`,yanit:`Her programın ilanı ve kontenjanı ayrı doğrulanmalıdır.`}]},{no:`13`,baslik:`Yangın Güvenlik Uzmanlığı (YGU) Sınavı Nasıl Olacak? Yangın Güvenlik Uzmanı (YGU) Sınavına Hazırlık Rehberi`,ozet:`Yangın Güvenlik Uzmanlığı (YGU) sınavı, yangın güvenlik uzmanı olarak resmî yetkilendirmeye ulaşmak isteyen kişilerin eğitim sonrasında karşılaşacağı bilgi değerlendirme aşamasıdır. Eğitim süreci, sınav başarısı ve yetki belgesinin düzenlenmesi birbirine bağlı olsa da aynı işlem değildir. Bu nedenle YGU sınavına hazırlanırken hem teknik konular hem de başvuru, itiraz ve yeniden sınava girme hükümleri ayrı değerlendirilmelidir.`,bloklar:[{tip:`not`,etiket:`MEVZUAT DURUMU – TASLAK`,metin:`Bu makalede verilen soru sayıları, başarı koşulu, itiraz ve yeniden sınava girme hükümleri, özgün YGU yönetmelik taslağının 11. maddesinden alınmıştır. Bunlar yayımlanmış nihai sınav kılavuzu değildir.`},{tip:`h2`,id:`1-ygu-sinavinin-kanuni-ve-taslak-dayanagi`,metin:`1. YGU sınavının kanuni ve taslak dayanağı`},{tip:`p`,metin:`22 Mayıs 2026 tarihli 7579 sayılı Kanun'un 3194 sayılı İmar Kanunu'na getirdiği düzenleme, eğitim ve sınavda başarılı olarak yetkilendirilen Yangın Güvenlik Uzmanlarının (YGU) belirli koşullarda yangın güvenlik raporu düzenleyebilmesine ilişkin çerçeveyi oluşturmuştur. Uygulama ayrıntıları ise yönetmeliğe bırakılmıştır.`},{tip:`p`,metin:`TASLAK Madde 11, sınavın Bakanlıkça düzenleneceğini ve teorik eğitim konularını kapsayacağını belirtir. Sınavın kesin tarihi ve uygulama merkezi ise Bakanlığın resmî açıklamalarıyla belirlenmelidir.`},{tip:`h2`,id:`2-kimler-ygu-sinavina-girebilecek`,metin:`2. Kimler YGU sınavına girebilecek?`},{tip:`p`,metin:`Taslak Madde 11/3, Madde 14'teki özel muafiyete sahip olanlar dışında, öngörülen eğitimleri tamamlayanların sınava başvurabileceğini düzenler. Bunun temelinde, Madde 5'te belirtilen meslek/seviye koşulları ve Madde 9'daki teorik ve uygulamalı eğitim süreci bulunur.`},{tip:`p`,metin:`YGU-1, YGU-2, YGU-3 ve YGU-K seviyeleri için öğrenim ve geçiş şartları aynı değildir. Genel yangın güvenliği sertifikası sahibi olmak veya iş güvenliği uzmanlığı belgesi taşımak, tek başına resmî YGU sınavına girme hakkı sağlamaz.`},{tip:`h2`,id:`3-taslakta-sinavin-soru-sayisi-ve-basari-kosulu`,metin:`3. Taslakta sınavın soru sayısı ve başarı koşulu`},{tip:`not`,etiket:`TASLAK Madde 11/5`,metin:`YGU-1, YGU-2 ve YGU-3 sınavlarının en az 50 çoktan seçmeli sorudan; YGU-K sınavının en az 25 çoktan seçmeli sorudan oluşması öngörülmektedir. 100 üzerinden 70 ve üstünde puan alan adayların başarılı sayılması önerilmektedir.`},{tip:`tablo`,basliklar:[`Seviye`,`Taslak asgari soru sayısı`,`Taslak başarı sınırı`],satirlar:[[`YGU-1`,`50`,`70/100`],[`YGU-2`,`50`,`70/100`],[`YGU-3`,`50`,`70/100`],[`YGU-K`,`25`,`70/100`]]},{tip:`p`,metin:`Buradaki “en az” ifadesi önemlidir; tablo sınavın kesinlikle yalnız bu sayıda soru içereceği anlamına gelmez. Bu sayılar resmî eğitim belgelerine eklenecek puanlama sistemi değil, taslak yönetmelikte önerilen sınav hükümleridir. Eğitim üniteleri için ayrıca rubrik, puan dağılımı veya notlandırma oluşturulmamaktadır.`},{tip:`h2`,id:`4-eksik-basvuru-belgesi-ve-15-gunluk-sure`,metin:`4. Eksik başvuru belgesi ve 15 günlük süre`},{tip:`p`,metin:`Taslak Madde 11/4'e göre Madde 10'daki başvuru belgelerini Komisyon inceler. Zorunlu belgeler eksikse tamamlamak için 15 gün süre öngörülür. Süre içinde tamamlanmayan belgeler Bakanlıkça iade edilir ve ilgili kişi sınava katılamaz.`},{tip:`p`,metin:`Madde 11/4'ün belge incelemesini sınava kabul sonucu ile ilişkilendirmesi nedeniyle, bu hüküm doğrudan “üniversite kaydını kesinleştirmek için herkese 15 gün verilir” şeklinde anlatılmamalıdır. Eğitim ilanı ve sınav kabul süreci ayrı incelenmelidir.`},{tip:`h2`,id:`5-taslakta-itiraz-hakki-ve-sinava-tekrar-giris`,metin:`5. Taslakta itiraz hakkı ve sınava tekrar giriş`},{tip:`not`,etiket:`TASLAK Madde 11/6`,metin:`Sınav sonucuna itiraz, sonuçların ilanını izleyen yedi iş günü içinde yapılır; Bakanlığın itirazı on beş iş günü içinde karara bağlaması öngörülür.`},{tip:`not`,etiket:`TASLAK Madde 11/7`,metin:`Sınavda başarılı olamayan veya geçerli mazeret nedeniyle sınava katılamayan kişiye, yeniden eğitime katılmaksızın en fazla bir kez daha sınava girme hakkı öngörülmektedir. Bu hakkın hangi koşullarda kullanılacağına ilişkin sınav duyurusu ayrıca takip edilmelidir.`},{tip:`p`,metin:`Bu hükümler gelecekteki sınav takviminin ilan edildiği anlamına gelmez; başvuru ve değerlendirme usulüne ilişkin taslak kurallardır.`},{tip:`h2`,id:`6-ygu-sinavina-teknik-hazirlik-hangi-konularla-baslamali`,metin:`6. YGU sınavına teknik hazırlık hangi konularla başlamalı?`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) adayları, EK-2 eğitim müfredatını kendi seviyelerine göre okumalıdır. Ortak başlangıç alanları yangın bilimi, yangın mevzuatı ve proje okuma yaklaşımıdır. YGU-1 ile YGU-2'nin yapı, kaçış yolları, elektrik ve mekanik yangın güvenliği sistemlerine ilişkin modülleri aynı teknik derinlikte düzenlenmemiştir.`},{tip:`p`,metin:`YGU-3 için yüksek tehlikeli yapılar ve uluslararası teknik dokümanlar; YGU-K için tehlikeli maddeler, sınıflandırma ve ilgili kontrol süreçleri öne çıkar. Ancak sınavın kesin soru dağılımı taslak eğitim modüllerinden varsayılarak uydurulmamalıdır.`},{tip:`h2`,id:`7-saha-ornegi-mevzuati-dogru-uygulama`,metin:`7. Saha örneği: mevzuatı doğru uygulama`},{tip:`p`,metin:`Bir konaklama yapısında kaçış kapısının sürekli kilitli tutulduğunu düşünelim. Yangın Güvenlik Uzmanı (YGU) incelemesinde önce yapının onaylı projesi, ilgili kullanım ve ruhsat bilgileri, kapının kaçış düzenindeki yeri ve gerçek saha koşulları belirlenir.`},{tip:`p`,metin:`Sonrasında uygulanabilir BYKHY hükümleri araştırılır; varsa teknik belgeler ve istisnalar birlikte değerlendirilir. Sadece “kapı kilitli” gözlemi değil, bu tespitin kaçış güvenliğine etkisi ve dayanağı raporlanır. Mesleki hazırlıkta doğru bilgi–belge–hüküm bağlantısı kurabilmek, salt tanım ezberinden daha değerlidir.`},{tip:`h2`,id:`8-yetki-belgesi-sinavdan-hemen-sonra-mi-verilir`,metin:`8. Yetki belgesi sınavdan hemen sonra mı verilir?`},{tip:`p`,metin:`TASLAK Madde 13, başarılı olanların yetki belgesi almaya hak kazanacağını ve belgenin Bakanlıkça elektronik doğrulanabilir biçimde düzenleneceğini söyler. Bununla birlikte sınav sonucunun açıklanması ile belge kaydının tamamlanması aynı anda olmak zorunda değildir; resmî işlemler takip edilmelidir.`},{tip:`p`,metin:`Sınavın yapılması, kişinin bütün yapılar için sınırsız yangın güvenliği kontrolü yapabileceği anlamına da gelmez. Görev ve yetki sınırları, taslak Madde 6 ile EK-1'in ilgili kullanım sınıfı tablosuna bağlıdır.`},{tip:`h2`,id:`sik-sorulan-sorular`,metin:`Sık sorulan sorular`},{tip:`h3`,metin:`YGU sınavı 50 soru mu olacak?`},{tip:`p`,metin:`Taslak YGU-1, YGU-2 ve YGU-3 için en az 50, YGU-K için en az 25 soru der. Kesin sınav duyurusu ayrıca gerekir.`},{tip:`h3`,metin:`YGU sınavı geçme puanı 70 mi?`},{tip:`p`,metin:`İncelenen taslakta 100 üzerinden 70 yer alır; yürürlükteki kesin koşul olarak sunulmamalıdır.`},{tip:`h3`,metin:`Sonuca itiraz mümkün mü?`},{tip:`p`,metin:`Taslak, yedi iş günü içinde itiraz ve on beş iş günü içinde karara bağlama öngörmektedir.`},{tip:`h3`,metin:`A sınıfı iş güvenliği uzmanı sınavdan muaf mı?`},{tip:`p`,metin:`Böyle genel bir muafiyet yoktur. Taslak Madde 14'ün dar kurum, meslek ve deneyim koşulları ayrıca incelenmelidir.`},{tip:`h2`,id:`sonuc`,metin:`Sonuç`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) sınavında hazırlığın temeli, resmî müfredatı seviyeye göre çalışmak ve mevzuat uygulama becerisini geliştirmektir. Taslaktaki soru, başarı, itiraz ve tekrar sınav hükümleri artık somut olarak görülebilmektedir; ancak nihai yönetmelik ve sınav kılavuzu çıkmadan kesin takvim ve hak iddiasında bulunulmamalıdır.`}],kaynakBaslik:`Kaynakça`,kaynaklar:[{metin:`3194 Sayılı İmar Kanunu`},{metin:`7579 Sayılı Tapu Kanunu ile Bazı Kanunlarda ve 375 Sayılı Kanun Hükmünde Kararnamede Değişiklik Yapılmasına Dair Kanun`},{metin:`Binaların Yangından Korunması Hakkında Yönetmelik`},{metin:`Yangın Güvenlik Uzmanlığı ve Periyodik Kontrol Usul ve Esasları Hakkında Yönetmelik Taslağı`}],sss:[{soru:`YGU sınavı 50 soru mu olacak?`,yanit:`Taslak YGU-1, YGU-2 ve YGU-3 için en az 50, YGU-K için en az 25 soru der. Kesin sınav duyurusu ayrıca gerekir.`},{soru:`YGU sınavı geçme puanı 70 mi?`,yanit:`İncelenen taslakta 100 üzerinden 70 yer alır; yürürlükteki kesin koşul olarak sunulmamalıdır.`},{soru:`Sonuca itiraz mümkün mü?`,yanit:`Taslak, yedi iş günü içinde itiraz ve on beş iş günü içinde karara bağlama öngörmektedir.`},{soru:`A sınıfı iş güvenliği uzmanı sınavdan muaf mı?`,yanit:`Böyle genel bir muafiyet yoktur. Taslak Madde 14'ün dar kurum, meslek ve deneyim koşulları ayrıca incelenmelidir.`}]},{no:`14`,baslik:`Yangın Güvenlik Uzmanı (YGU) Belgesi Nasıl Alınır? Yangın Güvenlik Uzmanlığı (YGU) Yetkilendirme Süreci`,ozet:`Yangın Güvenlik Uzmanı (YGU) belgesi, genel yangın güvenliği kurs sertifikasıyla karıştırılmamalıdır. Yangın Güvenlik Uzmanlığı (YGU) sisteminde mesleki kabul, teorik ve uygulama eğitimi, sınav ve resmî yetkilendirme birbirinden farklı aşamalardır. Bir kişinin yangın güvenliği konusunda deneyimli olması veya üniversite katılım belgesi alması, kendiliğinden YGU yetkisi kazandığı anlamına gelmez.`,bloklar:[{tip:`not`,etiket:`MEVZUAT DURUMU – TASLAK`,metin:`Aşağıdaki beş yıllık geçerlilik, elektronik doğrulama, yenileme ve askı koşulları özgün YGU yönetmelik taslağının 13. maddesine dayanmaktadır. Yayımlanmış nihai belge düzeni olarak sunulmamaktadır.`},{tip:`h2`,id:`1-ygu-yetki-belgesi-hangi-islemi-gosterir`,metin:`1. YGU yetki belgesi hangi işlemi gösterir?`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU) yetki belgesi, kişinin ilgili seviyede mevzuatla tanımlanan görevleri üstlenebilecek resmî yetkilendirme durumunu gösterir. Taslak Madde 13/1, belgenin Bakanlıkça elektronik ortam üzerinden doğrulanabilir biçimde düzenlenmesini öngörür. Bu, belgenin doğrulanabilirliğinin önemini gösterir; ancak kesin erişim ekranı veya belge numarası sisteminin fiilen kullanıldığını kanıtlamaz.`},{tip:`p`,metin:`Bir katılım sertifikasının üzerinde “yangın güvenliği” veya “üniversite” yazması, Bakanlıkça düzenlenmiş YGU yetki belgesiyle aynı anlama gelmez.`},{tip:`h2`,id:`2-belgeye-ulasmak-icin-hangi-asamalar-ongoruluyor`,metin:`2. Belgeye ulaşmak için hangi aşamalar öngörülüyor?`},{tip:`p`,metin:`Önce taslak Madde 5'teki meslek ve seviye koşulları sağlanmalıdır. Madde 9, teorik ve uygulamalı eğitimi; Madde 11, sınavı; Madde 13 ise başarılı olan kişinin belge hakkını ve belge düzenini ele alır.`},{tip:`p`,metin:`TASLAK Madde 11, YGU-1/2/3 için en az 50, YGU-K için en az 25 çoktan seçmeli soru ve 100 üzerinden en az 70 başarı koşulu öngörür. Bu rakamlar resmî sınav sisteminin kesinleştiği anlamına gelmez; taslak uzmanlık belgelendirme düzeninin bir parçasıdır.`},{tip:`h2`,id:`3-ygu-belgesinin-gecerlilik-suresi-ne-kadar-olacak`,metin:`3. YGU belgesinin geçerlilik süresi ne kadar olacak?`},{tip:`p`,metin:`TASLAK Madde 13/3, yetki belgesinin geçerlilik süresini beş yıl olarak öngörür. Yenileme için yeniden eğitime katılmaksızın tekrar sınava girilip başarılı olunmasına ilişkin yol tarif edilir. İki sınav girişinde başarısız olunduğunda yeniden eğitime katılma şartı da aynı taslakta bulunur.`},{tip:`p`,metin:`Taslak Madde 13/4, süresi içinde yenileme yapılmadığında yetkinin yenilemeye kadar askıya alınmasını ve bu sırada YGU olarak faaliyet gösterilememesini öngörür. İhtiyaç duyulan ilave eğitimlere katılmama halinde askıya alma hakkında da ayrı hükümler vardır.`},{tip:`h2`,id:`4-belge-dogrulamada-yalnizca-isim-yeterli-mi`,metin:`4. Belge doğrulamada yalnızca isim yeterli mi?`},{tip:`p`,metin:`Resmî yetkilendirme değerlendirmesinde kişinin kimliği, uzmanlık seviyesi, belgenin geçerliliği, varsa askı veya iptal kararı ve yapılacak işin bu seviyeye uygunluğu birlikte kontrol edilmelidir. Taslak Madde 13/6, geçerli belge sahipleri ile askı veya iptal durumlarına ilişkin bilgilerin Bakanlık tarafından yayımlanmasını öngörür.`},{tip:`p`,metin:`Bir YGU belgesinin bulunması, bir yapıda yapılan bütün işlemlere uygun yetki bulunduğunu göstermez. Taslak Madde 6 ve EK-1, görev türünü ve yapı sınıfı/sınırlarını birlikte ele alır.`},{tip:`h2`,id:`5-bagimsizlik-ve-cikar-catismasi-neden-onemli`,metin:`5. Bağımsızlık ve çıkar çatışması neden önemli?`},{tip:`p`,metin:`TASLAK Madde 8, Yangın Güvenlik Uzmanının (YGU) tarafsız ve bağımsız hareket etmesini, belirli ticari faaliyetlerde bulunduğu proje ve yapılarda görev almamasını ve görevini başkasına devretmemesini düzenler. Bu tür koşullar, resmî kontrolün güvenilirliği ve bulguların objektif biçimde raporlanması açısından önemlidir.`},{tip:`p`,metin:`YGU'nun bir projeye danışmanlık yapmış olması ile aynı projede bağımsız resmî kontrol görevi üstlenmesi arasındaki olası çıkar çatışması, taslak kapsamındaki sınırlamalar dikkate alınmadan geçiştirilemez. Ancak bu düzenlemeler de nihai hüküm olarak gösterilmemelidir.`},{tip:`h2`,id:`6-saha-ornegi-belgeyi-gorevle-eslestirme`,metin:`6. Saha örneği: belgeyi görevle eşleştirme`},{tip:`p`,metin:`Bir kimyasal depo binasında periyodik kontrol yapılması planlandığında yalnızca “belgeli bir Yangın Güvenlik Uzmanı (YGU) geldi” denilmesi yeterli değildir. Yapının kullanım sınıfı ve tehlike düzeyi, taslak EK-1'deki ilgili satır ve Madde 6'daki görev ayrımı belirlenmelidir.`},{tip:`p`,metin:`YGU-K'nin tehlikeli maddelerin tespiti ve sınıflandırılmasına ilişkin rolü, genel bina kontrol uzmanlığından ayrıdır. Yetkinin kapsamı ile yapılan iş arasında ilişki kurulmadan hazırlanmış rapor, eğitim sertifikası veya eski bir belge kopyasıyla karıştırılmamalıdır.`},{tip:`h2`,id:`sik-sorulan-sorular`,metin:`Sık sorulan sorular`},{tip:`h3`,metin:`Sertifika YGU belgesi yerine geçer mi?`},{tip:`p`,metin:`Hayır; eğitim tamamlama ve resmî yetkilendirme ayrı işlemlerdir.`},{tip:`h3`,metin:`Taslakta belge süresi beş yıl mı?`},{tip:`p`,metin:`Evet; Madde 13/3'te öyle yazılıdır, ancak yürürlükteki kesin kural olarak sunulmamalıdır.`},{tip:`h3`,metin:`Belge süre dolunca kullanılabilir mi?`},{tip:`p`,metin:`Taslak yenileme yapılana kadar askı öngörür.`},{tip:`h3`,metin:`İSG uzmanlığı belgesi YGU belgesi yerine geçer mi?`},{tip:`p`,metin:`Hayır; farklı mevzuatla düzenlenen ayrı yetkilerdir.`},{tip:`h2`,id:`sonuc`,metin:`Sonuç`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) belgesi, yalnızca eğitim katılımını değil resmî yetkilendirmeyi gösterir. Belgenin geçerliliği, seviyesi ve ilgili görev kapsamı birlikte değerlendirilmelidir. Taslaktaki elektronik doğrulama ve yenileme hükümleri, nihai düzenleme ve resmî sistem açıklanana kadar kesinleşmiş işlem gibi sunulamaz.`}],kaynakBaslik:`Kaynakça`,kaynaklar:[{metin:`3194 Sayılı İmar Kanunu`},{metin:`7579 Sayılı Tapu Kanunu ile Bazı Kanunlarda ve 375 Sayılı Kanun Hükmünde Kararnamede Değişiklik Yapılmasına Dair Kanun`},{metin:`Binaların Yangından Korunması Hakkında Yönetmelik`},{metin:`Yangın Güvenlik Uzmanlığı ve Periyodik Kontrol Usul ve Esasları Hakkında Yönetmelik Taslağı`}],sss:[{soru:`Sertifika YGU belgesi yerine geçer mi?`,yanit:`Hayır; eğitim tamamlama ve resmî yetkilendirme ayrı işlemlerdir.`},{soru:`Taslakta belge süresi beş yıl mı?`,yanit:`Evet; Madde 13/3'te öyle yazılıdır, ancak yürürlükteki kesin kural olarak sunulmamalıdır.`},{soru:`Belge süre dolunca kullanılabilir mi?`,yanit:`Taslak yenileme yapılana kadar askı öngörür.`},{soru:`İSG uzmanlığı belgesi YGU belgesi yerine geçer mi?`,yanit:`Hayır; farklı mevzuatla düzenlenen ayrı yetkilerdir.`}]},{no:`15`,baslik:`Yangın Güvenlik Uzmanlığı (YGU) Eğitiminde Teorik ve Uygulamalı Dersler Neden Önemlidir?`,ozet:`Yangın Güvenlik Uzmanlığı (YGU) eğitiminde teori ve uygulama iki ayrı öğrenme alanıdır. Yangın Güvenlik Uzmanı (YGU), yönetmeliğin ne söylediğini bilmekle yetinmemeli; hükmün hangi projeye, yapı bölümüne ve saha koşuluna uygulanacağını anlayabilmelidir. Bu nedenle teknik eğitim, mevzuatın yapıyla ve gerçek kullanım koşullarıyla eşleştirilmesini sağlamalıdır.`,bloklar:[{tip:`not`,etiket:`MEVZUAT DURUMU – TASLAK`,metin:`Aşağıdaki eğitim yöntemi ve devam koşulları, özgün YGU yönetmelik taslağı Madde 9'daki önerilerdir. Kendi başına yürürlüğe girmiş bir eğitim duyurusu değildir.`},{tip:`h2`,id:`1-teorik-ygu-egitimi-hangi-amaci-tasir`,metin:`1. Teorik YGU eğitimi hangi amacı taşır?`},{tip:`p`,metin:`Yangın bilimi, BYKHY'nin sistematiği, yapı ve malzeme davranışı, kaçış düzeni, yangın algılama/söndürme sistemleri ve raporlama bilgileri teorik eğitimin temel alanlarıdır. Örneğin yangın kapısının neden gerekli olduğu ve bir yangın bölmesinin sürekliliğinin nasıl korunduğu anlaşılmadan sahada doğru değerlendirme yapmak zordur.`},{tip:`p`,metin:`EK-2 modülleri, bu bilgileri YGU-1, YGU-2, YGU-3 ve YGU-K seviyelerine göre farklı kapsamda düzenler. YGU-1'in tüm kazanımları YGU-2'ninkilerle aynı değildir; YGU-K'nin tehlikeli madde sınıflandırmasına ilişkin özel odağı bulunmaktadır.`},{tip:`h2`,id:`2-taslakta-teorik-egitim-nerede-ve-nasil-verilir`,metin:`2. Taslakta teorik eğitim nerede ve nasıl verilir?`},{tip:`p`,metin:`TASLAK Madde 9/1-2, teorik eğitimin Bakanlık veya yetkilendirilmiş eğitici kuruluşça verilmesini, yüz yüze ya da uzaktan düzenlenebilmesini öngörür. Madde 9/3 teorik eğitime en az %90 devamı katılım belgesi koşulu olarak tarif eder.`},{tip:`p`,metin:`Bu oran, eğitim ünitesi içinde ayrıca kurulmuş bir ölçme-değerlendirme veya puanlama sistemi değildir. Taslakta tarif edilen bir devam şartıdır. Resmî kursun kesin uygulama şartları nihai metin ve eğitim ilanıyla belirlenir.`},{tip:`h2`,id:`3-uygulama-egitiminin-gorevli-kurumu-ve-kapsami-nedir`,metin:`3. Uygulama eğitiminin görevli kurumu ve kapsamı nedir?`},{tip:`p`,metin:`TASLAK Madde 9/1, uygulama eğitiminin mahalli itfaiye teşkilatınca verilmesini öngörür. Madde 9/5 ise adayların farklı kullanım sınıfındaki iki yapıya ilişkin yangın güvenlik raporu düzenleme ve uygulama gözetimi faaliyetlerine katılmasını tarif eder.`},{tip:`p`,metin:`Bu düzenleme, teorik eğitimin uzaktan verilebilmesiyle uygulama çalışmasının aynı şey olmadığını gösterir. Adayın örnek yapıdaki görevleri, kendi mesleki/öğrenme kapsamına uygun biçimde yürütülmelidir; herhangi bir dış elektrik, makine veya kimya mühendisine eğitim dokümanını ayrıca imzalatma gibi bir zorunluluk çıkarılmamalıdır.`},{tip:`h2`,id:`4-proje-okuma-uygulamasi-nasil-ogretici-olur`,metin:`4. Proje okuma uygulaması nasıl öğretici olur?`},{tip:`p`,metin:`Örneğin bir büro binasının kat planındaki kaçış merdiveni, yangın kapıları ve yangın bölmeleri işaretlenebilir. Ardından sahadaki düzenlemelerle proje karşılaştırılır. Bu karşılaştırmada öncelikle geçerli onaylı proje ve yapının kullanım izni belirlenmelidir.`},{tip:`p`,metin:`Proje ile saha arasında fark görülürse önce değişikliğin izin durumu ve uygulanabilir BYKHY hükümleri araştırılır. Her farklılık otomatik uygunsuzluk sayılmaz. Yangın Güvenlik Uzmanı (YGU), belirsizlikleri ve ek belge ihtiyaçlarını teknik gerekçeleriyle ifade edebilmelidir.`},{tip:`h2`,id:`5-yangin-tesisatlarinda-uygulama-egitimi-neye-odaklanmali`,metin:`5. Yangın tesisatlarında uygulama eğitimi neye odaklanmalı?`},{tip:`p`,metin:`Yangın algılama, sprinkler, yangın dolapları, pompalar ve duman kontrol sistemleriyle ilişkili proje ve teknik belgelerin okunması önemlidir. Bir sistemin sahada görünmesi, çalışmasının uygun olduğunu kanıtlamaz; test ve bakım kayıtları ayrıca değerlendirilir.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU), görevine göre kanıtları ve eksiklikleri belirlemelidir. Özel hidrolik hesap veya cihaz performans testlerinin bütün katılımcılar tarafından yerine getirilmesi, genel YGU eğitiminin otomatik sonucu olarak yorumlanamaz.`},{tip:`h2`,id:`6-ornek-vaka-mevcut-yapida-tadilat`,metin:`6. Örnek vaka: mevcut yapıda tadilat`},{tip:`p`,metin:`Bir konaklama yapısında iki oda birleştirilmiş ve aradaki koridor düzeni değiştirilmiş olsun. Önce yapı kullanma izni ve tadilat projesi araştırılır. Kaçış yolu genişliği, kapı düzeni, yangın bölmesi ve algılama sistemi yeni kullanımla birlikte değerlendirilir.`},{tip:`p`,metin:`Bu uygulamada Yangın Güvenlik Uzmanlığı (YGU) eğitimindeki mevzuat, mimari proje, sistemler ve raporlama modülleri birlikte kullanılır. Öğretici sonuç, yalnız “uygun/uygunsuz” işareti değil, kanıt ve gerekçelerin açık biçimde gösterilmesidir.`},{tip:`h2`,id:`sik-sorulan-sorular`,metin:`Sık sorulan sorular`},{tip:`h3`,metin:`Teorik YGU eğitimi yalnızca çevrim içi olabilir mi?`},{tip:`p`,metin:`Taslak teorik bölüm için uzaktan yönteme izin verir; uygulama eğitimi ayrıca düzenlenir.`},{tip:`h3`,metin:`Taslakta teorik devam şartı ne kadar?`},{tip:`p`,metin:`En az %90; kesin uygulama nihai düzenlemeye bağlıdır.`},{tip:`h3`,metin:`Uygulamada neden iki farklı yapı var?`},{tip:`p`,metin:`Farklı kullanım sınıflarının farklı teknik ve mevzuat gerekliliklerini karşılaştırabilmek açısından öğreticidir.`},{tip:`h2`,id:`sonuc`,metin:`Sonuç`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitiminin amacı, teknik bilgiyi saha değerlendirmesinde kullanılabilir hale getirmektir. Taslakta teorik/uygulamalı ayrım ve iki farklı yapı üzerinde çalışma açıkça düzenlenmiştir; ancak eğitim yeri, takvim ve kesin yetkilendirme nihai mevzuatla doğrulanmalıdır.`}],kaynakBaslik:`Kaynakça`,kaynaklar:[{metin:`Binaların Yangından Korunması Hakkında Yönetmelik`},{metin:`Binaların Yangından Korunması Hakkında Yönetmelik Kılavuzu`},{metin:`Yangın Güvenlik Uzmanlığı ve Periyodik Kontrol Usul ve Esasları Hakkında Yönetmelik Taslağı`}],sss:[{soru:`Teorik YGU eğitimi yalnızca çevrim içi olabilir mi?`,yanit:`Taslak teorik bölüm için uzaktan yönteme izin verir; uygulama eğitimi ayrıca düzenlenir.`},{soru:`Taslakta teorik devam şartı ne kadar?`,yanit:`En az %90; kesin uygulama nihai düzenlemeye bağlıdır.`},{soru:`Uygulamada neden iki farklı yapı var?`,yanit:`Farklı kullanım sınıflarının farklı teknik ve mevzuat gerekliliklerini karşılaştırabilmek açısından öğreticidir.`}]},{no:`16`,baslik:`Yangın Güvenlik Uzmanlığı (YGU) Eğitim Müfredatı: YGU Eğitiminde Hangi Konular Öğrenilecek?`,ozet:`Yangın Güvenlik Uzmanlığı (YGU) eğitim müfredatı, yangın güvenlik uzmanı olmak isteyen kişinin yalnızca hangi derslere katılacağını değil, yapıların yangın güvenliğini nasıl değerlendirebileceğini de gösterir. Özgün yönetmelik taslağının EK-2 tablosunda modül başlıkları, içerikler, kazanımlar, asgari teorik süreler, hedef uzmanlık seviyeleri ve eğitici branşları ayrı sütunlarda tanımlanmıştır.`,bloklar:[{tip:`p`,metin:`Bu makalede EK-2'nin modülleri tek tek özetlenirken yönetmelik taslağının Madde 9'unda öngörülen uygulama eğitimi ayrıca açıklanmaktadır. YGU eğitiminin bilimsel/teknik içeriğiyle resmî yetkilendirme süreci aynı şey değildir.`},{tip:`not`,etiket:`MEVZUAT DURUMU – TASLAK`,metin:`Aşağıdaki modül adları ve saatler Kitaplık'taki YGU yönetmelik taslağı EK-2 sürümünden alınmıştır. Yürürlükteki kesin eğitim müfredatı veya ilan edilmiş kurs takvimi olarak yorumlanmamalıdır.`},{tip:`h2`,id:`1-ygu-egitiminde-ortak-baslangic-modulleri`,metin:`1. YGU eğitiminde ortak başlangıç modülleri`},{tip:`p`,metin:`EK-2'de Modül 1-A Yangın Bilimi (2 saat), Modül 1-B Yasal Çerçeve (4 saat) olarak yer alır. Bu iki modül YGU-1, YGU-2 ve YGU-K için ortaktır. Yangın Bilimi, yanma ve yangın davranışına ilişkin temel kavramları; Yasal Çerçeve, ulusal yangın mevzuatını okuma, yetki ve etik konularını ele alır.`},{tip:`p`,metin:`Modül 1-C Yangın Projeleri (3 saat) ise YGU-1 ve YGU-2 için proje okumaya odaklanır. Bu modülde teknik çizimin bütün ayrıntılarının tasarlanması değil, projedeki yangın güvenliği düzenlemelerinin anlaşılması hedeflenir.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU), çalışma sırasında bir kuralı yalnızca ezberlemekle kalmamalı; hangi bina verisine bağlı olduğunu ve sahada hangi kanıtla doğrulanabileceğini anlayabilmelidir.`},{tip:`h2`,id:`2-yapi-malzeme-ve-tahliye-modulleri`,metin:`2. Yapı, malzeme ve tahliye modülleri`},{tip:`p`,metin:`EK-2, Yapı ve Malzeme konusunda YGU-1 için Modül 2-A'yı 4 saat, YGU-2 için Modül 2-B'yi 6 saat düzenler. Her iki programda yapı malzemelerinin yangın davranışı ve yapı elemanlarının korunması ele alınır; ancak kazanımların teknik derinliği farklıdır.`},{tip:`p`,metin:`Modül 3-A Kaçış Yolları YGU-1 için 8 saat; Modül 3-B Tahliye YGU-2 için 14 saattir. Bina kullanım sınıfları, kaçış düzenlemeleri, kullanıcı davranışı ve tahliye ilişkileri bu alanın odağındadır.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitiminde örnek bir kat planındaki kaçış kapısının türü, merdiven konumu ve korunmuş alan ilişkisi birlikte incelenmelidir. Plan üzerinde görülen bir düzenlemenin sahadaki karşılığı değerlendirilmeden uygunluk sonucu verilmez.`},{tip:`h2`,id:`3-elektrik-tesisati-ve-yangin-guvenligi-sistemleri`,metin:`3. Elektrik tesisatı ve yangın güvenliği sistemleri`},{tip:`p`,metin:`Modül 4-A Yangın Güvenliği Sistemleri-1, YGU-1 için 8 saattir. Modül 4-B ise YGU-2 için 12 saat olarak düzenlenmiştir. Her iki modül elektrik tesisatı ve sistemlerine ilişkindir: asansör, yıldırımdan korunma, transformatör, jeneratör, elektrik tesisatı, güneş enerjisi sistemleri, acil aydınlatma, yönlendirme ve yangın algılama/uyarı sistemleri gibi alanları kapsar.`},{tip:`p`,metin:`Buradaki eğitim, özel mühendislik test veya tasarım yetkilerinin tüm katılımcılara kendiliğinden verildiği anlamına gelmez. Yangın Güvenlik Uzmanı (YGU), kendi görevindeki uygunluk değerlendirmesi için teknik belge, proje ve saha bilgilerinin ilişkisini öğrenir.`},{tip:`h2`,id:`4-mekanik-sondurme-ve-duman-kontrolu-modulleri`,metin:`4. Mekanik söndürme ve duman kontrolü modülleri`},{tip:`p`,metin:`Modül 5-A Yangın Güvenliği Sistemleri-2 YGU-1 için 8 saat; Modül 5-B YGU-2 için 12 saattir. Duman kontrolü, basınçlandırma, sulu söndürme sistemleri, köpüklü/gazlı/tozlu sabit söndürme ve taşınabilir söndürücüler bu modül ailesine dahildir.`},{tip:`p`,metin:`Bir sprinkler sisteminin sadece projede çizilmiş olması, gerçek binada doğru kurulduğunun veya gerekli bakım/testlerinin yapılmış olduğunun tek başına kanıtı değildir. Yangın Güvenlik Uzmanı (YGU), proje, gözlem, bakım ve test kayıtlarını uygun kanıt türleri olarak ayrı ayrı okuyabilmelidir.`},{tip:`h2`,id:`5-yuksek-tehlikeli-yapilar-ve-tehlikeli-maddeler`,metin:`5. Yüksek tehlikeli yapılar ve tehlikeli maddeler`},{tip:`p`,metin:`Modül 6-A YGU-1 ve YGU-2 için 4 saatlik temel içeriktir. Modül 6-B YGU-3 ve YGU-K için 24 saattir. Tehlikeli maddelerin depolanması ve kullanılması, patlayıcı maddeler, parlayıcı gazlar, yanıcı ve parlayıcı sıvılar, ilgili tehlike sınıflandırması ve alınacak yangın tedbirleri bu grubun konularıdır.`},{tip:`p`,metin:`YGU-K'nin bu alandaki eğitimi, yüksek tehlikeli yapıların periyodik kontrolünde maddelerin tespit ve sınıflandırılması yönündeki taslak göreviyle ilişkilidir. Genel yapı yangın güvenliği kontrolü ile özel tehlikeli madde değerlendirmesi birbirine karıştırılmamalıdır.`},{tip:`h2`,id:`6-periyodik-kontrol-tatbikat-proje-uygunlugu-ve-standart-okuma`,metin:`6. Periyodik kontrol, tatbikat, proje uygunluğu ve standart okuma`},{tip:`p`,metin:`Modül 7-A Periyodik Kontrol ve Süreçleri YGU-1/YGU-2 için 20 saat; Modül 7-B YGU-K için 5 saattir. Kontrol süreci, formlar, teknik bulguların sunumu ve raporlama bu modüllerde açıklanır.`},{tip:`p`,metin:`Modül 8 Yangın Güvenliği Sorumluluğu YGU-1/YGU-2 için 4 saatlik tatbikat, eğitim ve ekip konularını; Modül 9 Yapı Ruhsatı ve Yapı Kullanma İzni Aşamalarındaki Kontroller YGU-2 için 4 saatlik uygunluk incelemesini kapsar.`},{tip:`p`,metin:`Modül 10 Uluslararası Doküman ve Standart Okuma, YGU-3 için 16 saattir. Buradaki amaç, ulusal mevzuatta hüküm bulunmayan durumlarda teknik kaynakların nasıl değerlendirileceğini anlamaktır. Bu modül ulusal mevzuatın yerine kendiliğinden yabancı standart uygulanabileceği şeklinde yorumlanmamalıdır.`},{tip:`h2`,id:`7-ek-2-modul-ve-saat-tablosu`,metin:`7. EK-2 modül ve saat tablosu`},{tip:`tablo`,basliklar:[`EK-2 modülü`,`Başlık`,`Saat`,`Seviye`],satirlar:[[`1-A`,`Yangın Bilimi`,`2`,`YGU-1, YGU-2, YGU-K`],[`1-B`,`Yasal Çerçeve`,`4`,`YGU-1, YGU-2, YGU-K`],[`1-C`,`Yangın Projeleri`,`3`,`YGU-1, YGU-2`],[`2-A / 2-B`,`Yapı ve Malzeme`,`4 / 6`,`YGU-1 / YGU-2`],[`3-A / 3-B`,`Kaçış Yolları / Tahliye`,`8 / 14`,`YGU-1 / YGU-2`],[`4-A / 4-B`,`Yangın Güvenliği Sistemleri-1`,`8 / 12`,`YGU-1 / YGU-2`],[`5-A / 5-B`,`Yangın Güvenliği Sistemleri-2`,`8 / 12`,`YGU-1 / YGU-2`],[`6-A / 6-B`,`Yüksek Tehlikeli Binalar ve Tehlikeli Maddeler`,`4 / 24`,`YGU-1 ve YGU-2 / YGU-3 ve YGU-K`],[`7-A / 7-B`,`Periyodik Kontrol ve Süreçleri`,`20 / 5`,`YGU-1 ve YGU-2 / YGU-K`],[`8`,`Yangın Güvenliği Sorumluluğu`,`4`,`YGU-1, YGU-2`],[`9`,`Yapı Ruhsatı ve Yapı Kullanma İzni Aşamalarındaki Kontroller`,`4`,`YGU-2`],[`10`,`Uluslararası Doküman ve Standart Okuma`,`16`,`YGU-3`]]},{tip:`p`,metin:`EK-2 modüllerinin seviye bazında toplamı: YGU-1 = 65 saat, YGU-2 = 85 saat, YGU-3 = 40 saat ek eğitim, YGU-K = 35 saat. Modül 6-B'nin 24 saati, YGU-3 ve YGU-K hesaplarında ayrı ayrı yer alır; bir kez ortak modül gibi toplanıp ikiye bölünmez.`},{tip:`h2`,id:`8-teorik-mufredat-ile-uygulama-egitimi-ayri-sureclerdir`,metin:`8. Teorik müfredat ile uygulama eğitimi ayrı süreçlerdir`},{tip:`p`,metin:`TASLAK Madde 9, teorik eğitimin Bakanlık veya Bakanlıkça yetkilendirilen eğitici kuruluşça, uygulamanın ise mahalli itfaiye teşkilatınca verilmesini öngörmektedir. Teorik eğitim yüz yüze veya uzaktan yapılabilir; katılım belgesi için en az %90 devam şartı önerilmiştir.`},{tip:`p`,metin:`Uygulamada farklı kullanım sınıfındaki iki yapıya ilişkin yangın güvenlik raporu düzenleme ve uygulama gözetimi bulunur. Bu uygulama, yukarıdaki teorik saat toplamlarıyla aynı kalem değildir. Eğitimin fiili süresi ve takvimi, resmî program düzenlenmeden varsayılamaz.`},{tip:`h2`,id:`9-saha-ornegi-ek-2-kazanimlarinin-birlestirilmesi`,metin:`9. Saha örneği: EK-2 kazanımlarının birleştirilmesi`},{tip:`p`,metin:`Bir depoda tadilat sonrası yeni bir bölme oluşturulduğunda Yangın Güvenlik Uzmanı (YGU), önce yapının kullanım sınıfını ve geçerli proje sürümünü belirler. Ardından kaçış düzeninin değişip değişmediğini, yangın bölmesi sürekliliğini ve tesisat sistemleriyle ilişkisini inceler. Eğer depolanan maddelerin niteliği de değişmişse tehlikeli madde sınıflandırması ayrıca ele alınır.`},{tip:`p`,metin:`Bu tek örnekte mevzuat, proje okuma, yapı/malzeme, elektrik ve mekanik sistemler, tehlikeli maddeler ve raporlama modülleri birlikte kullanılır. Eğitim müfredatının amacı bu bağlantıyı kurmak olmalıdır; her branşın bütün özel hesaplarının aynı kişi tarafından yapılması değildir.`},{tip:`h2`,id:`sik-sorulan-sorular`,metin:`Sık sorulan sorular`},{tip:`h3`,metin:`YGU-K eğitiminde 35 saat doğru mu?`},{tip:`p`,metin:`İncelenen taslak EK-2'nin modül toplamıdır; yayımlanmış nihai eğitim süresi olarak açıklanmamalıdır.`},{tip:`h3`,metin:`YGU-3'ün 40 saati temel eğitim yerine geçer mi?`},{tip:`p`,metin:`Taslakta YGU-3, önceden YGU-2 yeterliliğine bağlı ek seviye olarak düzenlenir.`},{tip:`h3`,metin:`EK-2'de eğitici branşı yazması dış uzman onayı gerektiği anlamına mı gelir?`},{tip:`p`,metin:`Hayır. Eğitici branşı, dersin kim tarafından verilebileceğine ilişkin taslak yeterlilik alanıdır; hazırlanan her eğitim dokümanına bağımsız mühendis veya kimyager imzası aranması anlamına gelmez.`},{tip:`h2`,id:`sonuc`,metin:`Sonuç`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) eğitim müfredatı, seviyeye özel teknik kazanımların tutarlı biçimde bir araya getirilmesini sağlar. EK-2'nin saat toplamları ve modül grupları doğrulandı; yine de bunlar taslak hükümleridir. YGU eğitimi, proje–mevzuat–saha–rapor bağlantısını öğreterek gerçek görevleri karşılayacak biçimde değerlendirilmelidir.`}],kaynakBaslik:`Kaynakça`,kaynaklar:[{metin:`3194 Sayılı İmar Kanunu`},{metin:`Binaların Yangından Korunması Hakkında Yönetmelik`},{metin:`Binaların Yangından Korunması Hakkında Yönetmelik Kılavuzu`},{metin:`Yangın Güvenlik Uzmanlığı ve Periyodik Kontrol Usul ve Esasları Hakkında Yönetmelik Taslağı`}],sss:[{soru:`YGU-K eğitiminde 35 saat doğru mu?`,yanit:`İncelenen taslak EK-2'nin modül toplamıdır; yayımlanmış nihai eğitim süresi olarak açıklanmamalıdır.`},{soru:`YGU-3'ün 40 saati temel eğitim yerine geçer mi?`,yanit:`Taslakta YGU-3, önceden YGU-2 yeterliliğine bağlı ek seviye olarak düzenlenir.`},{soru:`EK-2'de eğitici branşı yazması dış uzman onayı gerektiği anlamına mı gelir?`,yanit:`Hayır. Eğitici branşı, dersin kim tarafından verilebileceğine ilişkin taslak yeterlilik alanıdır; hazırlanan her eğitim dokümanına bağımsız mühendis veya kimyager imzası aranması anlamına gelmez.`}]},{no:`17`,baslik:`Yangın Güvenlik Uzmanı (YGU) Ne İş Yapar? Yangın Güvenlik Uzmanlığı (YGU) Görevleri ve Sorumlulukları`,ozet:`Yangın Güvenlik Uzmanı (YGU) ne iş yapar sorusu, yangın güvenliğine ilişkin bütün projeleri, denetimleri ve bakımları tek kişinin yürüttüğü düşüncesiyle cevaplanmamalıdır. Yangın Güvenlik Uzmanlığı (YGU), kanuni çerçeve ve ilgili uygulama düzenlemesinde tanımlanan işlerde görev yapmayı ifade eder. Yapıların onaylı projeleri, gerçek saha koşulları ve yangından korunma sistemlerine ilişkin teknik kayıtların karşılaştırılması bu uzmanlığın önemli çalışma alanlarıdır.`,bloklar:[{tip:`not`,etiket:`MEVZUAT DURUMU`,metin:`7579 sayılı Kanun'la getirilen yangın güvenliği periyodik kontrol çerçevesi yürürlüktedir. Aşağıdaki dört görev türü ve uzmanlık seviyesi dağılımı, YGU yönetmelik TASLAĞI Madde 6 hükümlerine dayanmaktadır.`},{tip:`h2`,id:`1-proje-uygunluguna-esas-rapor-hazirlama`,metin:`1. Proje uygunluğuna esas rapor hazırlama`},{tip:`p`,metin:`TASLAK Madde 6/1-a, yangın algılama, söndürme ve tahliye projeleri ile yangın tedbirlerinin gösterildiği diğer projelerin ilgili yangın mevzuatına uygunluğuna ilişkin, uygunluk görüşüne esas rapor düzenlenmesini öngörür. Burada YGU'nun işi, proje müellifliği ve bütün teknik onay yetkilerini üstlenmek olarak tanımlanmamıştır.`},{tip:`p`,metin:`Proje incelemesinde hangi düzenlemenin hangi yapı kullanım koşuluna karşılık geldiği belirlenmelidir. Örneğin bir çıkış kapısının planda bulunması, bütün kaçış düzeninin uygun olduğu sonucunu tek başına doğurmaz.`},{tip:`h2`,id:`2-yapi-kullanma-izni-asamasinda-uygunluga-esas-rapor`,metin:`2. Yapı kullanma izni aşamasında uygunluğa esas rapor`},{tip:`p`,metin:`TASLAK Madde 6/1-b, yapı kullanma izin belgesi verilmesi aşamasında projenin sahada nasıl uygulandığının ve sistemlerin test edilip devreye alındığını gösteren belgelerin bulunup bulunmadığının değerlendirilmesini öngörür.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU), proje ile as-built/uygulama kayıtları ve gerçek saha arasındaki farkları tespit edebilir. Bir test raporunu incelemek ile testi bizzat yapmak farklı işlemlerdir. Testin yapıldığı veya geçerli olduğu doğrulanmadıysa rapora “test edildi” sonucu yazılmamalıdır.`},{tip:`h2`,id:`3-yangin-guvenligi-periyodik-kontrolu`,metin:`3. Yangın güvenliği periyodik kontrolü`},{tip:`p`,metin:`TASLAK Madde 6/1-c, 3194 sayılı İmar Kanunu kapsamında kullanıma ilişkin belgeye sahip olup EK-1'de sayılan yapıların periyodik kontrolünü ele alır. Bu kontroller, taslakta ilgili kullanım sınıfına, bina sınırlarına ve YGU seviyesine göre ayrılmıştır.`},{tip:`p`,metin:`Kontrolün başlaması, yapının onaylı projeleri, kullanım izni, varsa tadilat belgeleri, bakım ve test kayıtları gibi kaynakların belirlenmesini gerektirir. Taslak Madde 24 hazırlık, yerinde kontrol ve raporlama aşamalarını düzenlemektedir.`},{tip:`h2`,id:`4-belirli-yangin-tatbikatlarini-birlikte-planlama`,metin:`4. Belirli yangın tatbikatlarını birlikte planlama`},{tip:`p`,metin:`TASLAK Madde 6/1-ç, ilgili Bina Yangın Yönetmeliği hükmünde belirtilen yapıların tatbikatının yapı sahibi, yöneticisi veya görevlendirilen birim amirinin sorumluluğunda birlikte planlanmasını öngörür. Bu, YGU'nun bütün işyerlerinin acil durum yönetiminden tek başına sorumlu olduğu anlamına gelmez.`},{tip:`p`,metin:`Tatbikat planlamasının yeri, amacı ve ilgili görev dağılımı ayrı belirlenmelidir. İşyerinin iş sağlığı ve güvenliği kapsamındaki acil durum yükümlülükleri bu nedenle kendiliğinden ortadan kalkmaz.`},{tip:`h2`,id:`5-hangi-seviyeler-hangi-gorevleri-yurutur`,metin:`5. Hangi seviyeler hangi görevleri yürütür?`},{tip:`p`,metin:`TASLAK Madde 6/2-a, proje uygunluğuna esas rapor, yapı kullanma izni aşamasındaki rapor ve belirli tatbikat planlaması görevlerini YGU-2 veya YGU-3 seviyelerine ayırmaktadır. Madde 6/2-b ise EK-1 sınırları dahilindeki periyodik kontrolleri YGU-1, YGU-2 veya YGU-3 seviyeleriyle ilişkilendirir. YGU-K'nin yüksek tehlikeli yapılarda tehlikeli maddelerin tespiti ve sınıflandırılması bakımından özel görevi vardır.`},{tip:`p`,metin:`Yalnızca bir yetki belgesine sahip olmak, mahalli itfaiye teşkilatının kanuni rolü ve görevlendirme koşulları olmadan sınırsız resmî kontrol yetkisi vermez.`},{tip:`h2`,id:`6-ygu-nun-bagimsizligi-ve-kayit-sorumlulugu`,metin:`6. YGU'nun bağımsızlığı ve kayıt sorumluluğu`},{tip:`p`,metin:`TASLAK Madde 8, tarafsızlık, bağımsızlık, çıkar çatışmasından kaçınma, bilgilerin gizliliği ve görevi bizzat yürütme konusunda ayrıntılı hükümler içerir. Bu hükümler nihai metinle doğrulanmadan yürürlükteymiş gibi sunulmamalıdır; ancak objektif teknik raporlama açısından önemlidir.`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU), incelemediği belgeyi incelemiş, yapılmayan testi yapılmış veya sahada görülmeyen bir uygulamayı doğrulanmış gibi gösteremez. Bulgunun dayanağı, belirsizliği ve gerekiyorsa ek inceleme ihtiyacı açıkça belirtilmelidir.`},{tip:`h2`,id:`7-saha-ornegi-projeden-gercege-kontrol-zinciri`,metin:`7. Saha örneği: projeden gerçeğe kontrol zinciri`},{tip:`p`,metin:`Bir hastane binasının onaylı projesinde yangın bölmesi olarak ayrılmış alanda sonradan tesisat geçişi açılmış olsun. Yangın Güvenlik Uzmanı (YGU), önce geçerli projenin hangisi olduğunu, değişikliğin onaylanıp onaylanmadığını ve sahadaki gerçek durumu belirler. Geçişin yangın bölmesinin sürekliliği bakımından anlamı, uygulanabilir mevzuat ve teknik belgeler üzerinden değerlendirilir.`},{tip:`p`,metin:`Uygunsuzluk tespit edilirse mahal, belge ve mevzuat ilişkisiyle gerekçelendirilir. Ancak YGU'nun bu görevi, eksik tasarımın yeniden çizilmesi, test raporunun üretilmesi veya başka mesleklerin özel hesaplarının otomatik olarak yapılması anlamına gelmez.`},{tip:`h2`,id:`sik-sorulan-sorular`,metin:`Sık sorulan sorular`},{tip:`h3`,metin:`YGU her binada kontrol yapabilir mi?`},{tip:`p`,metin:`Hayır; görevlendirme, yapı sınıfı ve uzmanlık seviyesi dikkate alınmalıdır.`},{tip:`h3`,metin:`YGU bütün yangın projelerini onaylar mı?`},{tip:`p`,metin:`Taslak, uygunluk görüşüne esas raporlamayı düzenler; bütün proje müellifliği veya onay yetkisi değildir.`},{tip:`h3`,metin:`YGU bakım yapar mı?`},{tip:`p`,metin:`Resmî yangın güvenliği kontrolü ile sistemlerin periyodik bakım/test yükümlülükleri aynı işlem değildir.`},{tip:`h2`,id:`sonuc`,metin:`Sonuç`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) görevleri, taslakta dört ayrı iş türü altında düzenlenmiştir. Her görevde proje, saha, teknik kanıt ve mevzuat arasındaki ilişki kurulmalı; uzmanlık seviyesi ile yetki sınırları açık tutulmalıdır.`}],kaynakBaslik:`Kaynakça`,kaynaklar:[{metin:`3194 Sayılı İmar Kanunu`},{metin:`Binaların Yangından Korunması Hakkında Yönetmelik`},{metin:`Binaların Yangından Korunması Hakkında Yönetmelik Kılavuzu`},{metin:`Yangın Güvenlik Uzmanlığı ve Periyodik Kontrol Usul ve Esasları Hakkında Yönetmelik Taslağı`}],sss:[{soru:`YGU her binada kontrol yapabilir mi?`,yanit:`Hayır; görevlendirme, yapı sınıfı ve uzmanlık seviyesi dikkate alınmalıdır.`},{soru:`YGU bütün yangın projelerini onaylar mı?`,yanit:`Taslak, uygunluk görüşüne esas raporlamayı düzenler; bütün proje müellifliği veya onay yetkisi değildir.`},{soru:`YGU bakım yapar mı?`,yanit:`Resmî yangın güvenliği kontrolü ile sistemlerin periyodik bakım/test yükümlülükleri aynı işlem değildir.`}]},{no:`18`,baslik:`Yangın Güvenlik Uzmanlığı (YGU) ile İş Güvenliği Uzmanlığı Arasındaki Farklar Nelerdir?`,ozet:`Yangın Güvenlik Uzmanlığı (YGU) ile iş güvenliği uzmanlığı benzer yangın tehlikeleri üzerinde çalışabilse de amaçları, mevzuatları ve resmî yetkilendirme süreçleri aynı değildir. Bir işyerindeki yangın riski hem çalışanların güvenliği hem de yapının yangından korunma koşulları açısından değerlendirilebilir; ancak bu iki değerlendirmenin belge türleri ve görev sınırları birbirine karıştırılmamalıdır.`,bloklar:[{tip:`h2`,id:`1-is-guvenligi-uzmanliginin-bakis-acisi`,metin:`1. İş güvenliği uzmanlığının bakış açısı`},{tip:`p`,metin:`İş güvenliği uzmanı, işyerindeki tehlikelerin belirlenmesi, risk değerlendirmesi, önleyici faaliyetlerin planlanması ve acil durum hazırlıklarına ilişkin görevleri kendi mevzuatı kapsamında yürütür. Sıcak çalışma, elektrik tesisatındaki riskler, yanıcı maddelerin depolanması veya kaçış yollarının engellenmesi, iş sağlığı ve güvenliği açısından da incelenebilir.`},{tip:`p`,metin:`Ancak bir risk değerlendirmesinde yangın tehlikesinin bulunması, yapının yangın güvenliği periyodik kontrolünün mevzuata uygun tamamlandığını tek başına göstermez.`},{tip:`h2`,id:`2-yangin-guvenlik-uzmaninin-ygu-bakis-acisi`,metin:`2. Yangın Güvenlik Uzmanının (YGU) bakış açısı`},{tip:`p`,metin:`22 Mayıs 2026 tarihli kanuni düzenleme, kullanıma yönelik belgeye sahip yapılarda yangın güvenliği periyodik kontrolleri ve raporlama bakımından ayrı bir çerçeve oluşturmuştur. Yangın Güvenlik Uzmanı (YGU) bu alandaki resmî görevleri, mevzuatta öngörülen yetkilendirme ve görevlendirme koşullarına göre üstlenebilir.`},{tip:`p`,metin:`TASLAK Madde 6, ayrıca proje uygunluğuna esas raporlama, yapı kullanma izni aşamasındaki uygunluk incelemesi ve belirli tatbikatların birlikte planlanması görevlerini de düzenlemektedir. Bunların tümü iş güvenliği uzmanının mevcut belgesinden otomatik olarak doğmaz.`},{tip:`h2`,id:`3-risk-degerlendirmesi-ve-yangin-guvenlik-raporu-neden-farklidir`,metin:`3. Risk değerlendirmesi ve yangın güvenlik raporu neden farklıdır?`},{tip:`p`,metin:`İSG risk değerlendirmesi, işyerindeki tehlikeleri ve bunlardan kaynaklanan riskleri ele alır. Yangın güvenlik raporu ise yapıdaki yangından korunma tedbirlerinin ilgili kontrol sistemi kapsamında belgelenmesiyle ilişkilidir.`},{tip:`p`,metin:`Örneğin çıkış koridoruna depolama malzemesi konulması işyerinde çalışan güvenliği bakımından bir tehlikedir. Yangın Güvenlik Uzmanı (YGU) aynı durumu incelerken geçerli onaylı proje, kaçış düzeni, yapı kullanım sınıfı ve uygulanabilir mevzuatla ilişki kurar. İki yaklaşım birbirini destekleyebilir, ancak tek belgeyle birbirinin yerine geçtiği varsayılamaz.`},{tip:`h2`,id:`4-ayni-kisi-iki-ayri-yetkiye-sahip-olabilir-mi`,metin:`4. Aynı kişi iki ayrı yetkiye sahip olabilir mi?`},{tip:`p`,metin:`İş güvenliği uzmanlığı belgesi ile YGU yetki belgesi farklı sistemlerdir. TASLAK Madde 5, YGU için meslek ve öğrenim alanlarını belirler; YGU-3 için ayrıca önceki yetki ve rapor deneyimi öngörür. A, B veya C sınıfı iş güvenliği uzmanlığı belgesi tek başına bu koşulları değiştirmez.`},{tip:`p`,metin:`Öte yandan kişinin hem iş güvenliği hem yangın güvenliği alanında mesleki yeterliliği bulunabilir. Bu durumda her iki görevin kendi mevzuatına, bağımsızlık ve çıkar çatışması kurallarına göre yürütülmesi gerekir. Taslak Madde 8'de belirli proje ve yapılarda görev alınamayacak durumlar ayrıca öngörülmüştür.`},{tip:`h2`,id:`5-isg-acil-durum-plani-ile-ygu-tatbikat-gorevi-ayni-mi`,metin:`5. İSG acil durum planı ile YGU tatbikat görevi aynı mı?`},{tip:`p`,metin:`İşyerinin acil durum planı, çalışanların güvenliği ve acil durumda yapılacak düzenlemelerle ilgilidir. TASLAK Madde 6/1-ç, belirli yapıların tatbikatlarının sorumlu yapı yöneticisi veya görevli birim amiriyle birlikte planlanmasına ilişkin YGU rolü öngörür.`},{tip:`p`,metin:`Bu özel YGU görevi, her işyerindeki acil durum planının bütünüyle Yangın Güvenlik Uzmanına devredildiği anlamına gelmez. İşverenin ve yapı sahibinin diğer yükümlülükleri devam eder.`},{tip:`h2`,id:`6-temel-farklar-tablosu`,metin:`6. Temel farklar tablosu`},{tip:`tablo`,basliklar:[`Karşılaştırma`,`İş güvenliği uzmanlığı`,`Yangın Güvenlik Uzmanlığı (YGU)`],satirlar:[[`Temel amaç`,`İşyerindeki İSG risklerinin yönetimine katkı`,`Mevzuatla tanımlanan yapı yangın güvenliği değerlendirmesi`],[`Mevzuat ekseni`,`6331 sayılı Kanun ve ilgili düzenlemeler`,`3194 sayılı Kanun, BYKHY ve YGU uygulama düzeni`],[`Temel belge`,`Risk değerlendirmesi, İSG kayıtları ve ilgili çalışmalar`,`Yetki kapsamındaki yangın güvenlik raporu ve uygunluk işlemleri`],[`Mesleki yetki`,`İSG uzmanlık belgesi`,`Ayrı YGU eğitimi, sınavı ve yetkilendirmesi`],[`YGU görevleriyle ilişki`,`Kendiliğinden YGU yetkisi oluşturmaz`,`Kendiliğinden İSG uzmanlığı yetkisi oluşturmaz`]]},{tip:`p`,metin:`Bu tablo iki mesleğin tüm görevlerini saymaz; temel ayrımı göstermek için hazırlanmıştır.`},{tip:`h2`,id:`7-saha-ornegi-uretim-hatti-degisikligi`,metin:`7. Saha örneği: üretim hattı değişikliği`},{tip:`p`,metin:`Bir fabrikada üretim alanının yerleşimi değişsin. İş güvenliği uzmanı çalışanların risklerini, acil durum erişimini ve ilgili iş ekipmanı etkilerini değerlendirebilir. Yangın Güvenlik Uzmanı (YGU), kendi görevlendirmesi kapsamında değişikliğin yapı kullanım sınıfına, yangın bölmelerine, kaçış düzenine ve yangından korunma sistemlerine etkisini projeyle karşılaştırabilir.`},{tip:`p`,metin:`İki çalışma arasında teknik bilgi paylaşımı olabilir; ancak hazırlanan raporların kapsamları ve mevzuat dayanakları ayrı tutulmalıdır. Görülmeyen bir testin gerçekleştiği veya onaylanmamış bir tadilatın onaylı olduğu varsayılmamalıdır.`},{tip:`h2`,id:`sik-sorulan-sorular`,metin:`Sık sorulan sorular`},{tip:`h3`,metin:`A sınıfı İSG uzmanı doğrudan YGU olabilir mi?`},{tip:`p`,metin:`Hayır; temel öğrenim, eğitim, sınav ve ayrı yetkilendirme koşulları vardır.`},{tip:`h3`,metin:`YGU, İSG risk değerlendirmesini de yapar mı?`},{tip:`p`,metin:`YGU yetki belgesi tek başına İSG uzmanlığı yetkisi sağlamaz.`},{tip:`h3`,metin:`Yangın güvenlik raporu acil durum planının yerine geçer mi?`},{tip:`p`,metin:`Hayır; farklı amaç ve işlem türleridir.`},{tip:`h2`,id:`sonuc`,metin:`Sonuç`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) ile iş güvenliği uzmanlığı ortak teknik konuları paylaşır, ancak aynı uzmanlık veya raporlama sistemi değildir. İki alandaki yetkinliklerin işyerinde tutarlı biçimde kullanılması yararlıdır; yetki ve sorumluluklar ayrı tutulmalıdır.`}],kaynakBaslik:`Kaynakça`,kaynaklar:[{metin:`6331 Sayılı İş Sağlığı ve Güvenliği Kanunu`},{metin:`İş Güvenliği Uzmanlarının Görev, Yetki, Sorumluluk ve Eğitimleri Hakkında Yönetmelik`},{metin:`İşyerlerinde Acil Durumlar Hakkında Yönetmelik`},{metin:`3194 Sayılı İmar Kanunu`},{metin:`Binaların Yangından Korunması Hakkında Yönetmelik`},{metin:`Yangın Güvenlik Uzmanlığı ve Periyodik Kontrol Usul ve Esasları Hakkında Yönetmelik Taslağı`}],sss:[{soru:`A sınıfı İSG uzmanı doğrudan YGU olabilir mi?`,yanit:`Hayır; temel öğrenim, eğitim, sınav ve ayrı yetkilendirme koşulları vardır.`},{soru:`YGU, İSG risk değerlendirmesini de yapar mı?`,yanit:`YGU yetki belgesi tek başına İSG uzmanlığı yetkisi sağlamaz.`},{soru:`Yangın güvenlik raporu acil durum planının yerine geçer mi?`,yanit:`Hayır; farklı amaç ve işlem türleridir.`}]},{no:`19`,baslik:`Yangın Güvenlik Uzmanı (YGU) Hangi Binalarda Görev Alabilir? Yangın Güvenlik Uzmanlığı (YGU) Yetki Kapsamı`,ozet:`Yangın Güvenlik Uzmanı (YGU) hangi binalarda görev alabilir sorusu, uzmanlık seviyesinin adından daha ayrıntılı bir inceleme gerektirir. Bir yapının kullanım sınıfı, yapı yüksekliği veya inşaat alanı gibi sınırları, tehlike düzeyi, karma kullanım durumu ve yapılacak işin türü birlikte değerlendirilmelidir. Ayrıca resmî kontrol görevlendirmesi bakımından mahalli itfaiye teşkilatının kanuni rolü gözden kaçırılmamalıdır.`,bloklar:[{tip:`not`,etiket:`MEVZUAT DURUMU`,metin:`7579 sayılı Kanun'la 3194 sayılı İmar Kanunu'na eklenen periyodik kontrol çerçevesi yürürlüktedir. Aşağıdaki 3–5 yıllık periyotlar, bina sınırları ve YGU-1/2/3/K ayrımları ise incelenen YGU yönetmelik taslağının EK-1'ine dayanmaktadır; kesinleşmiş kontrol takvimi veya yetki belgesi kapsamı değildir.`},{tip:`h2`,id:`1-yangin-guvenlik-uzmanligi-ygu-yetkisi-otomatik-olarak-her-binayi-kapsar-mi`,metin:`1. Yangın Güvenlik Uzmanlığı (YGU) yetkisi otomatik olarak her binayı kapsar mı?`},{tip:`p`,metin:`Hayır. Kanuni çerçevede yangın güvenliği periyodik kontrolleri belediyelerin ilgili itfaiye teşkilatı tarafından veya itfaiyenin gerekli gördüğü durumlarda, öngörülen eğitim ve sınavı tamamlayarak yetkilendirilmiş yangın güvenlik uzmanları tarafından yapılabilir. Yangın Güvenlik Uzmanı (YGU) olmak, tek başına her yapıya gidip resmî yangın güvenlik raporu düzenleme hakkının sınırsız bulunduğu anlamına gelmez.`},{tip:`p`,metin:`Taslak Madde 6, görev türlerini ve seviyelerini ayırır. Proje uygunluk görüşüne esas rapor, yapı kullanma izni aşamasındaki rapor ve belirli tatbikatların birlikte planlanması YGU-2/YGU-3 için öngörülürken, periyodik kontrol görevi EK-1 kapsamında YGU-1/YGU-2/YGU-3 seviyeleriyle ilişkilendirilmiştir. YGU-K'nin yüksek tehlikeli yapılarda tehlikeli maddelerin tespiti ve sınıflandırmasına yönelik özel rolü ayrıca düzenlenmiştir.`},{tip:`h2`,id:`2-ek-1-de-konutlar-icin-hangi-sinirlar-var`,metin:`2. EK-1'de konutlar için hangi sınırlar var?`},{tip:`not`,etiket:`TASLAK EK-1`,metin:`Konutlarda yapı yüksekliği 30,50 metre dahil ile 51,50 metre arası için beş yıllık kontrol aralığı ve YGU-1/YGU-2/YGU-3; 51,50 metre ve üstü için dört yıllık kontrol aralığı ve YGU-2/YGU-3 seviyeleri yazılmıştır.`},{tip:`p`,metin:`İlk aralıktaki “51,50 m arası” ifadesiyle ikinci satırdaki “51,50 m ve üstü” ifadesi sınırda çakışma doğurabilecek şekilde okunabilir. Bu nedenle tam 51,50 metrelik bir yapıya ilişkin yorumda taslak ifadenin açıklaştırılması gereği not edilmelidir; tutarsızlığı yok sayarak kesin yetki sonucu çıkarılmamalıdır.`},{tip:`h2`,id:`3-konaklama-kurumsal-buro-ve-ticari-binalarda-nasil-farklilasiyor`,metin:`3. Konaklama, kurumsal, büro ve ticari binalarda nasıl farklılaşıyor?`},{tip:`p`,metin:`TASLAK EK-1 konaklama yapılarında yatılan oda sayısı 25 ve altında olduğunda beş yıllık periyot ve YGU-1/2/3; 25'in üstünde olduğunda dört yıllık periyot ve YGU-2/3 öngörür.`},{tip:`p`,metin:`Kurumsal, büro ve ticari amaçlı binalarda yapı inşaat alanı 1.000 m² ve altında olduğunda beş yıl ve YGU-1/2/3; alan 1.000 m²'nin üstünde olduğunda dört yıl ve YGU-2/3 seviyesi yer alır. Bu nedenle yalnızca binanın kat sayısına veya adının “iş merkezi” olmasına bakarak yetkili uzman seviyesi belirlenemez.`},{tip:`h2`,id:`4-endustriyel-ve-depolama-tesislerinde-tehlike-duzeyi-neden-belirleyicidir`,metin:`4. Endüstriyel ve depolama tesislerinde tehlike düzeyi neden belirleyicidir?`},{tip:`p`,metin:`TASLAK EK-1 endüstriyel tesisleri ve depolama amaçlı tesisleri yüksek, orta ve düşük tehlikeli yapı gruplarında ele alır. Yüksek tehlikeli endüstriyel tesis için üç yıl ve YGU-3 ile YGU-K; orta tehlikeli tesis için dört yıl ve YGU-2/YGU-3; düşük tehlikeli tesis için beş yıl ve YGU-1/2/3 düzenlemesi bulunur.`},{tip:`p`,metin:`Depolama amaçlı tesislerin yüksek tehlikeli satırında aynı üç yıllık periyot vardır; ancak incelenen kaynak tabloda “YGU-3 ve YGU-4” yazmaktadır. Bu ibare, Madde 5'te tanımlanan dört seviyeden biri değildir. Başka yüksek tehlikeli satırlarda YGU-K kullanılması, bunun yazım hatası olabileceğini düşündürür; fakat resmî düzeltme olmadığı için metin sessizce “YGU-K”ye çevrilerek kesin hüküm gibi aktarılamaz.`},{tip:`h2`,id:`5-toplanma-amacli-binalar-ve-yuksek-tehlikeli-yerler`,metin:`5. Toplanma amaçlı binalar ve yüksek tehlikeli yerler`},{tip:`not`,etiket:`TASLAK EK-1`,metin:`Toplanma amaçlı binalarda 1.000 m² ve altı için beş yıl ve YGU-1/2/3; 1.000 m² üstü için dört yıl ve YGU-2/3 satırları bulunmaktadır. “Yüksek Tehlikeli Yerler” için ise sınır olmaksızın üç yıl, YGU-3 ve YGU-K yazılıdır.`},{tip:`p`,metin:`Yapının gerçek kullanımının belirlenmesi bu noktada önemlidir. Örneğin bir yapının idari bina olarak adlandırılması, içinde bağımsız bir toplanma işlevi veya farklı tehlike düzeyinde bir kullanım bölümü bulunmadığı anlamına gelmez.`},{tip:`h2`,id:`6-ek-1-e-gore-ozet-yapi-periyot-yetki-tablosu`,metin:`6. EK-1'e göre özet yapı–periyot–yetki tablosu`},{tip:`tablo`,basliklar:[`Kullanım sınıfı / sınır (TASLAK)`,`Kontrol periyodu`,`Uzmanlık seviyesi (kaynakta)`],satirlar:[[`Konut 30,50 m dahil – 51,50 m arası`,`5 yıl`,`YGU-1 veya YGU-2 veya YGU-3`],[`Konut 51,50 m ve üstü`,`4 yıl`,`YGU-2 veya YGU-3`],[`Konaklama, yatılan oda 25 ve altı`,`5 yıl`,`YGU-1 veya YGU-2 veya YGU-3`],[`Konaklama, yatılan oda 25'in üstü`,`4 yıl`,`YGU-2 veya YGU-3`],[`Kurumsal / büro / ticari, 1.000 m² ve altı`,`5 yıl`,`YGU-1 veya YGU-2 veya YGU-3`],[`Kurumsal / büro / ticari, 1.000 m² üstü`,`4 yıl`,`YGU-2 veya YGU-3`],[`Endüstriyel, yüksek tehlikeli`,`3 yıl`,`YGU-3 ve YGU-K`],[`Endüstriyel, orta tehlikeli`,`4 yıl`,`YGU-2 veya YGU-3`],[`Endüstriyel, düşük tehlikeli`,`5 yıl`,`YGU-1 veya YGU-2 veya YGU-3`],[`Toplanma, 1.000 m² ve altı`,`5 yıl`,`YGU-1 veya YGU-2 veya YGU-3`],[`Toplanma, 1.000 m² üstü`,`4 yıl`,`YGU-2 veya YGU-3`],[`Depolama, yüksek tehlikeli`,`3 yıl`,`YGU-3 ve YGU-4 (kaynakta tutarsız ifade)`],[`Depolama, orta tehlikeli`,`4 yıl`,`YGU-2 veya YGU-3`],[`Depolama, düşük tehlikeli`,`5 yıl`,`YGU-1 veya YGU-2 veya YGU-3`],[`Yüksek tehlikeli yer, sınırsız`,`3 yıl`,`YGU-3 ve YGU-K`]]},{tip:`p`,metin:`Karma kullanım sınıfına ilişkin EK-1 notunda, kontrol periyodu düşük olan kullanım sınıfının uygulanması öngörülür. Ancak her karma yapının hangi kullanımlara ayrılacağı ve hangi yapı parçalarının birlikte ele alınacağı, onaylı projeler ve gerçek kullanım üzerinden belirlenmelidir.`},{tip:`h2`,id:`7-yeni-ve-mevcut-binalarda-mevzuat-nasil-secilir`,metin:`7. Yeni ve mevcut binalarda mevzuat nasıl seçilir?`},{tip:`p`,metin:`Yangın Güvenlik Uzmanı (YGU) incelemesinde yapının inşaat veya kullanım izni tarihi tek başına yeterli olmayabilir. Yapının ruhsatı, yapı kullanma izni, onaylı projeleri, varsa tadilatları ve kullanım değişiklikleri incelenmelidir.`},{tip:`p`,metin:`Yürürlükteki Binaların Yangından Korunması Hakkında Yönetmelik (BYKHY) ile yeni BYKHY değişiklik taslağı birbirine karıştırılmamalıdır. İncelenen YGU taslağı bazı yerlerde “Bina Yangın Yönetmeliği (BYY)” ve henüz kesinleşmemiş madde numaraları kullanmaktadır. Bu ifadelerin yürürlükteki BYKHY hükümleri olduğu varsayılamaz.`},{tip:`h2`,id:`8-periyodik-kontrol-ile-diger-ygu-gorevleri-ayni-mi`,metin:`8. Periyodik kontrol ile diğer YGU görevleri aynı mı?`},{tip:`p`,metin:`Hayır. TASLAK Madde 6 birbirinden farklı dört görev öngörür: uygunluk görüşüne esas proje raporu; yapı kullanma izni aşamasında uygunluk görüşüne esas rapor; EK-1'e giren yapılarda periyodik kontrol; belirli yapılarda tatbikatın birlikte planlanması. YGU seviyesinin bu iş türlerine ilişkin sınırları farklıdır.`},{tip:`p`,metin:`Örneğin EK-1'de YGU-1'in periyodik kontrol yapabileceği bir yapı satırının bulunması, aynı kişi için proje uygunluk görüşüne esas rapor hazırlama yetkisinin de bulunduğu anlamına gelmez.`},{tip:`h2`,id:`9-saha-ornegi-ticaret-depo-buro`,metin:`9. Saha örneği: ticaret + depo + büro`},{tip:`p`,metin:`Bir tesiste ticari satış alanı, ayrı bir büro bloğu ve kimyasal madde deposu birlikte bulunsun. Yangın Güvenlik Uzmanı (YGU), önce onaylı projelerdeki kullanım sınıflarını ve gerçek işletme faaliyetlerini karşılaştırır. Ardından her bölümün ayrı yapı mı, karma kullanım parçası mı olduğunu ve EK-1'de hangi sınırlara karşılık geldiğini belirler.`},{tip:`p`,metin:`Yapı sahibinin bildirdiği alan, kat sayısı veya tehlike düzeyi doğrulanmadan uygun seviye seçilemez. Yangın bölmeleri, kaçış düzeni, depolanan maddeler ve ilgili teknik kayıtlar tespit edilir; gerekçeli teknik değerlendirme bu kanıt zinciriyle oluşturulur.`},{tip:`h2`,id:`sik-sorulan-sorular`,metin:`Sık sorulan sorular`},{tip:`h3`,metin:`Her konut YGU periyodik kontrolüne giriyor mu?`},{tip:`p`,metin:`Taslak EK-1'de belirli yapı yüksekliği sınırları bulunmaktadır; bütün konutlar için otomatik aynı cevap verilemez.`},{tip:`h3`,metin:`Bütün fabrikaları YGU-1 kontrol edebilir mi?`},{tip:`p`,metin:`Hayır. Endüstriyel tesisin tehlike düzeyine göre taslakta farklı uzmanlık seviyeleri düzenlenmiştir.`},{tip:`h3`,metin:`YGU-K yüksek tehlikeli yerlerde tek başına bütün görevleri üstlenir mi?`},{tip:`p`,metin:`Taslakta YGU-K tehlikeli maddelerin tespiti ve sınıflandırılması bakımından özel görev sahibidir; genel kontrol uzmanlığıyla aynı değildir.`},{tip:`h3`,metin:`YGU-4 diye bir seviye var mı?`},{tip:`p`,metin:`Taslak Madde 5'te yoktur. EK-1'in tek satırındaki bu ifade kaynak içi tutarsızlık olarak işaretlenmelidir.`},{tip:`h2`,id:`sonuc`,metin:`Sonuç`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) yetkisi, yapı kullanım sınıfı, ilgili sınır, tehlike düzeyi, yapılacak işlemin türü ve itfaiye teşkilatının kanuni rolü birlikte değerlendirilmeden belirlenemez. EK-1 ayrıntılı yol gösterse de mevcut metin taslaktır ve içinde açıklaştırılması gereken sınır ve seviye ifadeleri bulunmaktadır.`}],kaynakBaslik:`Kaynakça`,kaynaklar:[{metin:`3194 Sayılı İmar Kanunu`},{metin:`Binaların Yangından Korunması Hakkında Yönetmelik`},{metin:`Binaların Yangından Korunması Hakkında Yönetmelik Kılavuzu`},{metin:`Yangın Güvenlik Uzmanlığı ve Periyodik Kontrol Usul ve Esasları Hakkında Yönetmelik Taslağı`}],sss:[{soru:`Her konut YGU periyodik kontrolüne giriyor mu?`,yanit:`Taslak EK-1'de belirli yapı yüksekliği sınırları bulunmaktadır; bütün konutlar için otomatik aynı cevap verilemez.`},{soru:`Bütün fabrikaları YGU-1 kontrol edebilir mi?`,yanit:`Hayır. Endüstriyel tesisin tehlike düzeyine göre taslakta farklı uzmanlık seviyeleri düzenlenmiştir.`},{soru:`YGU-K yüksek tehlikeli yerlerde tek başına bütün görevleri üstlenir mi?`,yanit:`Taslakta YGU-K tehlikeli maddelerin tespiti ve sınıflandırılması bakımından özel görev sahibidir; genel kontrol uzmanlığıyla aynı değildir.`},{soru:`YGU-4 diye bir seviye var mı?`,yanit:`Taslak Madde 5'te yoktur. EK-1'in tek satırındaki bu ifade kaynak içi tutarsızlık olarak işaretlenmelidir.`}]},{no:`20`,baslik:`Yangın Güvenlik Uzmanlığı (YGU) Mesleğinin Geleceği: Eğitim, İş İmkanları ve Çalışma Alanları`,ozet:`Yangın Güvenlik Uzmanlığı (YGU) mesleğinin geleceği, yalnızca kaç kişinin yeni bir yetki belgesi alacağıyla açıklanamaz. Yapıların yangın güvenliğine ilişkin periyodik kontrol ihtiyacının nasıl uygulanacağı, mahalli itfaiye teşkilatlarının rolü, eğitim ve sınav sisteminin ne zaman işler hale geleceği ve yapı sahiplerinin teknik belge düzeni, bu alanın gelişimini etkileyecektir.`,bloklar:[{tip:`p`,metin:`Bu nedenle yangın güvenlik uzmanı olmak isteyen kişilere iş garantisi, sabit kazanç veya bütün işletmelerde zorunlu kadro gibi doğrulanmamış vaatlerde bulunmak yerine, kanuni çerçeve, taslak uygulama modeli ve olası mesleki gelişme alanları ayrı değerlendirilmelidir.`},{tip:`h2`,id:`1-ygu-mesleginin-kanuni-zemini-ne-durumda`,metin:`1. YGU mesleğinin kanuni zemini ne durumda?`},{tip:`p`,metin:`22 Mayıs 2026 tarihinde yayımlanan 7579 sayılı Kanun, 3194 sayılı İmar Kanunu'na kullanıma yönelik belgeye sahip yapılarda yangın güvenliği periyodik kontrolü ve yangın güvenlik raporuna ilişkin hükümler getirmiştir. Kanuni sistemde mahalli itfaiye teşkilatının kontrol görevi ve gerekli gördüğü durumlarda eğitim/sınavla yetkilendirilmiş Yangın Güvenlik Uzmanlarının (YGU) görev alabilmesi düzenlenmiştir.`},{tip:`p`,metin:`Kontrole tabi yapılar, periyotlar ve uzmanların nitelikleri gibi ayrıntılar ikincil düzenlemeye bırakılmıştır. Temmuz 2026'da görüşe açılan YGU yönetmelik taslağının varlığı, bütün bu ayrıntıların yürürlükteki kesin kurallar haline geldiği anlamına gelmez.`},{tip:`h2`,id:`2-yangin-guvenlik-uzmanligi-ygu-icin-talep-hangi-kosullarda-olusabilir`,metin:`2. Yangın Güvenlik Uzmanlığı (YGU) için talep hangi koşullarda oluşabilir?`},{tip:`p`,metin:`Yapılar kullanım ömürleri boyunca değişir. Bir fabrika üretim hattını yenileyebilir, bir depo yeni tür maddeler depolayabilir, bir otel tadilat yapabilir veya büro alanları farklı kullanım amaçlarına dönüştürülebilir. Yangın güvenliğinin yalnız inşa aşamasında değil, kullanım süresince de değerlendirilmesi teknik açıdan önemlidir.`},{tip:`p`,metin:`Ancak bir bölgede çok sayıda tesis bulunması, o bölgedeki bütün işletmelerin sürekli YGU çalıştıracağı anlamına gelmez. Fiili hizmet talebi, yönetmeliğin son hali, görevlendirme modeli, itfaiye kapasitesi, ilk kontrol dönemleri ve gerçek başvurulara göre oluşacaktır.`},{tip:`h2`,id:`3-ygu-1-ygu-2-ygu-3-ve-ygu-k-is-alanlarini-nasil-farklilastirabilir`,metin:`3. YGU-1, YGU-2, YGU-3 ve YGU-K iş alanlarını nasıl farklılaştırabilir?`},{tip:`p`,metin:`TASLAK Madde 5, belirli mesleki öğrenim gruplarına bağlı dört uzmanlık seviyesi öngörür. Madde 6, uygunluk görüşüne esas raporlar, yapı kullanma izni aşaması, periyodik kontrol ve belirli tatbikatların birlikte planlanması gibi görevleri ayırır. EK-1, yapı kullanım sınıfı/sınırına göre farklı yetki seviyeleri gösterir.`},{tip:`p`,metin:`YGU-K'nin yüksek tehlikeli yapılarda tehlikeli maddelerin tespiti ve sınıflandırılmasındaki özel rolü, genel bina kontrol görevleriyle karıştırılmamalıdır. Bu ayrım, ileride farklı teknik bilgi birikimlerine dayalı iş bölümü oluşabileceğini düşündürür; ancak kesin istihdam büyüklüğünü göstermez.`},{tip:`h2`,id:`4-egitim-sistemi-mesleki-kaliteyi-nasil-etkileyebilir`,metin:`4. Eğitim sistemi mesleki kaliteyi nasıl etkileyebilir?`},{tip:`p`,metin:`TASLAK Madde 9, teorik ve uygulama eğitimini ayrı düzenlemektedir. Teorik eğitim Bakanlık veya yetkilendirilmiş eğitici kuruluş, uygulama eğitimi ise mahalli itfaiye teşkilatı tarafından verilebilecektir. Taslak EK-2, seviyelere göre 65, 85, 40 ek ve 35 saatlik teorik eğitim toplamları öngörür.`},{tip:`p`,metin:`YGU eğitiminde gerçek kazanım, projenin ne gösterdiğini, sahada ne bulunduğunu, hangi belgeye güvenilebileceğini ve hangi mevzuat hükmünün uygulanacağını birlikte değerlendirebilmektir. Yalnızca sertifika sayısının artması, bu becerilerin yeterince geliştiğini tek başına kanıtlamaz.`},{tip:`h2`,id:`5-dijitallesme-ygu-calismalarini-nasil-degistirebilir`,metin:`5. Dijitalleşme YGU çalışmalarını nasıl değiştirebilir?`},{tip:`p`,metin:`Yangın güvenliği kontrollerinde onaylı projeler, kullanım ve tadilat izinleri, test ve bakım kayıtları, önceki raporlar, fotoğraflar ve sahadaki değişiklikler arasında veri ilişkisi kurmak gerekir. Dijital doküman yönetimi, yapı modellemesi ve kontrol kayıtlarının izlenebilirliği bu süreçleri kolaylaştırabilir.`},{tip:`p`,metin:`Örneğin önceki kontrolde belirlenen bir yangın bölmesi açıklığının kapatılıp kapatılmadığı, eski ve yeni kanıtların ilişkilendirilmesiyle daha güvenilir takip edilebilir. Ancak yazılımın bir kural hakkında öneri üretmesi, Yangın Güvenlik Uzmanının (YGU) resmî karar sorumluluğunun otomatik olarak yazılıma geçtiği anlamına gelmez.`},{tip:`h2`,id:`6-genel-yangin-danismanligi-ile-resmi-ygu-kontrolu-ayni-pazar-mi`,metin:`6. Genel yangın danışmanlığı ile resmî YGU kontrolü aynı pazar mı?`},{tip:`p`,metin:`İşletmeler mevzuat danışmanlığı, proje inceleme, yangından korunma sistemlerinin teknik değerlendirmesi ve bakım/test organizasyonu gibi farklı hizmetlere ihtiyaç duyabilir. Bununla birlikte genel danışmanlık hizmeti, YGU yetki belgesi ve itfaiye görevlendirmesi gerektiren resmî kontrollerle aynı işlem olarak pazarlanmamalıdır.`},{tip:`p`,metin:`Tasarım, montaj, malzeme tedariki, bakım ve kontrol faaliyetlerinde görev ayrımı önemlidir. TASLAK Madde 8, aynı projede belirli ticari faaliyetleri yürüten kişilerin resmî YGU görevinde bulunmasına ilişkin çıkar çatışması sınırlamaları öngörmektedir. Bu durum mesleğin geleceğinde güvenilirlik ve bağımsızlık tartışmalarının önemli olabileceğini göstermektedir.`},{tip:`h2`,id:`7-saha-ornegi-degisen-bir-endustriyel-tesis`,metin:`7. Saha örneği: değişen bir endüstriyel tesis`},{tip:`p`,metin:`Bir organize sanayi bölgesindeki tesiste üretim ve depolama düzeni yıllar içinde değişmiş olsun. Yangın Güvenlik Uzmanı (YGU), yetki ve görevlendirme koşulları dahilinde geçerli onaylı projeleri, izin geçmişini ve gerçek kullanım düzenini karşılaştırır. Depolanan maddeler değişmişse tehlike sınıflandırması, sistemlerin koruma alanları ve kaçış koşulları ayrıca değerlendirilir.`},{tip:`p`,metin:`Bir değişikliğin görülmesi, sistemlerin otomatik olarak yetersiz olduğu anlamına gelmez. Teknik karar, belgelendirilmiş gözlem ve uygulanabilir mevzuatla gerekçelendirilir. Gerekli özel mühendislik hesapları, tasarım veya testler kendi yetki sınırları içinde yürütülür.`},{tip:`h2`,id:`8-ygu-meslegi-hakkinda-hangi-beklentilerden-kacinilmali`,metin:`8. YGU mesleği hakkında hangi beklentilerden kaçınılmalı?`},{tip:`p`,metin:`Bütün tesislerde tam zamanlı YGU istihdamı zorunlu olacağı, her uzman için sabit bir yıllık kontrol sayısı oluşacağı veya eğitim belgesi alan herkesin doğrudan iş bulacağı yönündeki iddialar kanuni metinden çıkarılamaz.`},{tip:`p`,metin:`Aynı şekilde “periyodik kontrolün başlayacağı tarih” konusunda taslağın 1 Ocak 2028 hükmü, nihai yönetmelik yayımlanmadan kesin uygulama takvimi şeklinde sunulmamalıdır. İş ve gelir projeksiyonları, uygulama başladıktan sonra somut verilerle değerlendirilmelidir.`},{tip:`h2`,id:`sik-sorulan-sorular`,metin:`Sık sorulan sorular`},{tip:`h3`,metin:`YGU eğitimi iş garantisi sağlar mı?`},{tip:`p`,metin:`Hayır. Eğitim ve yetkilendirme, tek başına istihdam veya gelir garantisi değildir.`},{tip:`h3`,metin:`YGU dijital yazılımlarla çalışabilir mi?`},{tip:`p`,metin:`Yazılımlar belge, proje ve saha verilerini destekleyebilir; resmî uzmanlık yetkisini kendiliğinden devralmaz.`},{tip:`h3`,metin:`Bütün işyerleri YGU kadrosu açmak zorunda mı?`},{tip:`p`,metin:`Böyle genel bir zorunluluk kanuni çerçeveden çıkarılamaz.`},{tip:`h3`,metin:`YGU-K daha yüksek maaş garantisi verir mi?`},{tip:`p`,metin:`Uzmanlık seviyesinden kesin gelir sonucu üretilemez.`},{tip:`h2`,id:`sonuc`,metin:`Sonuç`},{tip:`p`,metin:`Yangın Güvenlik Uzmanlığı (YGU) mesleğinin geleceği; mevzuatın uygulanması, nitelikli eğitim, resmî kontrol süreçleri, yapıların gerçek teknik ihtiyaçları ve kayıtların güvenilirliğiyle şekillenecektir. Geleceğe yönelik değerlendirmelerin sağlam olması için kanuni hükümler, taslak önerileri ve ekonomik beklentiler açıkça ayrılmalıdır.`}],kaynakBaslik:`Kaynakça`,kaynaklar:[{metin:`3194 Sayılı İmar Kanunu`},{metin:`7579 Sayılı Tapu Kanunu ile Bazı Kanunlarda ve 375 Sayılı Kanun Hükmünde Kararnamede Değişiklik Yapılmasına Dair Kanun`},{metin:`Binaların Yangından Korunması Hakkında Yönetmelik`},{metin:`Binaların Yangından Korunması Hakkında Yönetmelik Kılavuzu`},{metin:`Yangın Güvenlik Uzmanlığı ve Periyodik Kontrol Usul ve Esasları Hakkında Yönetmelik Taslağı`}],sss:[{soru:`YGU eğitimi iş garantisi sağlar mı?`,yanit:`Hayır. Eğitim ve yetkilendirme, tek başına istihdam veya gelir garantisi değildir.`},{soru:`YGU dijital yazılımlarla çalışabilir mi?`,yanit:`Yazılımlar belge, proje ve saha verilerini destekleyebilir; resmî uzmanlık yetkisini kendiliğinden devralmaz.`},{soru:`Bütün işyerleri YGU kadrosu açmak zorunda mı?`,yanit:`Böyle genel bir zorunluluk kanuni çerçeveden çıkarılamaz.`},{soru:`YGU-K daha yüksek maaş garantisi verir mi?`,yanit:`Uzmanlık seviyesinden kesin gelir sonucu üretilemez.`}]}];export{e as EGITIM_ICERIK};